--[[
	Lumen 1.0.0 - single file build

	Generated by tools/build.js. Every module below is the original source,
	served through a synthetic instance tree so no edits are needed here.

	Keep this file in sync by running:  node tools/build.js
]]

local __modules = {}
local __cache = {}

local __nodeMeta = {
	__index = function(self, key)
		return self.__children[key]
	end,
}

local function __node(name, modulePath, parent)
	local node = setmetatable({ Name = name, __path = modulePath, Parent = parent, __children = {} }, __nodeMeta)

	if parent then
		parent.__children[name] = node
	end

	return node
end

local function __require(node)
	local cached = __cache[node]
	if cached ~= nil then
		return cached
	end

	local loader = __modules[node.__path]
	if loader == nil then
		error("[Lumen] missing module: " .. tostring(node.__path), 2)
	end

	local value = loader(node, __require)
	__cache[node] = value

	return value
end

local __root = __node("Lumen", "init", nil)
local __node_Components = __node("Components", "Components", __root)
local __node_Core = __node("Core", "Core", __root)
local __node_Components_Button = __node("Button", "Components/Button", __node_Components)
local __node_Components_ColorPicker = __node("ColorPicker", "Components/ColorPicker", __node_Components)
local __node_Components_Divider = __node("Divider", "Components/Divider", __node_Components)
local __node_Components_Dropdown = __node("Dropdown", "Components/Dropdown", __node_Components)
local __node_Components_Icon = __node("Icon", "Components/Icon", __node_Components)
local __node_Components_Input = __node("Input", "Components/Input", __node_Components)
local __node_Components_Keybind = __node("Keybind", "Components/Keybind", __node_Components)
local __node_Components_Notification = __node("Notification", "Components/Notification", __node_Components)
local __node_Components_Paragraph = __node("Paragraph", "Components/Paragraph", __node_Components)
local __node_Components_Section = __node("Section", "Components/Section", __node_Components)
local __node_Components_Slider = __node("Slider", "Components/Slider", __node_Components)
local __node_Components_Tab = __node("Tab", "Components/Tab", __node_Components)
local __node_Components_Toggle = __node("Toggle", "Components/Toggle", __node_Components)
local __node_Components_Tooltip = __node("Tooltip", "Components/Tooltip", __node_Components)
local __node_Components_Window = __node("Window", "Components/Window", __node_Components)
local __node_Core_Config = __node("Config", "Core/Config", __node_Core)
local __node_Core_Effects = __node("Effects", "Core/Effects", __node_Core)
local __node_Core_Element = __node("Element", "Core/Element", __node_Core)
local __node_Core_Icons = __node("Icons", "Core/Icons", __node_Core)
local __node_Core_Maid = __node("Maid", "Core/Maid", __node_Core)
local __node_Core_Motion = __node("Motion", "Core/Motion", __node_Core)
local __node_Core_Scroll = __node("Scroll", "Core/Scroll", __node_Core)
local __node_Core_Signal = __node("Signal", "Core/Signal", __node_Core)
local __node_Core_Theme = __node("Theme", "Core/Theme", __node_Core)
local __node_Core_Util = __node("Util", "Core/Util", __node_Core)

__modules["Components/Button"] = function(script, require)
 --[[
 	Button
 	Row with a compact action button. Hover runs a sheen across the surface and
 	clicks emit a ripple from the pointer, so the control reads as a physical
 	object rather than a rectangle that changes colour.
 ]]

 local Config = require(script.Parent.Parent.Core.Config)
 local Effects = require(script.Parent.Parent.Core.Effects)
 local Element = require(script.Parent.Parent.Core.Element)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Icon = require(script.Parent.Icon)

 local Button = setmetatable({}, { __index = Element })
 Button.__index = Button

 function Button.new(section, options)
 	options = options or {}

 	local self = Element.new(Button, section, options, {
 		ControlWidth = options.Width or (options.Icon and 124 or 104),
 		ControlHeight = Config.Metrics.ControlHeight,
 	})

 	local button = Util.Create("TextButton", {
 		Name = "Button",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		AutoButtonColor = false,
 		BackgroundColor3 = Theme.Palette.Control,
 		BorderSizePixel = 0,
 		ClipsDescendants = true,
 		Position = UDim2.fromScale(0.5, 0.5),
 		Size = UDim2.fromScale(1, 1),
 		Text = "",
 		TextTransparency = 1,
 		Parent = self.Control,
 	})
 	Util.Corner(button, Config.Radius.Control)

 	local holder = Util.Create("Frame", {
 		Name = "Content",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		AutomaticSize = Enum.AutomaticSize.X,
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.fromScale(0.5, 0.5),
 		Size = UDim2.new(0, 0, 1, 0),
 		Parent = button,
 	})
 	local layout = Util.List(holder, 6, true)
 	layout.VerticalAlignment = Enum.VerticalAlignment.Center

 	local icon = nil
 	if options.Icon then
 		icon = Icon.new(holder, options.Icon, Config.Icons.SliderSize + 2, "Text")
 	end

 	local label = Util.Create("TextLabel", {
 		Name = "Label",
 		BackgroundTransparency = 1,
 		Font = Config.Font.Medium,
 		Size = UDim2.new(0, 0, 0, 16),
 		AutomaticSize = Enum.AutomaticSize.X,
 		Text = options.Text or "Click",
 		TextSize = Config.TextSize.Control,
 		TextXAlignment = Enum.TextXAlignment.Center,
 		TextYAlignment = Enum.TextYAlignment.Center,
 		Parent = holder,
 	})
 	Theme.Bind(label, "TextColor3", "Text")

 	local sheen = Effects.Sheen(button, { Color = Theme.Palette.Text })

 	local hovering = false
 	local pressing = false

 	local function paint()
 		Theme.Bind(button, "BackgroundColor3", hovering and "ControlHover" or "Control")

 		Motion.Spring(button, "BackgroundTransparency", pressing and 0.12 or 0, {
 			Stiffness = Config.Motion.Hover.Stiffness,
 			Damping = Config.Motion.Hover.Damping,
 		})
 	end

 	button.MouseEnter:Connect(function()
 		hovering = true
 		paint()
 		sheen.Play()
 	end)

 	button.MouseLeave:Connect(function()
 		hovering = false
 		pressing = false
 		paint()
 	end)

 	button.InputBegan:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
 			return
 		end

 		pressing = true
 		paint()

 		if self.Enabled then
 			Effects.Ripple(button, {
 				X = input.Position.X - button.AbsolutePosition.X,
 				Y = input.Position.Y - button.AbsolutePosition.Y,
 				Color = Theme.Palette.Text,
 			})
 		end
 	end)

 	button.InputEnded:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
 			pressing = false
 			paint()
 		end
 	end)

 	button.MouseButton1Click:Connect(function()
 		if not self.Enabled then
 			return
 		end

 		self:Fire(nil)
 	end)

 	self.Maid:Add(Theme.Changed:Connect(paint))
 	self.Button = button
 	self.Label = label
 	self.Icon = icon
 	self.Holder = holder

 	paint()

 	self:SetHoverable(true)
 	return self
 end

 function Button:SetText(text)
 	self.Label.Text = tostring(text)
 end

 function Button:SetIcon(glyph)
 	if self.Icon == nil then
 		return
 	end

 	if Icon.HasGlyph(glyph) then
 		self.Icon:SetGlyph(glyph)
 	else
 		self.Icon.Container.Visible = false
 	end
 end

 function Button:SetControlEnabled(enabled)
 	self.Button.Active = enabled

 	Motion.Spring(self.Label, "TextTransparency", enabled and 0 or 0.45, {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	})

 	if self.Icon then
 		self.Icon:SetTransparency(enabled and 0 or 0.45)
 	end
 end

 return Button
end

__modules["Components/ColorPicker"] = function(script, require)
 --[[
 	ColorPicker
 	Swatch row that opens a saturation / value pad with a hue strip and a hex
 	field. Hue, saturation and value are kept as the source of truth so pure
 	black or white never lose their hue.
 ]]

 local UserInputService = game:GetService("UserInputService")

 local Config = require(script.Parent.Parent.Core.Config)
 local Element = require(script.Parent.Parent.Core.Element)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local ColorPicker = setmetatable({}, { __index = Element })
 ColorPicker.__index = ColorPicker

 local MENU_WIDTH = 212
 local PAD = 10
 local SV_HEIGHT = 122
 local HUE_HEIGHT = 12
 local FIELD_HEIGHT = 26
 local GAP = 12

 local HEX_DIGITS = "0123456789ABCDEF"

 local function toHex(color)
 	local function channel(value)
 		local index = math.clamp(math.floor(value * 255 + 0.5), 0, 255)
 		local high = math.floor(index / 16) + 1
 		local low = (index % 16) + 1
 		return string.sub(HEX_DIGITS, high, high) .. string.sub(HEX_DIGITS, low, low)
 	end

 	return "#" .. channel(color.R) .. channel(color.G) .. channel(color.B)
 end

 local function fromHex(text)
 	local cleaned = string.upper((string.gsub(tostring(text), "#", "")))
 	if #cleaned ~= 6 or string.find(cleaned, "[^0-9A-F]") then
 		return nil
 	end

 	return Color3.fromRGB(
 		tonumber(string.sub(cleaned, 1, 2), 16),
 		tonumber(string.sub(cleaned, 3, 4), 16),
 		tonumber(string.sub(cleaned, 5, 6), 16)
 	)
 end

 function ColorPicker.new(section, options)
 	options = options or {}

 	local self = Element.new(ColorPicker, section, options, {
 		ControlWidth = options.Width or 46,
 		ControlHeight = 24,
 	})

 	local initial = options.Default or Color3.fromRGB(76, 141, 255)
 	local hue, saturation, value = Color3.toHSV(initial)

 	self.Hue = hue
 	self.Sat = saturation
 	self.Val = value
 	self.Value = Color3.fromHSV(hue, saturation, value)
 	self.Open = false

 	-------------------------------------------------------------------------
 	-- Swatch
 	-------------------------------------------------------------------------

 	local swatch = Util.Create("TextButton", {
 		Name = "Swatch",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		AutoButtonColor = false,
 		BackgroundColor3 = self.Value,
 		BorderSizePixel = 0,
 		Position = UDim2.fromScale(0.5, 0.5),
 		Size = UDim2.fromScale(1, 1),
 		Text = "",
 		TextTransparency = 1,
 		Parent = self.Control,
 	})
 	Util.Corner(swatch, Config.Radius.Control)
 	Theme.Bind(Util.Stroke(swatch, Theme.Palette.Outline, 1, 0.25), "Color", "Outline")

 	self.Swatch = swatch

 	-------------------------------------------------------------------------
 	-- Menu
 	-------------------------------------------------------------------------

 	local menuHeight = PAD * 2 + SV_HEIGHT + GAP + HUE_HEIGHT + GAP + FIELD_HEIGHT

 	local menu = Util.Create("Frame", {
 		Name = "ColorMenu",
 		BackgroundColor3 = Theme.Palette.Surface,
 		BorderSizePixel = 0,
 		ClipsDescendants = true,
 		Size = UDim2.fromOffset(MENU_WIDTH, 0),
 		Visible = false,
 		ZIndex = 22,
 		Parent = section.Window.Overlay,
 	})
 	Util.Corner(menu, Config.Radius.Card)
 	Theme.Bind(menu, "BackgroundColor3", "Surface")
 	Theme.Bind(Util.Stroke(menu, Theme.Palette.Outline, 1, 0.25), "Color", "Outline")

 	local pad = Util.Create("Frame", {
 		Name = "Pad",
 		BackgroundColor3 = Color3.new(1, 1, 1),
 		BorderSizePixel = 0,
 		Position = UDim2.fromOffset(PAD, PAD),
 		Size = UDim2.new(1, -(PAD * 2), 0, SV_HEIGHT),
 		Parent = menu,
 	})
 	Util.Corner(pad, Config.Radius.Small)

 	local whiteFade = Util.Create("Frame", {
 		Name = "WhiteFade",
 		BackgroundColor3 = Color3.new(1, 1, 1),
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		ZIndex = 2,
 		Parent = pad,
 	})
 	Util.Corner(whiteFade, Config.Radius.Small)
 	Util.Create("UIGradient", {
 		Rotation = 0,
 		Transparency = NumberSequence.new({
 			NumberSequenceKeypoint.new(0, 0),
 			NumberSequenceKeypoint.new(1, 1),
 		}),
 		Parent = whiteFade,
 	})

 	local blackFade = Util.Create("Frame", {
 		Name = "BlackFade",
 		BackgroundColor3 = Color3.new(0, 0, 0),
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		ZIndex = 3,
 		Parent = pad,
 	})
 	Util.Corner(blackFade, Config.Radius.Small)
 	Util.Create("UIGradient", {
 		Rotation = 90,
 		Transparency = NumberSequence.new({
 			NumberSequenceKeypoint.new(0, 1),
 			NumberSequenceKeypoint.new(1, 0),
 		}),
 		Parent = blackFade,
 	})

 	local padHit = Util.Create("Frame", {
 		Name = "Hit",
 		Active = true,
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		ZIndex = 5,
 		Parent = pad,
 	})

 	local cursorRing = Util.Create("Frame", {
 		Name = "Cursor",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromOffset(16, 16),
 		ZIndex = 6,
 		Parent = pad,
 	})
 	Theme.Bind(Util.Stroke(cursorRing, Theme.Palette.Window, 2, 0.15), "Color", "Window")

 	local cursorDot = Util.Create("Frame", {
 		Name = "Dot",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.fromScale(0.5, 0.5),
 		Size = UDim2.fromOffset(12, 12),
 		ZIndex = 6,
 		Parent = cursorRing,
 	})
 	Util.Create("UIStroke", {
 		Color = Color3.new(1, 1, 1),
 		Thickness = 2,
 		Transparency = 0,
 		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
 		Parent = cursorDot,
 	})

 	local hueSequence = ColorSequence.new({
 		ColorSequenceKeypoint.new(0 / 6, Color3.fromHSV(0 / 6, 1, 1)),
 		ColorSequenceKeypoint.new(1 / 6, Color3.fromHSV(1 / 6, 1, 1)),
 		ColorSequenceKeypoint.new(2 / 6, Color3.fromHSV(2 / 6, 1, 1)),
 		ColorSequenceKeypoint.new(3 / 6, Color3.fromHSV(3 / 6, 1, 1)),
 		ColorSequenceKeypoint.new(4 / 6, Color3.fromHSV(4 / 6, 1, 1)),
 		ColorSequenceKeypoint.new(5 / 6, Color3.fromHSV(5 / 6, 1, 1)),
 		ColorSequenceKeypoint.new(1, Color3.fromHSV(1, 1, 1)),
 	})

 	local hueBar = Util.Create("Frame", {
 		Name = "Hue",
 		BackgroundColor3 = Color3.new(1, 0, 0),
 		BorderSizePixel = 0,
 		Position = UDim2.fromOffset(PAD, PAD + SV_HEIGHT + GAP),
 		Size = UDim2.new(1, -(PAD * 2), 0, HUE_HEIGHT),
 		Parent = menu,
 	})
 	Util.Corner(hueBar, HUE_HEIGHT / 2)
 	Util.Create("UIGradient", {
 		Rotation = 0,
 		Color = hueSequence,
 		Parent = hueBar,
 	})

 	local hueHit = Util.Create("Frame", {
 		Name = "Hit",
 		Active = true,
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.new(1, 0, 1, 8),
 		Position = UDim2.new(0, 0, 0, -4),
 		ZIndex = 5,
 		Parent = hueBar,
 	})

 	local hueCursor = Util.Create("Frame", {
 		Name = "Cursor",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		BackgroundColor3 = Color3.new(1, 1, 1),
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, 0, 0.5, 0),
 		Size = UDim2.fromOffset(4, HUE_HEIGHT + 6),
 		ZIndex = 6,
 		Parent = hueBar,
 	})
 	Util.Corner(hueCursor, 2)
 	Util.Create("UIStroke", {
 		Color = Color3.new(0, 0, 0),
 		Thickness = 1,
 		Transparency = 0.6,
 		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
 		Parent = hueCursor,
 	})

 	local hexField = Util.Create("Frame", {
 		Name = "HexField",
 		BackgroundColor3 = Theme.Palette.Control,
 		BorderSizePixel = 0,
 		Position = UDim2.fromOffset(PAD, PAD + SV_HEIGHT + GAP + HUE_HEIGHT + GAP),
 		Size = UDim2.new(1, -(PAD * 2), 0, FIELD_HEIGHT),
 		Parent = menu,
 	})
 	Util.Corner(hexField, Config.Radius.Control)
 	Theme.Bind(hexField, "BackgroundColor3", "Control")

 	local hexStroke = Util.Stroke(hexField, Theme.Palette.Outline, 1, 0.4)
 	Theme.Bind(hexStroke, "Color", "Outline")

 	local hexBox = Util.Create("TextBox", {
 		Name = "Box",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		BackgroundTransparency = 1,
 		ClearTextOnFocus = false,
 		Font = Config.Font.Mono,
 		Position = UDim2.fromScale(0.5, 0.5),
 		Size = UDim2.new(1, -20, 1, 0),
 		Text = toHex(self.Value),
 		TextColor3 = Theme.Palette.Text,
 		TextSize = Config.TextSize.Control,
 		TextXAlignment = Enum.TextXAlignment.Left,
 		TextYAlignment = Enum.TextYAlignment.Center,
 		Parent = hexField,
 	})
 	Theme.Bind(hexBox, "TextColor3", "Text")

 	self.Menu = menu
 	self.MenuWidth = MENU_WIDTH
 	self.MenuHeight = menuHeight
 	self.Pad = pad
 	self.HexBox = hexBox
 	self.HexStroke = hexStroke
 	self.MenuProgress = 0

 	-------------------------------------------------------------------------
 	-- Rendering
 	-------------------------------------------------------------------------

 	local suppressHex = false

 	function self.render()
 		local color = Color3.fromHSV(self.Hue, self.Sat, self.Val)

 		pad.BackgroundColor3 = Color3.fromHSV(self.Hue, 1, 1)
 		cursorRing.Position = UDim2.fromScale(self.Sat, 1 - self.Val)
 		hueCursor.Position = UDim2.new(self.Hue, 0, 0.5, 0)
 		swatch.BackgroundColor3 = color

 		if not hexBox:IsFocused() then
 			suppressHex = true
 			hexBox.Text = toHex(color)
 			suppressHex = false
 		end

 		return color
 	end

 	local function apply(fire)
 		self.Value = self.render()

 		if fire then
 			self:Fire(self.Value)
 		end
 	end

 	-------------------------------------------------------------------------
 	-- Pad and hue dragging
 	-------------------------------------------------------------------------

 	local dragging = nil
 	local moveConnection = nil

 	local function stopDragging()
 		dragging = nil
 		if moveConnection then
 			moveConnection:Disconnect()
 			moveConnection = nil
 		end
 	end

 	local function updateFromPad(x, y)
 		local position = pad.AbsolutePosition
 		local size = pad.AbsoluteSize

 		self.Sat = Util.Clamp((x - position.X) / math.max(1, size.X), 0, 1)
 		self.Val = 1 - Util.Clamp((y - position.Y) / math.max(1, size.Y), 0, 1)

 		apply(true)
 	end

 	local function updateFromHue(x)
 		local position = hueBar.AbsolutePosition
 		local size = hueBar.AbsoluteSize

 		self.Hue = Util.Clamp((x - position.X) / math.max(1, size.X), 0, 1)

 		apply(true)
 	end

 	padHit.InputBegan:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
 			return
 		end

 		dragging = "pad"
 		updateFromPad(input.Position.X, input.Position.Y)

 		if moveConnection then
 			moveConnection:Disconnect()
 		end
 		moveConnection = UserInputService.InputChanged:Connect(function(moved)
 			if dragging ~= "pad" then
 				return
 			end

 			local movedType = moved.UserInputType
 			if movedType == Enum.UserInputType.MouseMovement or movedType == Enum.UserInputType.Touch then
 				updateFromPad(moved.Position.X, moved.Position.Y)
 			end
 		end)
 	end)

 	hueHit.InputBegan:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
 			return
 		end

 		dragging = "hue"
 		updateFromHue(input.Position.X)

 		if moveConnection then
 			moveConnection:Disconnect()
 		end
 		moveConnection = UserInputService.InputChanged:Connect(function(moved)
 			if dragging ~= "hue" then
 				return
 			end

 			local movedType = moved.UserInputType
 			if movedType == Enum.UserInputType.MouseMovement or movedType == Enum.UserInputType.Touch then
 				updateFromHue(moved.Position.X)
 			end
 		end)
 	end)

 	self.Maid:Add(stopDragging)

 	self.Maid:Add(UserInputService.InputEnded:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
 			stopDragging()
 		end
 	end))

 	-------------------------------------------------------------------------
 	-- Hex field
 	-------------------------------------------------------------------------

 	hexBox.Focused:Connect(function()
 		Theme.Bind(hexStroke, "Color", "Accent")
 		Util.Tween(hexStroke, { Transparency = 0 }, Util.Easing.Fast)
 	end)

 	hexBox.FocusLost:Connect(function(enterPressed)
 		Theme.Bind(hexStroke, "Color", "Outline")
 		Util.Tween(hexStroke, { Transparency = 0.4 }, Util.Easing.Fast)

 		if suppressHex then
 			return
 		end

 		local parsed = fromHex(hexBox.Text)
 		if parsed then
 			self:SetValue(parsed)
 		else
 			self.render()
 		end

 		if enterPressed then
 			hexBox:ReleaseFocus()
 		end
 	end)

 	-------------------------------------------------------------------------
 	-- Open / close
 	-------------------------------------------------------------------------

 	local outsideConnection = nil

 	local function disconnectOutside()
 		if outsideConnection then
 			outsideConnection:Disconnect()
 			outsideConnection = nil
 		end
 	end

 	local function animateMenu(target, onComplete)
 		Motion.Spring(self, "MenuProgress", target, {
 			Stiffness = Config.Motion.Menu.Stiffness,
 			Damping = Config.Motion.Menu.Damping,
 			OnUpdate = function(value)
 				menu.Size = UDim2.fromOffset(MENU_WIDTH, math.max(0, value))
 			end,
 			OnComplete = onComplete,
 		})
 	end

 	local function close()
 		if not self.Open then
 			return
 		end

 		self.Open = false
 		disconnectOutside()
 		section.Window:ClosePopup(self)

 		animateMenu(0, function()
 			if not self.Open then
 				menu.Visible = false
 			end
 		end)
 	end

 	local function positionMenu()
 		if not self.Open then
 			return
 		end

 		local window = section.Window.Frame
 		local control = self.Control
 		local scale = math.max(0.05, section.Window.Scale.Scale)
 		local x = (control.AbsolutePosition.X - window.AbsolutePosition.X + control.AbsoluteSize.X) / scale - MENU_WIDTH
 		local y = (control.AbsolutePosition.Y - window.AbsolutePosition.Y + control.AbsoluteSize.Y) / scale
 			+ Config.Metrics.PopupGap
 		local windowSize = Vector2.new(window.AbsoluteSize.X / scale, window.AbsoluteSize.Y / scale)
 		local margin = Config.Metrics.PopupMargin

 		if y + menuHeight > windowSize.Y - margin then
 			y = (control.AbsolutePosition.Y - window.AbsolutePosition.Y) / scale - menuHeight - Config.Metrics.PopupGap
 		end

 		menu.Position = UDim2.fromOffset(
 			math.clamp(x, margin, math.max(margin, windowSize.X - MENU_WIDTH - margin)),
 			math.clamp(y, margin, math.max(margin, windowSize.Y - menuHeight - margin))
 		)
 	end

 	local function open()
 		if self.Open or not self.Enabled then
 			return
 		end

 		section.Window:OpenPopup(self)
 		self.Open = true

 		positionMenu()
 		menu.Size = UDim2.fromOffset(MENU_WIDTH, 0)
 		menu.Visible = true

 		animateMenu(menuHeight)

 		task.defer(function()
 			if not self.Open then
 				return
 			end

 			outsideConnection = UserInputService.InputBegan:Connect(function(input)
 				local inputType = input.UserInputType
 				if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
 					return
 				end

 				local point = Vector2.new(input.Position.X, input.Position.Y)
 				if Util.IsInside(menu, point) or Util.IsInside(swatch, point) then
 					return
 				end

 				close()
 			end)
 		end)
 	end

 	swatch.MouseButton1Click:Connect(function()
 		if self.Open then
 			close()
 		else
 			open()
 		end
 	end)

 	self.Maid:Add(disconnectOutside)
 	self.Maid:Add(function()
 		menu:Destroy()
 	end)
 	self.Maid:Add(close)

 	self.render()
 	self.open = open
 	self.close = close
 	self.Reposition = positionMenu

 	self:SetHoverable(true)
 	return self
 end

 function ColorPicker:GetValue()
 	return self.Value
 end

 function ColorPicker:SetValue(color, silent)
 	if typeof(color) ~= "Color3" then
 		return
 	end

 	local hue, saturation, value = Color3.toHSV(color)

 	self.Hue = hue
 	self.Sat = saturation
 	self.Val = value
 	self.Value = self.render()

 	if not silent then
 		self:Fire(self.Value)
 	end
 end

 --- Closes the floating palette. Mirrors Dropdown:Hide for popup coordination.
 function ColorPicker:Hide()
 	if self.close then
 		self.close()
 	end
 end

 function ColorPicker:SetControlEnabled(enabled)
 	self.Swatch.Active = enabled
 	Util.Tween(self.Swatch, { BackgroundTransparency = enabled and 0 or 0.55 }, Util.Easing.Fast)

 	if not enabled then
 		self:Hide()
 	end
 end

 return ColorPicker
end

__modules["Components/Divider"] = function(script, require)
 --[[
 	Divider
 	Labelled hairline used to break a long card into named groups.
 ]]

 local Config = require(script.Parent.Parent.Core.Config)
 local Element = require(script.Parent.Parent.Core.Element)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Divider = setmetatable({}, { __index = Element })
 Divider.__index = Divider

 local HEIGHT = 28
 local LABEL_PADDING = 6

 function Divider.new(section, options)
 	options = options or {}

 	local elementOptions = table.clone(options)
 	elementOptions.Name = nil

 	local self = Element.new(Divider, section, elementOptions, {
 		Height = HEIGHT,
 		Separator = false,
 	})

 	local line = Util.Create("Frame", {
 		Name = "Line",
 		AnchorPoint = Vector2.new(0, 0.5),
 		BackgroundColor3 = Theme.Palette.Divider,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, 0, 0.5, 0),
 		Size = UDim2.new(1, 0, 0, 1),
 		Parent = self.Row,
 	})
 	Theme.Bind(line, "BackgroundColor3", "Divider")

 	self.Line = line

 	if options.Name ~= nil then
 		local text = tostring(options.Name)
 		local textWidth = math.ceil(Util.MeasureText(text, Config.TextSize.Badge, Config.Font.Bold))

 		local holder = Util.Create("Frame", {
 			Name = "LabelHolder",
 			AnchorPoint = Vector2.new(0, 0.5),
 			BackgroundColor3 = Theme.Palette.Surface,
 			BorderSizePixel = 0,
 			Position = UDim2.new(0, 0, 0.5, 0),
 			Size = UDim2.fromOffset(textWidth + LABEL_PADDING * 2, 16),
 			Parent = self.Row,
 		})
 		Theme.Bind(holder, "BackgroundColor3", "Surface")

 		local label = Util.Create("TextLabel", {
 			Name = "Label",
 			BackgroundTransparency = 1,
 			Font = Config.Font.Bold,
 			Position = UDim2.fromOffset(LABEL_PADDING, 0),
 			Size = UDim2.new(0, textWidth, 1, 0),
 			Text = text,
 			TextSize = Config.TextSize.Badge,
 			TextXAlignment = Enum.TextXAlignment.Left,
 			TextYAlignment = Enum.TextYAlignment.Center,
 			Parent = holder,
 		})
 		Theme.Bind(label, "TextColor3", "TextDim")

 		self.Holder = holder
 		self.Label = label
 	end

 	return self
 end

 return Divider
end

__modules["Components/Dropdown"] = function(script, require)
 --[[
 	Dropdown
 	Single or multi select list.

 	The menu is parented to the window overlay so it is never clipped by the
 	scroll canvas, and it flips above the row when there is not enough room
 	underneath. Opening springs the menu open and staggers the option labels in.
 ]]

 local UserInputService = game:GetService("UserInputService")

 local Config = require(script.Parent.Parent.Core.Config)
 local Element = require(script.Parent.Parent.Core.Element)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Scroll = require(script.Parent.Parent.Core.Scroll)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Icon = require(script.Parent.Icon)

 local Dropdown = setmetatable({}, { __index = Element })
 Dropdown.__index = Dropdown

 local FIELD_HEIGHT = 26
 local ITEM_HEIGHT = 26
 local MENU_PADDING = 4
 local ITEM_STAGGER = 0.014

 function Dropdown.new(section, options)
 	options = options or {}

 	local self = Element.new(Dropdown, section, options, {
 		ControlWidth = options.Width or 156,
 		ControlHeight = FIELD_HEIGHT,
 	})

 	self.Items = {}
 	self.Multi = options.Multi == true
 	self.MaxVisible = math.max(1, options.MaxVisible or 6)
 	self.Searchable = options.Searchable == true
 	self.Open = false
 	self.MenuProgress = 0

 	for _, item in ipairs(options.Items or {}) do
 		table.insert(self.Items, tostring(item))
 	end

 	self.Selection = {}

 	-------------------------------------------------------------------------
 	-- Selector
 	-------------------------------------------------------------------------

 	local selector = Util.Create("TextButton", {
 		Name = "Selector",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		AutoButtonColor = false,
 		BackgroundColor3 = Theme.Palette.Control,
 		BorderSizePixel = 0,
 		Position = UDim2.fromScale(0.5, 0.5),
 		Size = UDim2.fromScale(1, 1),
 		Text = "",
 		TextTransparency = 1,
 		Parent = self.Control,
 	})
 	Util.Corner(selector, Config.Radius.Control)
 	Theme.Bind(selector, "BackgroundColor3", "Control")

 	local selectorStroke = Util.Stroke(selector, Theme.Palette.Outline, 1, 0.4)

 	local valueLabel = Util.Create("TextLabel", {
 		Name = "Value",
 		AnchorPoint = Vector2.new(0, 0.5),
 		BackgroundTransparency = 1,
 		Font = Config.Font.Medium,
 		Position = UDim2.new(0, 10, 0.5, 0),
 		Size = UDim2.new(1, -32, 1, 0),
 		Text = "",
 		TextSize = Config.TextSize.Control,
 		TextTruncate = Enum.TextTruncate.AtEnd,
 		TextXAlignment = Enum.TextXAlignment.Left,
 		Parent = selector,
 	})
 	Theme.Bind(valueLabel, "TextColor3", "Text")

 	local chevron = Icon.new(selector, "chevron-down", Config.Icons.ChevronSize, "TextMuted")
 	chevron.Container.AnchorPoint = Vector2.new(1, 0.5)
 	chevron.Container.Position = UDim2.new(1, -9, 0.5, 0)

 	-------------------------------------------------------------------------
 	-- Menu
 	-------------------------------------------------------------------------

 	local menu = Util.Create("Frame", {
 		Name = "Menu",
 		BackgroundColor3 = Theme.Palette.Surface,
 		BorderSizePixel = 0,
 		ClipsDescendants = true,
 		Position = UDim2.fromOffset(0, 0),
 		Size = UDim2.fromOffset(0, 0),
 		Visible = false,
 		ZIndex = 22,
 		Parent = section.Window.Overlay,
 	})
 	Util.Corner(menu, Config.Radius.Card)
 	Theme.Bind(menu, "BackgroundColor3", "Surface")
 	Theme.Bind(Util.Stroke(menu, Theme.Palette.Outline, 1, 0.25), "Color", "Outline")

 	local searchBox = nil
 	if self.Searchable then
 		local searchField = Util.Create("Frame", {
 			Name = "SearchField",
 			BackgroundColor3 = Theme.Palette.Control,
 			BorderSizePixel = 0,
 			Position = UDim2.fromOffset(MENU_PADDING, MENU_PADDING),
 			Size = UDim2.new(1, -(MENU_PADDING * 2), 0, FIELD_HEIGHT),
 			Parent = menu,
 		})
 		Util.Corner(searchField, Config.Radius.Control)
 		Theme.Bind(searchField, "BackgroundColor3", "Control")

 		local searchIcon = Icon.new(searchField, "search", Config.Icons.SearchSize, "TextDim")
 		searchIcon.Container.AnchorPoint = Vector2.new(0, 0.5)
 		searchIcon.Container.Position = UDim2.new(0, 8, 0.5, 0)

 		searchBox = Util.Create("TextBox", {
 			Name = "Box",
 			AnchorPoint = Vector2.new(0.5, 0.5),
 			BackgroundTransparency = 1,
 			ClearTextOnFocus = false,
 			Font = Config.Font.Medium,
 			PlaceholderColor3 = Theme.Palette.TextDim,
 			PlaceholderText = "Search",
 			Position = UDim2.fromScale(0.5, 0.5),
 			Size = UDim2.new(1, -28, 1, 0),
 			Text = "",
 			TextColor3 = Theme.Palette.Text,
 			TextSize = Config.TextSize.Control,
 			TextXAlignment = Enum.TextXAlignment.Left,
 			TextYAlignment = Enum.TextYAlignment.Center,
 			Parent = searchField,
 		})
 		Theme.Bind(searchBox, "TextColor3", "Text")
 		Theme.Bind(searchBox, "PlaceholderColor3", "TextDim")
 	end

 	local listTop = self.Searchable and (MENU_PADDING * 2 + FIELD_HEIGHT) or MENU_PADDING
 	local listHeight = self.MaxVisible * ITEM_HEIGHT

 	local listArea = Util.Create("Frame", {
 		Name = "ListArea",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.fromOffset(MENU_PADDING, listTop),
 		Size = UDim2.new(1, -(MENU_PADDING * 2), 0, listHeight),
 		Parent = menu,
 	})

 	local scroll = Scroll.new(listArea, {
 		Padding = { Top = 0, Right = 10, Bottom = 0, Left = 4 },
 		Spacing = 2,
 	})

 	local menuWidth = options.MenuWidth or math.max(options.Width or 156, 176)
 	local menuHeight = listTop + listHeight + MENU_PADDING

 	self.Selector = selector
 	self.SelectorLabel = valueLabel
 	self.Chevron = chevron
 	self.Menu = menu
 	self.Scroll = scroll
 	self.MenuWidth = menuWidth
 	self.MenuHeight = menuHeight
 	self.ItemHeight = ITEM_HEIGHT

 	-------------------------------------------------------------------------
 	-- Rendering
 	-------------------------------------------------------------------------

 	local function selectedList()
 		local list = {}

 		for _, item in ipairs(self.Items) do
 			if self.Selection[item] then
 				table.insert(list, item)
 			end
 		end

 		return list
 	end

 	local function renderSelector()
 		local selected = selectedList()
 		local placeholder = options.Placeholder or (self.Multi and "Select options" or "Select an option")

 		if #selected == 0 then
 			valueLabel.Text = placeholder
 			Theme.Bind(valueLabel, "TextColor3", "TextDim")
 		elseif self.Multi and #selected > 2 then
 			valueLabel.Text = ("%d selected"):format(#selected)
 			Theme.Bind(valueLabel, "TextColor3", "Text")
 		else
 			valueLabel.Text = table.concat(selected, ", ")
 			Theme.Bind(valueLabel, "TextColor3", "Text")
 		end
 	end

 	-- Row pool. Rows are created lazily and then reused: selecting an item or
 	-- typing in the search box only rewrites text / marker / visibility on the
 	-- existing rows instead of destroying and rebuilding the whole list. Event
 	-- handlers are connected once per slot and read `slot.Item`, so a slot can be
 	-- rebound to a different item without reconnecting anything.
 	local rowPool = {}
 	local emptyLabel = nil

 	-- Spring options are read-only inside Motion, so one shared table is enough.
 	local HOVER_SPRING = {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	}

 	local function createSlot()
 		local slot = { Item = nil, Selected = false }

 		local row = Util.Create("TextButton", {
 			Name = "Item",
 			AutoButtonColor = false,
 			BackgroundColor3 = Theme.Palette.SurfaceHover,
 			BackgroundTransparency = 1,
 			BorderSizePixel = 0,
 			Size = UDim2.new(1, 0, 0, ITEM_HEIGHT),
 			Text = "",
 			TextTransparency = 1,
 			Visible = false,
 			Parent = scroll.Content,
 		})
 		Util.Corner(row, Config.Radius.Small)
 		Theme.Bind(row, "BackgroundColor3", "SurfaceHover")

 		local marker = Util.Create("Frame", {
 			Name = "Marker",
 			AnchorPoint = Vector2.new(0, 0.5),
 			BackgroundColor3 = Theme.Palette.Accent,
 			BorderSizePixel = 0,
 			Position = UDim2.new(0, 2, 0.5, 0),
 			Size = UDim2.fromOffset(2, 12),
 			Visible = false,
 			Parent = row,
 		})
 		Util.Corner(marker, 1)
 		Theme.Bind(marker, "BackgroundColor3", "Accent")

 		local label = Util.Create("TextLabel", {
 			Name = "Label",
 			BackgroundTransparency = 1,
 			Font = Config.Font.Medium,
 			Position = UDim2.fromOffset(10, 0),
 			Size = UDim2.new(1, -16, 1, 0),
 			Text = "",
 			TextSize = Config.TextSize.Control,
 			TextTruncate = Enum.TextTruncate.AtEnd,
 			TextXAlignment = Enum.TextXAlignment.Left,
 			Parent = row,
 		})
 		Theme.Bind(label, "TextColor3", "Text")

 		slot.Row = row
 		slot.Marker = marker
 		slot.Label = label

 		row.MouseEnter:Connect(function()
 			-- Label leads the highlight by a hair, matching the sidebar tabs.
 			Motion.Spring(label, "Position", UDim2.fromOffset(13, 0), HOVER_SPRING)

 			if not slot.Selected then
 				Motion.Spring(row, "BackgroundTransparency", 0.4, HOVER_SPRING)
 			end
 		end)

 		row.MouseLeave:Connect(function()
 			Motion.Spring(label, "Position", UDim2.fromOffset(10, 0), HOVER_SPRING)

 			if not slot.Selected then
 				Motion.Spring(row, "BackgroundTransparency", 1, HOVER_SPRING)
 			end
 		end)

 		row.MouseButton1Click:Connect(function()
 			local item = slot.Item
 			if item ~= nil then
 				self:Toggle(item)
 			end
 		end)

 		return slot
 	end

 	-- Writes only what changed onto an existing slot.
 	local function bindSlot(slot, item, index, stagger)
 		local selected = self.Selection[item] == true
 		local row, marker, label = slot.Row, slot.Marker, slot.Label
 		local rebound = slot.Item ~= item

 		slot.Item = item

 		if rebound then
 			-- A recycled row may still be mid-hover for its previous item.
 			Motion.Cancel(label, "Position")
 			Motion.Cancel(label, "TextTransparency")
 			Motion.Cancel(row, "BackgroundTransparency")
 			label.Position = UDim2.fromOffset(10, 0)
 			label.Text = item
 		end

 		if row.LayoutOrder ~= index then
 			row.LayoutOrder = index
 		end

 		if not row.Visible then
 			row.Visible = true
 		end

 		if marker.Visible ~= selected then
 			marker.Visible = selected
 		end

 		if slot.Selected ~= selected or rebound then
 			slot.Selected = selected

 			Theme.Bind(label, "TextColor3", selected and "Accent" or "Text")

 			Motion.Cancel(row, "BackgroundTransparency")
 			if selected then
 				Theme.Bind(row, "BackgroundColor3", "AccentSoft")
 				row.BackgroundTransparency = 0.15
 			else
 				Theme.Bind(row, "BackgroundColor3", "SurfaceHover")
 				row.BackgroundTransparency = 1
 			end
 		end

 		if stagger then
 			Motion.Cancel(label, "TextTransparency")
 			label.TextTransparency = 1
 			Motion.Curve(label, "TextTransparency", 0, {
 				Curve = "Glide",
 				Duration = 0.24,
 				Delay = (index - 1) * ITEM_STAGGER,
 			})
 		elseif label.TextTransparency ~= 0 and not Motion.IsActive(label, "TextTransparency") then
 			label.TextTransparency = 0
 		end
 	end

 	local function ensureEmptyLabel()
 		if emptyLabel == nil then
 			emptyLabel = Util.Create("TextLabel", {
 				Name = "Empty",
 				BackgroundTransparency = 1,
 				Font = Config.Font.Regular,
 				Size = UDim2.new(1, 0, 0, ITEM_HEIGHT),
 				Text = "No matching items",
 				TextSize = Config.TextSize.Control,
 				TextXAlignment = Enum.TextXAlignment.Left,
 				Visible = false,
 				Parent = scroll.Content,
 			})
 			Theme.Bind(emptyLabel, "TextColor3", "TextDim")
 		end

 		return emptyLabel
 	end

 	local function buildItems(stagger)
 		local filter = searchBox and string.lower(searchBox.Text) or ""
 		local count = 0

 		for _, item in ipairs(self.Items) do
 			if filter == "" or string.find(string.lower(item), filter, 1, true) then
 				count += 1

 				local slot = rowPool[count]
 				if slot == nil then
 					slot = createSlot()
 					rowPool[count] = slot
 				end

 				bindSlot(slot, item, count, stagger)
 			end
 		end

 		-- Hide (never destroy) the surplus rows so they can be reused later.
 		for index = count + 1, #rowPool do
 			local slot = rowPool[index]
 			if slot.Row.Visible then
 				slot.Row.Visible = false
 				-- Stop any in-flight stagger / hover tween on a row nobody can see.
 				Motion.Cancel(slot.Label, "TextTransparency")
 				Motion.Cancel(slot.Label, "Position")
 				Motion.Cancel(slot.Row, "BackgroundTransparency")
 			end
 			slot.Item = nil
 		end

 		if count == 0 then
 			ensureEmptyLabel().Visible = true
 		elseif emptyLabel then
 			emptyLabel.Visible = false
 		end
 	end

 	function self.buildItems()
 		buildItems(false)
 	end

 	function self.renderSelector()
 		renderSelector()
 	end

 	-------------------------------------------------------------------------
 	-- Open / close
 	-------------------------------------------------------------------------

 	local outsideConnection = nil

 	local function setMenuHeight(target, onComplete)
 		Motion.Spring(self, "MenuProgress", target, {
 			Stiffness = Config.Motion.Menu.Stiffness,
 			Damping = Config.Motion.Menu.Damping,
 			OnUpdate = function(value)
 				menu.Size = UDim2.fromOffset(menuWidth, math.max(0, value))
 			end,
 			OnComplete = onComplete,
 		})
 	end

 	local function setChevron(open)
 		Motion.Spring(self, "ChevronSpin", open and 180 or 0, {
 			From = self.ChevronSpin,
 			Stiffness = Config.Motion.Indicator.Stiffness,
 			Damping = Config.Motion.Indicator.Damping,
 			OnUpdate = function(value)
 				chevron.Container.Rotation = value
 			end,
 		})
 	end

 	self.ChevronSpin = 0

 	local function disconnectOutside()
 		if outsideConnection then
 			outsideConnection:Disconnect()
 			outsideConnection = nil
 		end
 	end

 	local function close()
 		if not self.Open then
 			return
 		end

 		self.Open = false
 		disconnectOutside()
 		section.Window:ClosePopup(self)

 		setChevron(false)
 		Theme.Bind(selectorStroke, "Color", "Outline")

 		setMenuHeight(0, function()
 			if not self.Open then
 				menu.Visible = false
 			end
 		end)
 	end

 	local function positionMenu()
 		if not self.Open then
 			return
 		end

 		local window = section.Window.Frame
 		local control = self.Control
 		local scale = math.max(0.05, section.Window.Scale.Scale)
 		local x = (control.AbsolutePosition.X - window.AbsolutePosition.X + control.AbsoluteSize.X) / scale - menuWidth
 		local y = (control.AbsolutePosition.Y - window.AbsolutePosition.Y + control.AbsoluteSize.Y) / scale
 			+ Config.Metrics.PopupGap
 		local windowSize = Vector2.new(window.AbsoluteSize.X / scale, window.AbsoluteSize.Y / scale)
 		local margin = Config.Metrics.PopupMargin

 		if y + menuHeight > windowSize.Y - margin then
 			y = (control.AbsolutePosition.Y - window.AbsolutePosition.Y) / scale - menuHeight - Config.Metrics.PopupGap
 		end

 		menu.Position = UDim2.fromOffset(
 			math.clamp(x, margin, math.max(margin, windowSize.X - menuWidth - margin)),
 			math.clamp(y, margin, math.max(margin, windowSize.Y - menuHeight - margin))
 		)
 	end

 	local function open()
 		if self.Open or not self.Enabled then
 			return
 		end

 		section.Window:OpenPopup(self)
 		self.Open = true

 		if searchBox then
 			searchBox.Text = ""
 		end

 		buildItems(true)

 		positionMenu()
 		menu.Size = UDim2.fromOffset(menuWidth, 0)
 		menu.Visible = true

 		setMenuHeight(menuHeight)
 		setChevron(true)
 		Theme.Bind(selectorStroke, "Color", "Accent")

 		task.defer(function()
 			if not self.Open then
 				return
 			end

 			scroll:Refresh()

 			outsideConnection = UserInputService.InputBegan:Connect(function(input)
 				local inputType = input.UserInputType
 				if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
 					return
 				end

 				local point = Vector2.new(input.Position.X, input.Position.Y)
 				if Util.IsInside(menu, point) or Util.IsInside(selector, point) then
 					return
 				end

 				close()
 			end)
 		end)
 	end

 	selector.MouseButton1Click:Connect(function()
 		if self.Open then
 			close()
 		else
 			open()
 		end
 	end)

 	if searchBox then
 		searchBox:GetPropertyChangedSignal("Text"):Connect(function()
 			if self.Open then
 				buildItems(false)
 				scroll:Refresh()
 			end
 		end)

 		searchBox.FocusLost:Connect(function(enterPressed)
 			if enterPressed then
 				searchBox:ReleaseFocus()
 			end
 		end)
 	end

 	self.Maid:Add(disconnectOutside)
 	self.Maid:Add(function()
 		-- Pooled rows are parented under the menu; stop their tweens first.
 		Motion.CancelTree(menu)
 		menu:Destroy()
 	end)
 	self.Maid:Add(close)

 	self.open = open
 	self.close = close
 	self.Reposition = positionMenu

 	-------------------------------------------------------------------------
 	-- Value
 	-------------------------------------------------------------------------

 	if options.Default ~= nil then
 		self:SetValue(options.Default, true)
 	else
 		renderSelector()
 	end

 	self:SetControlEnabled(self.Enabled)

 	self:SetHoverable(true)
 	return self
 end

 --- Applies a selection. Accepts a string for single select mode and an array
 --- (or set table) for multi select mode.
 function Dropdown:SetValue(value, silent)
 	local selection = {}

 	if self.Multi then
 		if type(value) == "table" then
 			for key, entry in pairs(value) do
 				local item = type(key) == "number" and entry or key
 				if type(item) == "string" and table.find(self.Items, item) then
 					selection[item] = true
 				end
 			end
 		elseif value ~= nil then
 			local item = tostring(value)
 			if table.find(self.Items, item) then
 				selection[item] = true
 			end
 		end
 	else
 		local item = value ~= nil and tostring(value) or nil
 		if item and table.find(self.Items, item) then
 			selection[item] = true
 		end
 	end

 	self.Selection = selection
 	self:_render()

 	if not silent then
 		self:Fire(self:GetValue())
 	end
 end

 function Dropdown:Toggle(item)
 	if not self.Enabled then
 		return
 	end

 	if self.Multi then
 		self.Selection[item] = not self.Selection[item] or nil
 	else
 		if self.Selection[item] then
 			self.Selection = {}
 		else
 			self.Selection = { [item] = true }
 		end
 	end

 	self:_render()

 	if not self.Multi then
 		self:Hide()
 	end

 	self:Fire(self:GetValue())
 end

 --- Selected item (string) or ordered list of selected items (array).
 function Dropdown:GetValue()
 	local selected = {}

 	for _, item in ipairs(self.Items) do
 		if self.Selection[item] then
 			table.insert(selected, item)
 		end
 	end

 	if self.Multi then
 		return selected
 	end

 	return selected[1]
 end

 function Dropdown:SetItems(items)
 	local previous = self:GetValue()

 	self.Items = {}
 	for _, item in ipairs(items or {}) do
 		table.insert(self.Items, tostring(item))
 	end

 	self.Selection = {}
 	self:SetValue(previous, true)

 	if self.Open then
 		self:_render()
 	end
 end

 function Dropdown:Add(item)
 	item = tostring(item)
 	if table.find(self.Items, item) then
 		return
 	end

 	table.insert(self.Items, item)
 	self:_render()
 end

 function Dropdown:Remove(item)
 	local index = table.find(self.Items, item)
 	if not index then
 		return
 	end

 	table.remove(self.Items, index)
 	self.Selection[item] = nil
 	self:_render()
 	self:Fire(self:GetValue())
 end

 function Dropdown:_render()
 	if self.renderSelector then
 		self.renderSelector()
 	end

 	if self.Open then
 		self.buildItems()
 		self.Scroll:Refresh()
 	end
 end

 function Dropdown:Hide()
 	if self.Open and self.close then
 		self.close()
 	end
 end

 function Dropdown:SetControlEnabled(enabled)
 	self.Selector.Active = enabled

 	Motion.Spring(self.SelectorLabel, "TextTransparency", enabled and 0 or 0.45, {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	})

 	Motion.Spring(self.Selector, "BackgroundTransparency", enabled and 0 or 0.5, {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	})

 	self.Chevron:SetTransparency(enabled and 0 or 0.45)

 	if not enabled then
 		self:Hide()
 	end
 end

 return Dropdown
end

__modules["Components/Icon"] = function(script, require)
 --[[
 	Icon
 	Draws a baked Lucide glyph out of rounded native frames.

 	Each glyph is a list of polylines in a 24x24 grid; segments become rotated
 	frames and joints become small dots, which reproduces the round cap and round
 	join look of the source SVG without any image assets. Icons inherit the theme
 	and can be recoloured or resized at runtime.

 		local icon = Icon.new(parent, "sliders-horizontal", 16, "TextMuted")
 		icon:SetColor("Accent")
 ]]

 local Icons = require(script.Parent.Parent.Core.Icons)
 local Maid = require(script.Parent.Parent.Core.Maid)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Icon = {}
 Icon.__index = Icon

 local JOINT_THRESHOLD = math.cos(math.rad(24))
 local CORNER = 1000

 --- Glyph keys are Lua identifiers, callers may use the original dashed names.
 local function normalize(name)
 	if type(name) ~= "string" then
 		return name
 	end

 	return (string.gsub(name, "%-", "_"))
 end

 function Icon.new(parent, glyph, size, colorKey)
 	local self = setmetatable({}, Icon)
 	self.Maid = Maid.new()
 	self.Size = size or 16
 	self.ColorKey = colorKey or "Text"
 	self.Parts = {}

 	self.Container = Util.Create("Frame", {
 		Name = "Icon",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromOffset(self.Size, self.Size),
 		Parent = parent,
 	})

 	self.Glyph = normalize(glyph)
 	self:Build()

 	self.Maid:Add(Theme.Changed:Connect(function()
 		self:ApplyColor()
 	end))

 	return self
 end

 function Icon:Build()
 	for _, part in ipairs(self.Parts) do
 		part:Destroy()
 	end
 	table.clear(self.Parts)

 	local glyph = self.Glyph and Icons.Glyphs[self.Glyph]

 	if glyph == nil then
 		if self.Glyph then
 			warn(("[Lumen] unknown icon %q"):format(tostring(self.Glyph)))
 		end
 		return
 	end

 	local scale = self.Size / Icons.Grid
 	local thickness = math.max(1, Icons.Stroke * scale)

 	local function addPart(className, properties)
 		local part = Util.Create(className, properties)
 		table.insert(self.Parts, part)
 		return part
 	end

 	local function addDot(x, y)
 		local dot = addPart("Frame", {
 			Name = "Joint",
 			AnchorPoint = Vector2.new(0.5, 0.5),
 			BackgroundColor3 = Theme.Palette.Text,
 			BorderSizePixel = 0,
 			Position = UDim2.fromOffset(x, y),
 			Size = UDim2.fromOffset(thickness, thickness),
 			Parent = self.Container,
 		})
 		Util.Corner(dot, CORNER)
 	end

 	local function addSegment(ax, ay, bx, by)
 		local dx = bx - ax
 		local dy = by - ay
 		local length = math.sqrt(dx * dx + dy * dy)

 		if length < 0.05 then
 			return
 		end

 		local segment = addPart("Frame", {
 			Name = "Segment",
 			AnchorPoint = Vector2.new(0.5, 0.5),
 			BackgroundColor3 = Theme.Palette.Text,
 			BorderSizePixel = 0,
 			Position = UDim2.fromOffset((ax + bx) / 2, (ay + by) / 2),
 			Rotation = math.deg(math.atan2(dy, dx)),
 			Size = UDim2.fromOffset(length, thickness),
 			Parent = self.Container,
 		})
 		Util.Corner(segment, CORNER)
 	end

 	for _, flat in ipairs(glyph) do
 		local count = #flat // 2

 		if count >= 2 then
 			local points = {}

 			for index = 1, count do
 				points[index] = { flat[index * 2 - 1] * scale, flat[index * 2] * scale }
 			end

 			local closed = math.abs(points[1][1] - points[count][1]) < 0.01
 				and math.abs(points[1][2] - points[count][2]) < 0.01

 			-- The last point of a closed polyline repeats the first one.
 			local lastSegmentIndex = closed and (count - 1) or count

 			for index = 1, lastSegmentIndex - 1 do
 				addSegment(points[index][1], points[index][2], points[index + 1][1], points[index + 1][2])
 			end

 			if closed then
 				addSegment(points[count - 1][1], points[count - 1][2], points[1][1], points[1][2])
 			else
 				addDot(points[1][1], points[1][2])
 				addDot(points[count][1], points[count][2])
 			end

 			for index = 2, count - 1 do
 				local previous = points[index - 1]
 				local current = points[index]
 				local following = points[index + 1] or points[1]

 				local ax = current[1] - previous[1]
 				local ay = current[2] - previous[2]
 				local bx = following[1] - current[1]
 				local by = following[2] - current[2]

 				local lengthA = math.sqrt(ax * ax + ay * ay)
 				local lengthB = math.sqrt(bx * bx + by * by)

 				if lengthA > 0.05 and lengthB > 0.05 then
 					local dot = (ax * bx + ay * by) / (lengthA * lengthB)

 					if dot < JOINT_THRESHOLD then
 						addDot(current[1], current[2])
 					end
 				end
 			end
 		end
 	end

 	self:ApplyColor()
 end

 function Icon:ApplyColor()
 	local color = self.ColorKey

 	if typeof(color) == "string" then
 		color = Theme.Palette[color] or Theme.Palette.Text
 	end

 	for _, part in ipairs(self.Parts) do
 		part.BackgroundColor3 = color
 	end
 end

 function Icon:SetGlyph(glyph)
 	glyph = normalize(glyph)

 	if self.Glyph == glyph then
 		return self
 	end

 	self.Glyph = glyph
 	self:Build()

 	return self
 end

 function Icon:SetColor(color)
 	self.ColorKey = color
 	self:ApplyColor()

 	return self
 end

 function Icon:SetSize(size)
 	if self.Size == size then
 		return self
 	end

 	self.Size = size
 	self.Container.Size = UDim2.fromOffset(size, size)
 	self:Build()

 	return self
 end

 function Icon:SetTransparency(value)
 	self.Transparency = value

 	for _, part in ipairs(self.Parts) do
 		part.BackgroundTransparency = value
 	end

 	return self
 end

 function Icon:Destroy()
 	self.Maid:Destroy()

 	if self.Container then
 		self.Container:Destroy()
 		self.Container = nil
 	end
 end

 --- True when `name` refers to a baked glyph rather than an image asset.
 function Icon.HasGlyph(name)
 	return type(name) == "string" and Icons.Glyphs[normalize(name)] ~= nil
 end

 Icon.Glyphs = Icons.Glyphs
 Icon.Grid = Icons.Grid

 return Icon
end

__modules["Components/Input"] = function(script, require)
 --[[
 	Input
 	Row with a single line text field.

 	The field is a frame containing an inset TextBox so the text keeps a
 	consistent margin from the border. Focus draws the accent ring in with spring
 	physics instead of snapping the border colour.
 ]]

 local Config = require(script.Parent.Parent.Core.Config)
 local Element = require(script.Parent.Parent.Core.Element)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Input = setmetatable({}, { __index = Element })
 Input.__index = Input

 local INSET = 10
 local FIELD_HEIGHT = 26

 function Input.new(section, options)
 	options = options or {}

 	local self = Element.new(Input, section, options, {
 		ControlWidth = options.Width or 156,
 		ControlHeight = FIELD_HEIGHT,
 	})

 	self.Numeric = options.Numeric == true

 	local field = Util.Create("Frame", {
 		Name = "Field",
 		Active = true,
 		BackgroundColor3 = Theme.Palette.Control,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		Parent = self.Control,
 	})
 	Util.Corner(field, Config.Radius.Control)
 	Theme.Bind(field, "BackgroundColor3", "Control")

 	local stroke = Util.Stroke(field, Theme.Palette.Outline, 1, 0.4)

 	local box = Util.Create("TextBox", {
 		Name = "Box",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		BackgroundTransparency = 1,
 		ClearTextOnFocus = false,
 		Font = Config.Font.Medium,
 		PlaceholderColor3 = Theme.Palette.TextDim,
 		PlaceholderText = options.Placeholder or "",
 		Position = UDim2.fromScale(0.5, 0.5),
 		Size = UDim2.new(1, -(INSET * 2), 1, 0),
 		Text = tostring(options.Default or ""),
 		TextColor3 = Theme.Palette.Text,
 		TextSize = Config.TextSize.Control,
 		TextTruncate = Enum.TextTruncate.AtEnd,
 		TextXAlignment = Enum.TextXAlignment.Left,
 		TextYAlignment = Enum.TextYAlignment.Center,
 		Parent = field,
 	})
 	Theme.Bind(box, "TextColor3", "Text")
 	Theme.Bind(box, "PlaceholderColor3", "TextDim")

 	self.Field = field
 	self.Box = box
 	self.Stroke = stroke
 	self.Value = box.Text

 	local function setFocused(focused)
 		Theme.Bind(stroke, "Color", focused and "Accent" or "Outline")

 		Motion.Spring(stroke, "Transparency", focused and 0 or 0.4, {
 			Stiffness = Config.Motion.Hover.Stiffness,
 			Damping = Config.Motion.Hover.Damping,
 		})

 		Motion.Spring(stroke, "Thickness", focused and 1.5 or 1, {
 			Stiffness = Config.Motion.Hover.Stiffness,
 			Damping = Config.Motion.Hover.Damping,
 		})
 	end

 	local function sanitize(text)
 		if not self.Numeric then
 			return text
 		end

 		local cleaned = string.gsub(text, "[^%d%.%-]", "")
 		cleaned = string.gsub(cleaned, "%-", "")

 		local firstDot = string.find(cleaned, ".", 1, true)
 		if firstDot then
 			local head = string.sub(cleaned, 1, firstDot)
 			local tail = string.gsub(string.sub(cleaned, firstDot + 1), "%.", "")
 			cleaned = head .. tail
 		end

 		if string.sub(text, 1, 1) == "-" then
 			cleaned = "-" .. cleaned
 		end

 		return cleaned
 	end

 	local function commit()
 		local text = box.Text

 		if self.Numeric then
 			local number = tonumber(text)
 			if number == nil then
 				box.Text = self.Value
 				return
 			end
 		end

 		if text == self.Value then
 			return
 		end

 		self.Value = text
 		self:Fire(text)
 	end

 	self.sanitize = sanitize

 	box.Focused:Connect(function()
 		setFocused(true)
 	end)

 	box.FocusLost:Connect(function(enterPressed)
 		setFocused(false)
 		commit()

 		if enterPressed then
 			box:ReleaseFocus()
 		end
 	end)

 	box:GetPropertyChangedSignal("Text"):Connect(function()
 		if not self.Numeric then
 			return
 		end

 		local cleaned = sanitize(box.Text)
 		if cleaned ~= box.Text then
 			box.Text = cleaned
 		end
 	end)

 	self.Maid:Add(Theme.Changed:Connect(function()
 		setFocused(box:IsFocused())
 	end))

 	self:SetHoverable(true)
 	return self
 end

 function Input:GetValue()
 	return self.Value
 end

 function Input:SetValue(text, silent)
 	text = tostring(text or "")
 	if self.Numeric then
 		text = self.sanitize(text)
 		if text ~= "" and text ~= "-" and tonumber(text) == nil then
 			return
 		end
 	end
 	self.Box.Text = text
 	self.Value = text

 	if not silent then
 		self:Fire(text)
 	end
 end

 function Input:SetPlaceholder(text)
 	self.Box.PlaceholderText = tostring(text)
 end

 function Input:SetControlEnabled(enabled)
 	self.Box.TextEditable = enabled

 	Motion.Spring(self.Field, "BackgroundTransparency", enabled and 0 or 0.5, {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	})

 	Motion.Spring(self.Box, "TextTransparency", enabled and 0 or 0.45, {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	})
 end

 return Input
end

__modules["Components/Keybind"] = function(script, require)
 --[[
 	Keybind
 	Row that captures a keyboard or mouse binding.

 	The button enters a listening state on click; Backspace or Delete clears the
 	binding, Escape cancels. While listening the border breathes with the accent
 	colour instead of simply changing, which makes the waiting state obvious at a
 	glance.
 ]]

 local UserInputService = game:GetService("UserInputService")

 local Config = require(script.Parent.Parent.Core.Config)
 local Element = require(script.Parent.Parent.Core.Element)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Icon = require(script.Parent.Icon)

 local Keybind = setmetatable({}, { __index = Element })
 Keybind.__index = Keybind

 local CLEAR_KEYS = {
 	[Enum.KeyCode.Backspace] = true,
 	[Enum.KeyCode.Delete] = true,
 }

 -- "Unknown" was renamed to "None" in newer API dumps; both share value 0.
 local NO_KEY = nil
 for _, item in ipairs(Enum.KeyCode:GetEnumItems()) do
 	if item.Value == 0 then
 		NO_KEY = item
 		break
 	end
 end

 local function isBindable(input)
 	local inputType = input.UserInputType

 	if inputType == Enum.UserInputType.Keyboard then
 		return input.KeyCode ~= NO_KEY
 	end

 	return inputType == Enum.UserInputType.MouseButton1
 		or inputType == Enum.UserInputType.MouseButton2
 		or inputType == Enum.UserInputType.MouseButton3
 end

 function Keybind.new(section, options)
 	options = options or {}

 	local self = Element.new(Keybind, section, options, {
 		ControlWidth = options.Width or 110,
 		ControlHeight = Config.Metrics.ControlHeight,
 	})

 	self.Value = options.Default
 	self.Listening = false

 	local button = Util.Create("TextButton", {
 		Name = "Button",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		AutoButtonColor = false,
 		BackgroundColor3 = Theme.Palette.Control,
 		BorderSizePixel = 0,
 		Position = UDim2.fromScale(0.5, 0.5),
 		Size = UDim2.fromScale(1, 1),
 		Text = "",
 		TextTransparency = 1,
 		Parent = self.Control,
 	})
 	Util.Corner(button, Config.Radius.Control)
 	Theme.Bind(button, "BackgroundColor3", "Control")

 	local stroke = Util.Stroke(button, Theme.Palette.Outline, 1, 0.4)

 	local icon = Icon.new(button, "keyboard", Config.Icons.KeybindSize, "TextMuted")
 	icon.Container.AnchorPoint = Vector2.new(0, 0.5)
 	icon.Container.Position = UDim2.new(0, 9, 0.5, 0)

 	local label = Util.Create("TextLabel", {
 		Name = "Label",
 		AnchorPoint = Vector2.new(1, 0.5),
 		BackgroundTransparency = 1,
 		Font = Config.Font.Medium,
 		Position = UDim2.new(1, -10, 0.5, 0),
 		Size = UDim2.new(1, -34, 1, 0),
 		Text = "",
 		TextSize = Config.TextSize.Control,
 		TextTruncate = Enum.TextTruncate.AtEnd,
 		TextXAlignment = Enum.TextXAlignment.Right,
 		TextYAlignment = Enum.TextYAlignment.Center,
 		Parent = button,
 	})
 	Theme.Bind(label, "TextColor3", "Text")

 	self.Button = button
 	self.Stroke = stroke
 	self.Label = label
 	self.Icon = icon

 	local pulsing = false

 	local function render()
 		label.Text = self.Listening and "Press a key" or Util.KeyName(self.Value)

 		if self.Listening then
 			Theme.Bind(stroke, "Color", "Accent")
 			Theme.Bind(button, "BackgroundColor3", "AccentSoft")
 			icon:SetColor("Accent")

 			if not pulsing then
 				pulsing = true
 				Motion.Pulse(stroke, "Transparency", 0, {
 					From = 0.75,
 					Duration = 1.1,
 					Curve = "Even",
 					Stopped = function()
 						return not self.Listening
 					end,
 				})
 			end

 			Motion.Curve(stroke, "Thickness", 1.5, { Curve = "Glide", Duration = 0.2 })
 		else
 			pulsing = false
 			Theme.Bind(stroke, "Color", "Outline")
 			Theme.Bind(button, "BackgroundColor3", "Control")
 			icon:SetColor(self.Enabled and "TextMuted" or "TextDim")

 			Motion.Curve(stroke, "Transparency", 0.4, { Curve = "Exit", Duration = 0.3 })
 			Motion.Curve(stroke, "Thickness", 1, { Curve = "Glide", Duration = 0.2 })
 		end
 	end

 	function self.render()
 		render()
 	end

 	function self.stopListening()
 		if not self.Listening then
 			return
 		end

 		self.Listening = false
 		render()
 	end

 	button.MouseButton1Click:Connect(function()
 		if not self.Enabled then
 			return
 		end

 		self.Listening = not self.Listening
 		render()
 	end)

 	-- While listening, `processed` is deliberately ignored: keys such as "/"
 	-- (chat) or others claimed by CoreGui / game processing must still be
 	-- assignable. Only the Listening flag gates capture.
 	self.Maid:Add(UserInputService.InputBegan:Connect(function(input)
 		if not self.Listening then
 			return
 		end

 		if
 			input.UserInputType == Enum.UserInputType.MouseButton1
 			and Util.IsInside(button, Vector2.new(input.Position.X, input.Position.Y))
 		then
 			-- Clicking the button toggles listening instead of binding.
 			return
 		end

 		if input.KeyCode == Enum.KeyCode.Escape then
 			self.stopListening()
 			return
 		end

 		if input.KeyCode ~= NO_KEY and CLEAR_KEYS[input.KeyCode] then
 			self.Listening = false
 			self:SetValue(nil)
 			return
 		end

 		if not isBindable(input) then
 			return
 		end

 		self.Listening = false

 		local value = input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode or input.UserInputType
 		self:SetValue(value)
 	end))

 	self.Maid:Add(Theme.Changed:Connect(render))

 	render()

 	self:SetHoverable(true)
 	return self
 end

 function Keybind:GetValue()
 	return self.Value
 end

 function Keybind:SetValue(value, silent)
 	if self.Value == value then
 		self.render()
 		return
 	end

 	self.Value = value
 	self.render()

 	if not silent then
 		self:Fire(value)
 	end
 end

 function Keybind:SetControlEnabled(enabled)
 	self.Button.Active = enabled

 	if not enabled then
 		self.Listening = false
 		self.render()
 	end

 	Motion.Spring(self.Label, "TextTransparency", enabled and 0 or 0.45, {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	})

 	Motion.Spring(self.Button, "BackgroundTransparency", enabled and 0 or 0.5, {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	})

 	self.Icon:SetTransparency(enabled and 0 or 0.45)
 end

 return Keybind
end

__modules["Components/Notification"] = function(script, require)
 --[[
 	Notification
 	Bottom right toast stack.

 	Each toast springs in from the right, drains a gradient progress bar and
 	collapses on its way out so the remaining stack never jumps. The accent bar
 	and glyph are picked from the notification type.
 ]]

 local Config = require(script.Parent.Parent.Core.Config)
 local Maid = require(script.Parent.Parent.Core.Maid)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Icon = require(script.Parent.Icon)

 local Notification = {}
 Notification.__index = Notification

 local WIDTH = 300
 local PADDING = 12
 local ICON_OFFSET = 34

 local TYPES = {
 	Info = { key = "Accent", glyph = "info" },
 	Success = { key = "Success", glyph = "circle-check" },
 	Warning = { key = "Warning", glyph = "triangle-alert" },
 	Error = { key = "Error", glyph = "circle-x" },
 }

 function Notification.new(window)
 	local self = setmetatable({}, Notification)
 	self.Window = window
 	self.Maid = Maid.new()
 	self.Active = {}
 	self.Transitions = {}
 	self.Count = 0

 	local container = Util.Create("Frame", {
 		Name = "Notifications",
 		AnchorPoint = Vector2.new(1, 1),
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.new(1, -16, 1, -16),
 		Size = UDim2.fromOffset(WIDTH, 0),
 		ZIndex = 40,
 		Parent = window.ScreenGui,
 	})
 	local layout = Util.List(container, 8)
 	layout.VerticalAlignment = Enum.VerticalAlignment.Bottom
 	container.AutomaticSize = Enum.AutomaticSize.Y

 	self.Container = container

 	return self
 end

 function Notification:Push(options)
 	if type(options) == "string" then
 		options = { Content = options }
 	end
 	options = options or {}

 	self.Count += 1

 	local preset = TYPES[options.Type] or TYPES.Info
 	local accent = Theme.Palette[preset.key]
 	local duration = options.Duration or 5

 	local toast = Util.Create("CanvasGroup", {
 		Name = "Notification",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		ClipsDescendants = true,
 		GroupTransparency = 1,
 		LayoutOrder = self.Count,
 		Size = UDim2.new(1, 0, 0, 0),
 		Parent = self.Container,
 	})

 	-- The slide lives on a wrapper: positions inside a UIListLayout belong to
 	-- the layout, so the toast itself must not move.
 	local slide = Util.Create("Frame", {
 		Name = "Slide",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		Parent = toast,
 	})

 	local card = Util.Create("Frame", {
 		Name = "Card",
 		Active = true,
 		BackgroundColor3 = Theme.Palette.Surface,
 		BorderSizePixel = 0,
 		Size = UDim2.new(1, 0, 0, 0),
 		Parent = slide,
 	})
 	Util.Corner(card, Config.Radius.Card)
 	Theme.Bind(card, "BackgroundColor3", "Surface")
 	Theme.Bind(Util.Stroke(card, Theme.Palette.Outline, 1, 0.35), "Color", "Outline")

 	local bar = Util.Create("Frame", {
 		Name = "Accent",
 		BackgroundColor3 = accent,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, 0, 0, 10),
 		Size = UDim2.fromOffset(3, 0),
 		Parent = card,
 	})
 	Util.Corner(bar, 2)

 	local glyph = Icon.new(card, preset.glyph, Config.Icons.NoticeSize, preset.key)
 	glyph.Container.AnchorPoint = Vector2.new(0, 0)
 	glyph.Container.Position = UDim2.fromOffset(PADDING + 6, PADDING + 1)

 	local cursor = PADDING

 	if options.Title then
 		local title = Util.Create("TextLabel", {
 			Name = "Title",
 			BackgroundTransparency = 1,
 			Font = Config.Font.Bold,
 			Position = UDim2.fromOffset(ICON_OFFSET + 6, cursor),
 			Size = UDim2.new(1, -(ICON_OFFSET + PADDING + 6), 0, 16),
 			Text = tostring(options.Title),
 			TextSize = Config.TextSize.Element,
 			TextXAlignment = Enum.TextXAlignment.Left,
 			TextYAlignment = Enum.TextYAlignment.Top,
 			TextTruncate = Enum.TextTruncate.AtEnd,
 			Parent = card,
 		})
 		Theme.Bind(title, "TextColor3", "Text")
 		cursor += 18
 	end

 	local content = nil
 	local contentWidth = WIDTH - (ICON_OFFSET + PADDING + 6)

 	if options.Content then
 		content = Util.Create("TextLabel", {
 			Name = "Content",
 			BackgroundTransparency = 1,
 			Font = Config.Font.Regular,
 			Position = UDim2.fromOffset(ICON_OFFSET + 6, cursor),
 			Size = UDim2.new(1, -(ICON_OFFSET + PADDING + 6), 0, 0),
 			AutomaticSize = Enum.AutomaticSize.Y,
 			Text = tostring(options.Content),
 			TextSize = Config.TextSize.Body,
 			TextWrapped = true,
 			TextXAlignment = Enum.TextXAlignment.Left,
 			TextYAlignment = Enum.TextYAlignment.Top,
 			Parent = card,
 		})
 		Theme.Bind(content, "TextColor3", "TextMuted")
 		cursor += 2
 	end

 	local contentHeight = content
 			and math.max(
 				16,
 				Util.MeasureWrappedHeight(content.Text, Config.TextSize.Body, Config.Font.Regular, contentWidth)
 			)
 		or 0
 	local cardHeight = math.max(48, cursor + contentHeight + PADDING)

 	card.Size = UDim2.new(1, 0, 0, cardHeight)
 	toast.Size = UDim2.new(1, 0, 0, cardHeight)
 	bar.Size = UDim2.fromOffset(3, cardHeight - 20)

 	if content then
 		content.Size = UDim2.new(1, -(ICON_OFFSET + PADDING + 6), 0, contentHeight)
 	end

 	local progress = Util.Create("Frame", {
 		Name = "Progress",
 		AnchorPoint = Vector2.new(0, 1),
 		BackgroundColor3 = accent,
 		BackgroundTransparency = 0.45,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, 0, 1, 0),
 		Size = UDim2.new(1, 0, 0, 2),
 		Parent = card,
 	})
 	Util.Create("UIGradient", {
 		Rotation = 0,
 		Transparency = NumberSequence.new({
 			NumberSequenceKeypoint.new(0, 0.15),
 			NumberSequenceKeypoint.new(1, 0.85),
 		}),
 		Parent = progress,
 	})

 	local dismissed = false
 	self.Height = cardHeight

 	-- Springs animate plain tables, never Instances, so no custom fields are
 	-- ever written onto a Roblox object.
 	local collapse = { Height = cardHeight }
 	local slideState = { Offset = 24 }
 	self.Transitions[toast] = { collapse, slideState, slide, progress }

 	local function dismiss()
 		if dismissed then
 			return
 		end
 		dismissed = true

 		local index = table.find(self.Active, toast)
 		if index then
 			table.remove(self.Active, index)
 		end

 		Motion.Curve(toast, "GroupTransparency", 1, { Curve = "Exit", Duration = 0.2 })
 		Motion.Curve(slide, "Position", UDim2.fromOffset(28, 0), { Curve = "Exit", Duration = 0.24 })

 		Motion.Spring(collapse, "Height", 0, {
 			Stiffness = 420,
 			Damping = 34,
 			OnUpdate = function(value)
 				toast.Size = UDim2.new(1, 0, 0, math.max(0, value))
 			end,
 			OnComplete = function()
 				self.Transitions[toast] = nil
 				toast:Destroy()
 			end,
 		})
 	end

 	card.InputBegan:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
 			dismiss()
 		end
 	end)

 	Motion.Spring(slideState, "Offset", 0, {
 		From = 24,
 		Stiffness = 300,
 		Damping = 26,
 		OnUpdate = function(value)
 			slide.Position = UDim2.fromOffset(value, 0)
 		end,
 	})

 	Motion.Curve(toast, "GroupTransparency", 0, { Curve = "Glide", Duration = 0.28 })

 	if options.Duration ~= 0 then
 		Motion.Curve(progress, "Size", UDim2.new(0, 0, 0, 2), {
 			From = UDim2.new(1, 0, 0, 2),
 			Curve = "Even",
 			Duration = duration,
 			OnComplete = dismiss,
 		})
 	end

 	table.insert(self.Active, toast)

 	return toast
 end

 function Notification:Clear()
 	for toast, transition in pairs(self.Transitions) do
 		for _, target in ipairs(transition) do
 			Motion.CancelAll(target)
 		end
 		if toast.Parent then
 			Motion.CancelTree(toast)
 			toast:Destroy()
 		end
 	end
 	table.clear(self.Transitions)
 	table.clear(self.Active)
 end

 function Notification:Destroy()
 	Motion.CancelAll(self)
 	self:Clear()
 	self.Maid:Destroy()
 	self.Container:Destroy()
 end

 return Notification
end

__modules["Components/Paragraph"] = function(script, require)
 --[[
 	Paragraph
 	Read only text block. Height follows the wrapped label so long copy always
 	fits, and the section re-flows when the window is resized.
 ]]

 local Config = require(script.Parent.Parent.Core.Config)
 local Element = require(script.Parent.Parent.Core.Element)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Paragraph = setmetatable({}, { __index = Element })
 Paragraph.__index = Paragraph

 local TITLE_GAP = 4

 function Paragraph.new(section, options)
 	options = options or {}

 	local paddingTop = 12
 	local paddingBottom = 14

 	local self = Element.new(Paragraph, section, options, {
 		Height = paddingTop + paddingBottom,
 		TitleHeight = Config.Metrics.TitleHeight,
 		PaddingTop = paddingTop,
 		PaddingBottom = paddingBottom,
 	})

 	local bodyTop = paddingTop + (self.Title and (Config.Metrics.TitleHeight + TITLE_GAP) or 0)

 	local body = Util.Create("TextLabel", {
 		Name = "Text",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Font = Config.Font.Regular,
 		Position = UDim2.new(0, 0, 0, bodyTop),
 		Size = UDim2.new(1, 0, 0, 0),
 		AutomaticSize = Enum.AutomaticSize.Y,
 		Text = tostring(options.Text or options.Content or ""),
 		TextSize = Config.TextSize.Body,
 		TextWrapped = true,
 		TextXAlignment = Enum.TextXAlignment.Left,
 		TextYAlignment = Enum.TextYAlignment.Top,
 		Parent = self.Row,
 	})
 	Theme.Bind(body, "TextColor3", options.Name and "TextMuted" or "Text")

 	self.Body = body
 	self.BodyTop = bodyTop
 	self.PaddingBottom = paddingBottom

 	-- The label wraps asynchronously, so the row height follows its measurement.
 	self.Maid:Add(body:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
 		self:RefreshHeight()
 	end))

 	task.defer(function()
 		self:RefreshHeight()
 	end)

 	return self
 end

 function Paragraph:RefreshHeight()
 	if self.Destroyed or not self.Body then
 		return
 	end

 	local textHeight = self.Body.AbsoluteSize.Y
 	if textHeight <= 0 then
 		return
 	end

 	self:SetRowHeight(self.BodyTop + textHeight + self.PaddingBottom)
 end

 function Paragraph:SetText(text)
 	self.Body.Text = tostring(text)
 end

 function Paragraph:GetText()
 	return self.Body.Text
 end

 return Paragraph
end

__modules["Components/Section"] = function(script, require)
 --[[
 	Section
 	A titled, collapsible card of rows.

 	Sections own the layout arithmetic for their content, which keeps the
 	surrounding scroll canvas exact without waiting for layout passes. The card
 	itself is a CanvasGroup so it can be revealed with a staggered fade when a
 	page becomes visible, and collapsing runs on a spring instead of a tween.
 ]]

 local Config = require(script.Parent.Parent.Core.Config)
 local Effects = require(script.Parent.Parent.Core.Effects)
 local Maid = require(script.Parent.Parent.Core.Maid)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Icon = require(script.Parent.Icon)

 local Section = {}
 Section.__index = Section

 function Section.new(tab, options)
 	options = options or {}

 	local self = setmetatable({}, Section)
 	self.Tab = tab
 	self.Window = tab.Window
 	self.Options = options
 	self.Entries = {}
 	self.Count = 0
 	self.Maid = Maid.new()
 	self.Expanded = options.Collapsed ~= true
 	self.ContentHeight = 0
 	self.CardHeight = 0
 	self.AnimatedHeight = 0
 	self.Destroyed = false

 	local metrics = Config.Metrics
 	local hasHeader = options.Name ~= nil and options.Unnamed ~= true
 	local headerHeight = hasHeader and metrics.SectionHeaderHeight or 0
 	local cardOffset = hasHeader and (headerHeight + 4) or 0

 	local frame = Util.Create("CanvasGroup", {
 		Name = "Section",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.new(1, 0, 0, 0),
 		Parent = tab.Container,
 	})

 	local card = Util.Create("Frame", {
 		Name = "Card",
 		BackgroundColor3 = Theme.Palette.Surface,
 		BorderSizePixel = 0,
 		ClipsDescendants = true,
 		Position = UDim2.new(0, 0, 0, cardOffset),
 		Size = UDim2.new(1, 0, 0, 0),
 		Parent = frame,
 	})
 	Util.Corner(card, Config.Radius.Card)
 	Theme.Bind(card, "BackgroundColor3", "Surface")
 	Theme.Bind(Util.Stroke(card, Theme.Palette.Outline, 1, 0.5), "Color", "Outline")

 	local container = Util.Create("Frame", {
 		Name = "Rows",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, metrics.CardPaddingX, 0, metrics.CardPaddingY),
 		Size = UDim2.new(1, -(metrics.CardPaddingX * 2), 0, 0),
 		Parent = card,
 	})
 	Util.List(container, 0)

 	self.Frame = frame
 	self.Card = card
 	self.Container = container
 	self.HeaderHeight = headerHeight
 	self.CardOffset = cardOffset

 	if hasHeader then
 		local header = Util.Create("TextButton", {
 			Name = "Header",
 			AutoButtonColor = false,
 			BackgroundTransparency = 1,
 			BorderSizePixel = 0,
 			Size = UDim2.new(1, 0, 0, headerHeight),
 			Text = "",
 			TextTransparency = 1,
 			Parent = frame,
 		})

 		local label = Util.Create("TextLabel", {
 			Name = "Label",
 			BackgroundTransparency = 1,
 			Font = Config.Font.Bold,
 			Size = UDim2.new(1, -24, 1, 0),
 			Text = string.upper(tostring(options.Name)),
 			TextSize = Config.TextSize.Section,
 			TextXAlignment = Enum.TextXAlignment.Left,
 			TextYAlignment = Enum.TextYAlignment.Center,
 			TextTruncate = Enum.TextTruncate.AtEnd,
 			Parent = header,
 		})
 		Theme.Bind(label, "TextColor3", "TextMuted")

 		local chevron = Icon.new(header, "chevron-down", Config.Icons.ChevronSize, "TextDim")
 		chevron.Container.AnchorPoint = Vector2.new(1, 0.5)
 		chevron.Container.Position = UDim2.new(1, -2, 0.5, 0)

 		local hovered = false

 		local function paint()
 			Theme.Bind(label, "TextColor3", hovered and "Text" or "TextMuted")
 			chevron:SetColor(hovered and "Text" or "TextDim")
 		end

 		header.MouseEnter:Connect(function()
 			hovered = true
 			paint()
 		end)

 		header.MouseLeave:Connect(function()
 			hovered = false
 			paint()
 		end)

 		header.MouseButton1Click:Connect(function()
 			self:SetExpanded(not self.Expanded, true)
 		end)

 		self.Maid:Add(Theme.Changed:Connect(paint))

 		self.Header = header
 		self.Chevron = chevron

 		chevron.Container.Rotation = self.Expanded and 0 or -90
 	end

 	if not self.Expanded then
 		card.Visible = false
 	end

 	self:RefreshLayout()

 	return self
 end

 --- Registers a control row. Layout order is assigned here so separators always
 --- sit between rows, even after removals.
 function Section:Insert(element)
 	self.Count += 1

 	local order = self.Count

 	if element.Separator then
 		element.Separator.LayoutOrder = order * 2 - 1
 		element.Separator.ZIndex = 1
 	end

 	if element.Row then
 		element.Row.LayoutOrder = order * 2
 		element.Row.ZIndex = 2
 	end

 	table.insert(self.Entries, element)

 	self:RefreshLayout()
 end

 function Section:Forget(element)
 	local index = table.find(self.Entries, element)
 	if index then
 		table.remove(self.Entries, index)
 	end

 	self:RefreshLayout()
 end

 --- Recomputes content height, card height and separator visibility.
 function Section:RefreshLayout()
 	if self.Destroyed then
 		return
 	end

 	local seen = 0

 	for _, entry in ipairs(self.Entries) do
 		if entry.Visible then
 			seen += 1

 			if entry.Separator then
 				entry.Separator.Visible = seen > 1 and entry.Separator.BackgroundTransparency < 1
 			end
 		end
 	end

 	local contentHeight = 0

 	for _, entry in ipairs(self.Entries) do
 		if entry.Visible then
 			contentHeight += entry.RowHeight or 0

 			if entry.Separator and entry.Separator.Visible then
 				contentHeight += 1
 			end
 		end
 	end

 	self.ContentHeight = contentHeight
 	self.CardHeight = contentHeight + Config.Metrics.CardPaddingY * 2

 	self.Container.Size = UDim2.new(1, -(Config.Metrics.CardPaddingX * 2), 0, contentHeight)
 	self:ApplyHeights()
 end

 function Section:ApplyHeights()
 	if self.Destroyed then
 		return
 	end

 	local visibleHeight = self.Expanded and self.CardHeight or 0

 	if not self.Animating then
 		self.Card.Size = UDim2.new(1, 0, 0, visibleHeight)
 		self.AnimatedHeight = visibleHeight
 	end

 	self.Frame.Size = UDim2.new(1, 0, 0, self.CardOffset + visibleHeight)
 end

 function Section:SetExpanded(expanded, animate)
 	expanded = expanded and true or false
 	if self.Expanded == expanded then
 		return
 	end

 	self.Expanded = expanded

 	if self.Chevron then
 		Motion.Spring(self.Chevron.Container, "Rotation", expanded and 0 or -90, {
 			Stiffness = Config.Motion.Collapse.Stiffness,
 			Damping = Config.Motion.Collapse.Damping,
 		})
 	end

 	local targetCard = expanded and self.CardHeight or 0
 	local targetFrame = self.CardOffset + targetCard

 	if not animate then
 		self.Card.Visible = expanded
 		self.Card.Size = UDim2.new(1, 0, 0, targetCard)
 		self.Frame.Size = UDim2.new(1, 0, 0, targetFrame)
 		self.AnimatedHeight = targetCard
 		return
 	end

 	self.Animating = true

 	if expanded then
 		self.Card.Visible = true
 	end

 	Motion.Spring(self, "AnimatedHeight", targetCard, {
 		Stiffness = Config.Motion.Collapse.Stiffness,
 		Damping = Config.Motion.Collapse.Damping,
 		OnUpdate = function(value)
 			if self.Destroyed then
 				return
 			end

 			self.Card.Size = UDim2.new(1, 0, 0, value)
 			self.Frame.Size = UDim2.new(1, 0, 0, self.CardOffset + value)
 		end,
 		OnComplete = function()
 			if self.Destroyed then
 				return
 			end

 			self.Animating = false

 			if not self.Expanded then
 				self.Card.Visible = false
 			end

 			self:ApplyHeights()
 		end,
 	})
 end

 --- Slides and fades this card in when its page becomes visible.
 function Section:Reveal(delay)
 	if self.Destroyed then
 		return
 	end

 	Effects.Reveal(self.Frame, 10, {
 		Delay = delay,
 		Fade = false,
 		Curve = Config.Motion.Reveal.Curve,
 		Duration = Config.Motion.Reveal.Duration,
 	})
 end

 function Section:SetVisible(visible)
 	if self.Destroyed then
 		return
 	end

 	self.Frame.Visible = visible and true or false
 	self.Tab.Scroll:Refresh()
 end

 --- Adds a component instance of `class`.
 function Section:Add(class, options)
 	return class.new(self, options)
 end

 function Section:Destroy()
 	if self.Destroyed then
 		return
 	end
 	self.Destroyed = true

 	Motion.CancelAll(self)

 	-- Element:Destroy removes itself from Entries. Destroy from the end so that
 	-- every component gets a chance to release service-level input listeners.
 	while #self.Entries > 0 do
 		self.Entries[#self.Entries]:Destroy()
 	end

 	self.Maid:Destroy()

 	if self.Chevron then
 		self.Chevron:Destroy()
 		self.Chevron = nil
 	end

 	if self.Frame then
 		Motion.CancelTree(self.Frame)
 		self.Frame:Destroy()
 		self.Frame = nil
 	end

 	if self.Tab and self.Tab.Sections then
 		local index = table.find(self.Tab.Sections, self)
 		if index then
 			table.remove(self.Tab.Sections, index)
 		end
 	end
 end

 -- Component shortcuts: Section:Button{...}, Section:Toggle{...}, ...
 Section.Components = {
 	Button = require(script.Parent.Button),
 	Toggle = require(script.Parent.Toggle),
 	Slider = require(script.Parent.Slider),
 	Dropdown = require(script.Parent.Dropdown),
 	Input = require(script.Parent.Input),
 	Keybind = require(script.Parent.Keybind),
 	Paragraph = require(script.Parent.Paragraph),
 	Divider = require(script.Parent.Divider),
 	ColorPicker = require(script.Parent.ColorPicker),
 }

 for name, class in pairs(Section.Components) do
 	Section[name] = function(self, options)
 		return self:Add(class, options)
 	end
 end

 return Section
end

__modules["Components/Slider"] = function(script, require)
 --[[
 	Slider
 	Row with a value readout and a draggable track underneath.

 	The knob swells and lifts a live value bubble while it is held, and the fill
 	carries an accent gradient instead of a flat colour, so dragging feels like
 	moving something rather than painting a rectangle.
 ]]

 local UserInputService = game:GetService("UserInputService")

 local Config = require(script.Parent.Parent.Core.Config)
 local Element = require(script.Parent.Parent.Core.Element)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Slider = setmetatable({}, { __index = Element })
 Slider.__index = Slider

 local TRACK_HEIGHT = 6
 local KNOB = 12
 local HIT_HEIGHT = 20

 function Slider.new(section, options)
 	options = options or {}

 	-- No fixed height: the row grows with the title line so a description never
 	-- collides with the track.
 	local self = Element.new(Slider, section, options, {
 		ControlWidth = options.ControlWidth or 60,
 		ControlHeight = Config.Metrics.TitleHeight,
 		BodyHeight = HIT_HEIGHT,
 		BodyGap = 4,
 		PaddingTop = 6,
 		PaddingBottom = 4,
 	})

 	self.Min = options.Min or 0
 	self.Max = options.Max or 100
 	self.Decimals = options.Decimals or 0
 	self.Step = options.Step
 	self.Suffix = options.Suffix or ""
 	self.Format = options.Format
 	self.KnobScale = 1

 	if self.Max < self.Min then
 		self.Min, self.Max = self.Max, self.Min
 	end

 	local valueLabel = Util.Create("TextLabel", {
 		Name = "Value",
 		BackgroundTransparency = 1,
 		Font = Config.Font.Mono,
 		Size = UDim2.fromScale(1, 1),
 		Text = "",
 		TextSize = Config.TextSize.Control,
 		TextXAlignment = Enum.TextXAlignment.Right,
 		TextYAlignment = Enum.TextYAlignment.Center,
 		Parent = self.Control,
 	})
 	Theme.Bind(valueLabel, "TextColor3", "Text")

 	local hit = Util.Create("Frame", {
 		Name = "Hit",
 		Active = true,
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		Parent = self.Body,
 	})

 	local track = Util.Create("Frame", {
 		Name = "Track",
 		AnchorPoint = Vector2.new(0, 0.5),
 		BackgroundColor3 = Theme.Palette.Control,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, 0, 0.5, 0),
 		Size = UDim2.new(1, 0, 0, TRACK_HEIGHT),
 		Parent = hit,
 	})
 	Util.Corner(track, Config.Radius.Pill)
 	Theme.Bind(track, "BackgroundColor3", "Control")

 	local fill = Util.Create("Frame", {
 		Name = "Fill",
 		BackgroundColor3 = Theme.Palette.Accent,
 		BorderSizePixel = 0,
 		Size = UDim2.new(0, 0, 1, 0),
 		Parent = track,
 	})
 	Util.Corner(fill, Config.Radius.Pill)

 	local fillGradient = Util.Create("UIGradient", {
 		Rotation = 0,
 		Parent = fill,
 	})

 	local function paintFill()
 		local accent = Theme.Palette.Accent
 		fill.BackgroundColor3 = accent
 		fillGradient.Color = ColorSequence.new({
 			ColorSequenceKeypoint.new(0, Util.Mix(accent, Color3.new(1, 1, 1), 0.22)),
 			ColorSequenceKeypoint.new(1, accent),
 		})
 	end

 	paintFill()

 	local knob = Util.Create("Frame", {
 		Name = "Knob",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		BackgroundColor3 = Theme.Palette.Accent,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, 0, 0.5, 0),
 		Size = UDim2.fromOffset(KNOB, KNOB),
 		ZIndex = 2,
 		Parent = hit,
 	})
 	Util.Corner(knob, Config.Radius.Pill)
 	Theme.Bind(knob, "BackgroundColor3", "Accent")
 	Theme.Bind(Util.Stroke(knob, Theme.Palette.Surface, 2, 0), "Color", "Surface")

 	-- Bubble that follows the knob while dragging. Skipped when the row carries a
 	-- description: the live readout in the title line covers it and nothing can
 	-- overlap.
 	local bubble = nil
 	local bubbleLabel = nil

 	if not self.HasDescription then
 		bubble = Util.Create("Frame", {
 			Name = "Bubble",
 			AnchorPoint = Vector2.new(0.5, 1),
 			BackgroundColor3 = Theme.Palette.ControlActive,
 			BackgroundTransparency = 1,
 			BorderSizePixel = 0,
 			Position = UDim2.new(0, 0, 0, -6),
 			Size = UDim2.fromOffset(46, 20),
 			ZIndex = 3,
 			Parent = hit,
 		})
 		Util.Corner(bubble, Config.Radius.Small)
 		Theme.Bind(bubble, "BackgroundColor3", "ControlActive")

 		bubbleLabel = Util.Create("TextLabel", {
 			Name = "Label",
 			BackgroundTransparency = 1,
 			Font = Config.Font.Mono,
 			Size = UDim2.fromScale(1, 1),
 			Text = "",
 			TextSize = Config.TextSize.Badge,
 			TextXAlignment = Enum.TextXAlignment.Center,
 			TextYAlignment = Enum.TextYAlignment.Center,
 			TextTransparency = 1,
 			Parent = bubble,
 		})
 		Theme.Bind(bubbleLabel, "TextColor3", "Text")
 	end

 	self.Value = Util.Clamp(options.Default or self.Min, self.Min, self.Max)
 	self.Track = track
 	self.Fill = fill
 	self.Knob = knob
 	self.Hit = hit
 	self.Bubble = bubble
 	self.ValueLabel = valueLabel

 	local function format(value)
 		if self.Format then
 			local ok, result = pcall(self.Format, value)
 			if ok then
 				return tostring(result)
 			end
 		end

 		return string.format("%." .. self.Decimals .. "f", value) .. self.Suffix
 	end

 	local bubbleShown = false

 	local function setBubble(visible)
 		if bubble == nil or bubbleShown == visible then
 			return
 		end

 		bubbleShown = visible

 		Motion.Spring(bubbleLabel, "TextTransparency", visible and 0 or 1, {
 			Stiffness = Config.Motion.Knob.Stiffness,
 			Damping = Config.Motion.Knob.Damping,
 		})

 		Motion.Spring(bubble, "BackgroundTransparency", visible and 0.05 or 1, {
 			Stiffness = Config.Motion.Knob.Stiffness,
 			Damping = Config.Motion.Knob.Damping,
 		})

 		Motion.Spring(bubble, "Position", UDim2.new(bubble.Position.X.Scale, 0, 0, visible and -8 or -2), {
 			From = UDim2.new(bubble.Position.X.Scale, 0, 0, visible and -2 or -8),
 			Curve = "Swift",
 			Duration = 0.22,
 		})
 	end

 	local function setKnobScale(value)
 		local size = KNOB * value
 		knob.Size = UDim2.fromOffset(size, size)
 	end

 	function self.render()
 		local alpha = self.Max > self.Min and ((self.Value - self.Min) / (self.Max - self.Min)) or 0
 		local text = format(self.Value)

 		fill.Size = UDim2.new(alpha, 0, 1, 0)
 		knob.Position = UDim2.new(alpha, 0, 0.5, 0)
 		valueLabel.Text = text

 		if bubble then
 			bubble.Position = UDim2.new(alpha, 0, 0, bubble.Position.Y.Offset)
 			bubbleLabel.Text = text
 		end
 	end

 	local function snap(raw)
 		local value = raw

 		if self.Step and self.Step > 0 then
 			value = math.floor(value / self.Step + 0.5) * self.Step
 		end

 		value = Util.Round(value, self.Decimals)
 		return Util.Clamp(value, self.Min, self.Max)
 	end

 	local function valueFromPointer(x)
 		local alpha = Util.Clamp((x - hit.AbsolutePosition.X) / math.max(1, hit.AbsoluteSize.X), 0, 1)
 		return snap(self.Min + (self.Max - self.Min) * alpha)
 	end

 	local dragging = false
 	local moveConnection = nil

 	local function stopDragging()
 		if not dragging then
 			return
 		end

 		dragging = false

 		if moveConnection then
 			moveConnection:Disconnect()
 			moveConnection = nil
 		end

 		setBubble(false)
 		if self.Destroyed then
 			return
 		end

 		Motion.Spring(self, "KnobScale", 1, {
 			Stiffness = Config.Motion.Knob.Stiffness,
 			Damping = Config.Motion.Knob.Damping,
 			OnUpdate = setKnobScale,
 		})
 	end

 	hit.InputBegan:Connect(function(input)
 		if not self.Enabled then
 			return
 		end

 		local inputType = input.UserInputType
 		if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
 			return
 		end

 		dragging = true
 		self:SetValue(valueFromPointer(input.Position.X))
 		setBubble(true)

 		Motion.Spring(self, "KnobScale", 1.35, {
 			Stiffness = Config.Motion.Knob.Stiffness,
 			Damping = Config.Motion.Knob.Damping,
 			OnUpdate = setKnobScale,
 		})

 		if moveConnection then
 			moveConnection:Disconnect()
 		end
 		moveConnection = UserInputService.InputChanged:Connect(function(moved)
 			if not dragging then
 				return
 			end

 			local movedType = moved.UserInputType
 			if movedType == Enum.UserInputType.MouseMovement or movedType == Enum.UserInputType.Touch then
 				self:SetValue(valueFromPointer(moved.Position.X))
 			end
 		end)
 	end)

 	hit.InputEnded:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
 			stopDragging()
 		end
 	end)

 	-- InputEnded on the hit target does not fire when the pointer is released
 	-- outside the row (especially on touch). The service-level listener closes
 	-- the temporary move connection deterministically.
 	self.Maid:Add(UserInputService.InputEnded:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
 			stopDragging()
 		end
 	end))

 	self.Maid:Add(stopDragging)

 	self.Maid:Add(Theme.Changed:Connect(function()
 		paintFill()
 		self.render()
 	end))

 	self.render()
 	setKnobScale(1)

 	self:SetHoverable(true)
 	return self
 end

 function Slider:SetValue(value, silent)
 	if type(value) ~= "number" then
 		return
 	end

 	local clamped = Util.Clamp(Util.Round(value, self.Decimals), self.Min, self.Max)
 	if self.Value == clamped then
 		return
 	end

 	self.Value = clamped
 	self.render()

 	if not silent then
 		self:Fire(clamped)
 	end
 end

 function Slider:GetValue()
 	return self.Value
 end

 function Slider:SetRange(minimum, maximum)
 	self.Min = minimum
 	self.Max = maximum
 	self:SetValue(self.Value)
 	self.render()
 end

 function Slider:SetControlEnabled(enabled)
 	self.Hit.Active = enabled

 	Motion.Spring(self.Fill, "BackgroundTransparency", enabled and 0 or 0.6, {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	})

 	Motion.Spring(self.Knob, "BackgroundTransparency", enabled and 0 or 0.6, {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	})
 end

 return Slider
end

__modules["Components/Tab"] = function(script, require)
 --[[
 	Tab
 	A sidebar entry plus the page that owns it. Pages are CanvasGroups, so the
 	switch costs a single fade and sections can stagger themselves in afterwards.

 	`Icon` accepts a baked glyph name ("activity", "sliders-horizontal", ...) or a
 	legacy rbxassetid string.
 ]]

 local Config = require(script.Parent.Parent.Core.Config)
 local Maid = require(script.Parent.Parent.Core.Maid)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Scroll = require(script.Parent.Parent.Core.Scroll)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)
 local UserInputService = game:GetService("UserInputService")

 local Icon = require(script.Parent.Icon)
 local Section = require(script.Parent.Section)

 local Tab = {}
 Tab.__index = Tab

 function Tab.new(window, options)
 	options = options or {}

 	local self = setmetatable({}, Tab)
 	self.Window = window
 	self.Options = options
 	self.Name = options.Name or "Tab"
 	self.Sections = {}
 	self.Maid = Maid.new()
 	self.Active = false

 	local button = Util.Create("TextButton", {
 		Name = "TabButton",
 		AutoButtonColor = false,
 		BackgroundColor3 = Theme.Palette.Window,
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		ClipsDescendants = true,
 		Size = UDim2.new(1, 0, 0, Config.Window.TabHeight),
 		Text = "",
 		TextTransparency = 1,
 		Parent = window.TabList,
 	})
 	Util.Corner(button, Config.Radius.Control)

 	-- Content slides slightly on hover; the button itself stays put.
 	local content = Util.Create("Frame", {
 		Name = "Content",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		Parent = button,
 	})

 	local icon = nil
 	local glyph = options.Icon
 	local iconOffset = 12

 	if glyph ~= nil then
 		if Icon.HasGlyph(glyph) then
 			icon = Icon.new(content, glyph, Config.Icons.TabSize, "TextMuted")
 			icon.Container.AnchorPoint = Vector2.new(0, 0.5)
 			icon.Container.Position = UDim2.new(0, 12, 0.5, 0)
 		else
 			icon = Util.Create("ImageLabel", {
 				Name = "Icon",
 				AnchorPoint = Vector2.new(0, 0.5),
 				BackgroundTransparency = 1,
 				Position = UDim2.new(0, 12, 0.5, 0),
 				Size = UDim2.fromOffset(Config.Icons.TabSize, Config.Icons.TabSize),
 				Image = glyph,
 				ImageColor3 = Theme.Palette.TextMuted,
 				ImageTransparency = 0.15,
 				Parent = content,
 			})
 			Theme.Bind(icon, "ImageColor3", "TextMuted")
 		end

 		iconOffset = 38
 	end

 	local label = Util.Create("TextLabel", {
 		Name = "Label",
 		AnchorPoint = Vector2.new(0, 0.5),
 		Position = UDim2.new(0, iconOffset, 0.5, 0),
 		Size = UDim2.new(1, -(iconOffset + 10), 1, 0),
 		BackgroundTransparency = 1,
 		Font = Config.Font.Medium,
 		Text = self.Name,
 		TextColor3 = Theme.Palette.TextMuted,
 		TextSize = Config.TextSize.Tab,
 		TextXAlignment = Enum.TextXAlignment.Left,
 		TextTruncate = Enum.TextTruncate.AtEnd,
 		Parent = content,
 	})
 	Theme.Bind(label, "TextColor3", "TextMuted")

 	local page = Util.Create("CanvasGroup", {
 		Name = "TabPage",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		GroupTransparency = 1,
 		Visible = false,
 		Parent = window.Content,
 	})

 	local scroll = Scroll.new(page, {
 		Padding = { Top = 14, Right = 16, Bottom = 14, Left = 16 },
 		Spacing = Config.Metrics.ScrollSpacing,
 	})

 	self.Button = button
 	self.Icon = icon
 	self.Label = label
 	self.Content = content
 	self.Page = page
 	self.Scroll = scroll
 	self.Container = scroll.Content
 	self.Compact = false

 	local hovering = false

 	local function isGlyphIcon()
 		return icon ~= nil and typeof(icon) == "table" and icon.SetColor ~= nil
 	end

 	local function setIconColor(key)
 		if icon == nil then
 			return
 		end

 		if isGlyphIcon() then
 			icon:SetColor(key)
 		else
 			Theme.Bind(icon, "ImageColor3", key)
 		end
 	end

 	local function paint()
 		local selected = self.Active
 		local labelKey = selected and "Accent" or (hovering and "Text" or "TextMuted")

 		if selected then
 			button.BackgroundColor3 = Theme.Palette.AccentSoft
 			Motion.Spring(button, "BackgroundTransparency", 0, {
 				Stiffness = Config.Motion.Hover.Stiffness,
 				Damping = Config.Motion.Hover.Damping,
 			})
 		elseif hovering then
 			button.BackgroundColor3 = Theme.Palette.SurfaceHover
 			Motion.Spring(button, "BackgroundTransparency", 0.4, {
 				Stiffness = Config.Motion.Hover.Stiffness,
 				Damping = Config.Motion.Hover.Damping,
 			})
 		else
 			Motion.Spring(button, "BackgroundTransparency", 1, {
 				Stiffness = Config.Motion.Hover.Stiffness,
 				Damping = Config.Motion.Hover.Damping,
 			})
 		end

 		Theme.Bind(label, "TextColor3", labelKey)
 		setIconColor(labelKey)

 		if icon and not isGlyphIcon() then
 			Util.Tween(icon, { ImageTransparency = selected and 0 or 0.15 }, Util.Easing.Fast)
 		elseif icon then
 			icon:SetTransparency(selected and 0 or 0.1)
 		end

 		-- Icons lead the label by a hair on hover; selected tabs sit still.
 		local slide = hovering and not selected and 2 or 0
 		Motion.Spring(content, "Position", UDim2.fromOffset(slide, 0), {
 			Stiffness = Config.Motion.Hover.Stiffness,
 			Damping = Config.Motion.Hover.Damping,
 		})
 	end

 	self._paint = paint

 	button.MouseEnter:Connect(function()
 		hovering = true
 		paint()
 	end)

 	button.MouseLeave:Connect(function()
 		hovering = false
 		paint()
 	end)

 	button.MouseButton1Click:Connect(function()
 		self.Window:SelectTab(self)
 	end)

 	-- Holding a tab and moving it vertically reorders the sidebar. A small
 	-- threshold preserves normal click-to-select behaviour.
 	local held = false
 	local dragging = false
 	local originY = 0

 	local function nearestTabIndex(pointerY)
 		local nearest = 1
 		local distance = math.huge

 		for index, candidate in ipairs(self.Window.Tabs) do
 			if candidate.Button and candidate.Button.Visible then
 				local center = candidate.Button.AbsolutePosition.Y + candidate.Button.AbsoluteSize.Y / 2
 				local candidateDistance = math.abs(pointerY - center)
 				if candidateDistance < distance then
 					nearest = index
 					distance = candidateDistance
 				end
 			end
 		end

 		return nearest
 	end

 	self.Maid:Add(button.InputBegan:Connect(function(input)
 		local kind = input.UserInputType
 		if kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch then
 			held = true
 			dragging = false
 			originY = input.Position.Y
 		end
 	end))

 	self.Maid:Add(UserInputService.InputChanged:Connect(function(input)
 		if not held then
 			return
 		end

 		local kind = input.UserInputType
 		if kind ~= Enum.UserInputType.MouseMovement and kind ~= Enum.UserInputType.Touch then
 			return
 		end

 		if not dragging and math.abs(input.Position.Y - originY) >= 6 then
 			dragging = true
 		end

 		if dragging then
 			self.Window:MoveTab(self, nearestTabIndex(input.Position.Y))
 		end
 	end))

 	self.Maid:Add(UserInputService.InputEnded:Connect(function(input)
 		local kind = input.UserInputType
 		if kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch then
 			held = false
 			dragging = false
 		end
 	end))

 	self.Maid:Add(Theme.Changed:Connect(paint))

 	self:SetActive(false, true)

 	return self
 end

 --- Uses an icon rail when the window is narrower than a normal sidebar.
 function Tab:SetCompact(compact)
 	compact = compact == true
 	if self.Compact == compact then
 		return
 	end

 	self.Compact = compact
 	self.Label.Visible = not compact

 	if self.Icon then
 		local container = typeof(self.Icon) == "table" and self.Icon.Container or self.Icon
 		container.AnchorPoint = compact and Vector2.new(0.5, 0.5) or Vector2.new(0, 0.5)
 		container.Position = compact and UDim2.new(0.5, 0, 0.5, 0) or UDim2.new(0, 12, 0.5, 0)
 	end
 end

 --- Adds an explicit, titled group of controls.
 function Tab:Section(options)
 	local section = Section.new(self, options)
 	table.insert(self.Sections, section)
 	return section
 end

 --- Adds a control to the implicit (untitled) section at the top of the page.
 function Tab:Add(class, options)
 	if not self.DefaultSection then
 		self.DefaultSection = Section.new(self, { Unnamed = true })
 		table.insert(self.Sections, 1, self.DefaultSection)
 	end

 	return class.new(self.DefaultSection, options)
 end

 function Tab:Select()
 	self.Window:SelectTab(self)
 end

 --- Staggers the sections back in. Called when the page becomes visible.
 function Tab:Reveal()
 	local step = Config.Motion.RevealStep

 	for index, section in ipairs(self.Sections) do
 		section:Reveal((index - 1) * step)
 	end
 end

 function Tab:SetActive(active, instant)
 	self.Active = active and true or false
 	self._paint()

 	if self.Active then
 		self.Page.Visible = true

 		if instant then
 			self.Page.GroupTransparency = 0
 			self.Page.Position = UDim2.fromOffset(0, 0)
 		else
 			Motion.Curve(self.Page, "GroupTransparency", 0, { Curve = "Glide", Duration = 0.26 })
 			Motion.Curve(self.Page, "Position", UDim2.fromOffset(0, 0), {
 				From = UDim2.fromOffset(0, 6),
 				Curve = "Swift",
 				Duration = 0.34,
 			})
 		end

 		task.defer(function()
 			if self.Destroyed then
 				return
 			end

 			self.Scroll:Refresh()

 			if not instant then
 				self:Reveal()
 			end
 		end)
 	else
 		if instant then
 			self.Page.Visible = false
 			self.Page.GroupTransparency = 1
 		else
 			local animation = Motion.Curve(self.Page, "GroupTransparency", 1, {
 				Curve = "Exit",
 				Duration = 0.16,
 				OnComplete = function()
 					if not self.Active then
 						self.Page.Visible = false
 					end
 				end,
 			})

 			local _ = animation
 		end
 	end
 end

 function Tab:GetContainer()
 	return self.Container
 end

 function Tab:Destroy()
 	if self.Destroyed then
 		return
 	end
 	self.Destroyed = true

 	-- Unlink from the window so it no longer holds a dead tab (sidebar layout,
 	-- GetTab, MoveTab and drag-reorder all iterate this array).
 	local window = self.Window
 	if window and window.Tabs then
 		local tabIndex = table.find(window.Tabs, self)
 		if tabIndex then
 			table.remove(window.Tabs, tabIndex)

 			-- Keep sidebar ordering contiguous for the remaining tabs.
 			for index = tabIndex, #window.Tabs do
 				local sibling = window.Tabs[index]
 				if sibling.Button then
 					sibling.Button.LayoutOrder = index
 				end
 			end
 		end

 		-- Do not leave the window pointing at a destroyed tab.
 		if window.ActiveTab == self then
 			window.ActiveTab = nil
 		end
 	end

 	Motion.CancelAll(self)
 	self.Maid:Destroy()

 	-- Section:Destroy removes itself from this array, so forward ipairs would
 	-- skip every second section.
 	while #self.Sections > 0 do
 		self.Sections[#self.Sections]:Destroy()
 	end

 	self.Scroll:Destroy()

 	if self.Icon and typeof(self.Icon) == "table" and self.Icon.Destroy then
 		self.Icon:Destroy()
 	end

 	Motion.CancelTree(self.Page)
 	Motion.CancelTree(self.Button)
 	self.Page:Destroy()
 	self.Button:Destroy()
 end

 -- Expose every component directly on tabs; they land in the implicit section.
 local COMPONENT_NAMES = {
 	"Button",
 	"Toggle",
 	"Slider",
 	"Dropdown",
 	"Input",
 	"Keybind",
 	"Paragraph",
 	"Divider",
 	"ColorPicker",
 }

 for _, name in ipairs(COMPONENT_NAMES) do
 	Tab[name] = function(self, options)
 		return self:Add(Section.Components[name], options)
 	end
 end

 return Tab
end

__modules["Components/Toggle"] = function(script, require)
 --[[
 	Toggle
 	Row with a pill switch on the right. The knob runs on spring physics so fast
 	taps and slow releases both land with weight, and it grows slightly while
 	held.
 ]]

 local Config = require(script.Parent.Parent.Core.Config)
 local Element = require(script.Parent.Parent.Core.Element)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Toggle = setmetatable({}, { __index = Element })
 Toggle.__index = Toggle

 local TRACK_WIDTH = 38
 local TRACK_HEIGHT = 20
 local KNOB = 14
 local INSET = (TRACK_HEIGHT - KNOB) / 2
 local TRAVEL = TRACK_WIDTH - KNOB - INSET * 2

 function Toggle.new(section, options)
 	options = options or {}

 	local self = Element.new(Toggle, section, options, {
 		ControlWidth = TRACK_WIDTH,
 		ControlHeight = TRACK_HEIGHT,
 	})

 	self.Value = options.Default == true
 	self.Progress = self.Value and 1 or 0
 	self.Scale = 1

 	local track = Util.Create("TextButton", {
 		Name = "Switch",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		AutoButtonColor = false,
 		BackgroundColor3 = Theme.Palette.Control,
 		BorderSizePixel = 0,
 		ClipsDescendants = true,
 		Position = UDim2.fromScale(0.5, 0.5),
 		Size = UDim2.fromScale(1, 1),
 		Text = "",
 		TextTransparency = 1,
 		Parent = self.Control,
 	})
 	Util.Corner(track, Config.Radius.Pill)
 	local stroke = Util.Stroke(track, Theme.Palette.Outline, 1, 0.25)

 	local knob = Util.Create("Frame", {
 		Name = "Knob",
 		AnchorPoint = Vector2.new(0, 0.5),
 		BackgroundColor3 = Theme.Palette.TextMuted,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, INSET + TRAVEL * self.Progress, 0.5, 0),
 		Size = UDim2.fromOffset(KNOB, KNOB),
 		Parent = track,
 	})
 	Util.Corner(knob, Config.Radius.Pill)

 	self.Track = track
 	self.Knob = knob

 	local function paint(custom)
 		if not custom then
 			local on = self.Value
 			Theme.Bind(track, "BackgroundColor3", on and "Accent" or "Control")
 			Theme.Bind(knob, "BackgroundColor3", on and "AccentText" or "TextMuted")
 			Theme.Bind(stroke, "Color", on and "Accent" or "Outline")
 			Theme.Bind(stroke, "Transparency", on and 0.05 or 0.25)
 		end
 	end

 	self._paint = paint

 	local function moveKnob(value)
 		local progress = math.clamp(value, 0, 1)
 		knob.Position = UDim2.new(0, INSET + TRAVEL * progress, 0.5, 0)
 	end

 	function self.paint(animate)
 		local on = self.Value
 		Theme.Bind(track, "BackgroundColor3", on and "Accent" or "Control")
 		Theme.Bind(knob, "BackgroundColor3", on and "AccentText" or "TextMuted")
 		Theme.Bind(stroke, "Color", on and "Accent" or "Outline")
 		Theme.Bind(stroke, "Transparency", on and 0.05 or 0.25)

 		local target = on and 1 or 0

 		if animate == false then
 			self.Progress = target
 			moveKnob(target)
 			return
 		end

 		Motion.Spring(self, "Progress", target, {
 			Stiffness = Config.Motion.Toggle.Stiffness,
 			Damping = Config.Motion.Toggle.Damping,
 			OnUpdate = moveKnob,
 		})
 	end

 	local function setScale(value)
 		local size = KNOB * math.clamp(value, 1, 1.08)
 		local progress = math.clamp(self.Progress, 0, 1)
 		knob.Size = UDim2.fromOffset(size, size)
 		knob.Position = UDim2.new(0, INSET + TRAVEL * progress - (size - KNOB) / 2, 0.5, 0)
 	end

 	self._setScale = setScale

 	track.InputBegan:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
 			return
 		end

 		Motion.Spring(self, "Scale", 1.12, {
 			Stiffness = Config.Motion.Knob.Stiffness,
 			Damping = Config.Motion.Knob.Damping,
 			OnUpdate = setScale,
 		})
 	end)

 	track.InputEnded:Connect(function()
 		Motion.Spring(self, "Scale", 1, {
 			Stiffness = Config.Motion.Knob.Stiffness,
 			Damping = Config.Motion.Knob.Damping,
 			OnUpdate = setScale,
 		})
 	end)

 	track.MouseButton1Click:Connect(function()
 		if not self.Enabled then
 			return
 		end

 		self:SetValue(not self.Value)
 	end)

 	self.Maid:Add(Theme.Changed:Connect(function()
 		paint()
 	end))

 	self:SetControlEnabled(self.Enabled)
 	paint(false)

 	self:SetHoverable(true)
 	return self
 end

 function Toggle:SetValue(value, silent)
 	value = value == true

 	if self.Value == value then
 		return
 	end

 	self.Value = value
 	self.paint(true)

 	if not silent then
 		self:Fire(value)
 	end
 end

 function Toggle:GetValue()
 	return self.Value
 end

 function Toggle:SetControlEnabled(enabled)
 	self.Track.Active = enabled

 	Motion.Spring(self.Track, "BackgroundTransparency", enabled and 0 or 0.55, {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	})

 	Motion.Spring(self.Knob, "BackgroundTransparency", enabled and 0 or 0.4, {
 		Stiffness = Config.Motion.Hover.Stiffness,
 		Damping = Config.Motion.Hover.Damping,
 	})
 end

 return Toggle
end

__modules["Components/Tooltip"] = function(script, require)
 --[[
 	Tooltip
 	Hover hint anchored to an element row.

 	Rendered inside the window overlay so no pointer coordinate conversion is
 	needed and the bubble can never leave the window. It rises into place on a
 	spring instead of just appearing.
 ]]

 local Config = require(script.Parent.Parent.Core.Config)
 local Maid = require(script.Parent.Parent.Core.Maid)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Tooltip = {}
 Tooltip.__index = Tooltip

 local PADDING_X = 8
 local PADDING_Y = 4
 local TEXT_HEIGHT = 14

 function Tooltip.new(window)
 	local self = setmetatable({}, Tooltip)
 	self.Window = window
 	self.Maid = Maid.new()
 	self.Current = nil
 	self.Offset = 0

 	local frame = Util.Create("Frame", {
 		Name = "Tooltip",
 		BackgroundColor3 = Theme.Palette.ControlActive,
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromOffset(0, 0),
 		Visible = false,
 		ZIndex = 30,
 		Parent = window.Overlay,
 	})
 	Util.Corner(frame, Config.Radius.Small)
 	Theme.Bind(frame, "BackgroundColor3", "ControlActive")
 	Theme.Bind(Util.Stroke(frame, Theme.Palette.Outline, 1, 0.2), "Color", "Outline")

 	local label = Util.Create("TextLabel", {
 		Name = "Label",
 		BackgroundTransparency = 1,
 		Font = Config.Font.Medium,
 		Position = UDim2.fromOffset(PADDING_X, PADDING_Y),
 		Size = UDim2.new(0, 0, 0, TEXT_HEIGHT),
 		Text = "",
 		TextSize = Config.TextSize.Badge,
 		TextTransparency = 1,
 		TextXAlignment = Enum.TextXAlignment.Left,
 		TextYAlignment = Enum.TextYAlignment.Top,
 		ZIndex = 31,
 		Parent = frame,
 	})
 	Theme.Bind(label, "TextColor3", "Text")

 	self.Frame = frame
 	self.Label = label

 	return self
 end

 --- Attaches a hint to an element row.
 function Tooltip:Bind(element, text)
 	if text == nil or text == "" then
 		return
 	end

 	local row = element.Row
 	if row == nil then
 		return
 	end

 	local content = tostring(text)

 	local function show()
 		self.Current = element
 		self.Label.Text = content

 		local textWidth = math.ceil(Util.MeasureText(content, Config.TextSize.Badge, Config.Font.Medium))
 		local width = textWidth + PADDING_X * 2
 		local height = TEXT_HEIGHT + PADDING_Y * 2

 		self.Label.Size = UDim2.new(0, textWidth, 0, TEXT_HEIGHT)
 		self.Frame.Size = UDim2.fromOffset(width, height)
 		self.Frame.Visible = true

 		local window = self.Window.Frame
 		local scale = math.max(0.05, self.Window.Scale.Scale)
 		local windowSize = Vector2.new(window.AbsoluteSize.X / scale, window.AbsoluteSize.Y / scale)
 		local rowX = (row.AbsolutePosition.X - window.AbsolutePosition.X) / scale
 		local rowY = (row.AbsolutePosition.Y - window.AbsolutePosition.Y) / scale
 		local rowHeight = row.AbsoluteSize.Y / scale
 		local margin = Config.Metrics.PopupMargin
 		local x = rowX + row.AbsoluteSize.X / scale - width
 		local y = rowY - height - Config.Metrics.PopupGap

 		if y < margin then
 			y = rowY + rowHeight + Config.Metrics.PopupGap
 		end

 		local targetX = math.clamp(x, margin, math.max(margin, windowSize.X - width - margin))
 		local targetY = math.clamp(y, margin, math.max(margin, windowSize.Y - height - margin))

 		Motion.Curve(self.Frame, "Position", UDim2.fromOffset(targetX, targetY), {
 			From = UDim2.fromOffset(targetX, targetY + 4),
 			Curve = "Swift",
 			Duration = 0.24,
 		})

 		Motion.Spring(self.Label, "TextTransparency", 0, {
 			Stiffness = 500,
 			Damping = 34,
 		})

 		Motion.Spring(self.Frame, "BackgroundTransparency", 0.05, {
 			Stiffness = 500,
 			Damping = 34,
 		})
 	end

 	local function hide()
 		if self.Current ~= element then
 			return
 		end

 		self.Current = nil

 		Motion.Curve(self.Label, "TextTransparency", 1, { Curve = "Exit", Duration = 0.16 })
 		Motion.Curve(self.Frame, "BackgroundTransparency", 1, {
 			Curve = "Exit",
 			Duration = 0.2,
 			OnComplete = function()
 				if self.Current == nil then
 					self.Frame.Visible = false
 				end
 			end,
 		})
 	end

 	self.Reposition = function()
 		if self.Current == element then
 			show()
 		end
 	end

 	local targets = { row }
 	if element.Control then
 		table.insert(targets, element.Control)
 	end

 	for _, target in ipairs(targets) do
 		element.Maid:Add(target.MouseEnter:Connect(show))
 		element.Maid:Add(target.MouseLeave:Connect(hide))
 	end

 	element.Maid:Add(function()
 		if self.Current == element then
 			hide()
 		end
 	end)
 end

 function Tooltip:Destroy()
 	self.Maid:Destroy()
 	self.Frame:Destroy()
 end

 return Tooltip
end

__modules["Components/Window"] = function(script, require)
 --[[
 	Window
 	Top level container: screen GUI, draggable frame, sidebar with tabs, content
 	area, popup overlay, resize grip, tooltips and the notification stack.
 ]]

 local Players = game:GetService("Players")

 local Config = require(script.Parent.Parent.Core.Config)
 local Effects = require(script.Parent.Parent.Core.Effects)
 local Maid = require(script.Parent.Parent.Core.Maid)
 local Motion = require(script.Parent.Parent.Core.Motion)
 local Signal = require(script.Parent.Parent.Core.Signal)
 local Theme = require(script.Parent.Parent.Core.Theme)
 local Util = require(script.Parent.Parent.Core.Util)

 local Icon = require(script.Parent.Icon)
 local Notification = require(script.Parent.Notification)
 local Tab = require(script.Parent.Tab)
 local Tooltip = require(script.Parent.Tooltip)

 local Window = {}
 Window.__index = Window

 function Window.new(options)
 	options = options or {}

 	local player = Players.LocalPlayer
 	assert(player ~= nil, "[Lumen] windows can only be created on the client")

 	if options.Theme ~= nil or options.Accent ~= nil then
 		Theme.Set(options.Theme or Theme.Name, options.Accent)
 	end

 	local self = setmetatable({}, Window)
 	self.Options = options
 	self.Maid = Maid.new()
 	self.Tabs = {}
 	self.ActiveTab = nil
 	self.Minimized = false
 	self.Closed = false
 	self.DestroyedSignal = Signal.new()

 	local parent = options.Parent or player:WaitForChild("PlayerGui")
 	local screenGui
 	local ownsScreenGui = false

 	if parent:IsA("ScreenGui") then
 		screenGui = parent
 	else
 		screenGui = Util.Create("ScreenGui", {
 			Name = options.Name or "Lumen",
 			DisplayOrder = options.DisplayOrder or 100,
 			IgnoreGuiInset = true,
 			ResetOnSpawn = false,
 			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
 			Parent = parent,
 		})
 		ownsScreenGui = true
 	end

 	local metrics = Config.Window
 	local initialScale = math.clamp(options.Scale or 1, 0.5, 2)
 	local camera = workspace.CurrentCamera
 	local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
 	local available = Vector2.new(
 		(viewport.X - Config.Metrics.ViewportMargin * 2) / initialScale,
 		(viewport.Y - Config.Metrics.ViewportMargin * 2) / initialScale
 	)
 	local maximum = Vector2.new(
 		math.max(1, math.min(metrics.MaxWidth, available.X)),
 		math.max(metrics.TopbarHeight, math.min(metrics.MaxHeight, available.Y))
 	)
 	local minimum = Vector2.new(math.min(metrics.MinWidth, maximum.X), math.min(metrics.MinHeight, maximum.Y))
 	local width = math.clamp(options.Size and options.Size.X or metrics.Width, minimum.X, maximum.X)
 	local height = math.clamp(options.Size and options.Size.Y or metrics.Height, minimum.Y, maximum.Y)
 	local origin = Vector2.new(
 		math.floor(math.max(0, (viewport.X - width) / 2)),
 		math.floor(math.max(0, (viewport.Y - height) / 2))
 	)

 	-- This layer is reparented into the shell below. Keeping it local prevents a
 	-- window's backdrop setting from dimming the game world or another GUI.
 	local backdrop = Util.Create("Frame", {
 		Name = "LocalBackdropDim",
 		BackgroundColor3 = Color3.new(0, 0, 0),
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		ZIndex = 0,
 		Parent = screenGui,
 	})

 	local root = Util.Create("CanvasGroup", {
 		Name = "LumenRoot",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		GroupTransparency = 1,
 		ZIndex = 1,
 		Parent = screenGui,
 	})

 	-- Interface scale: one UIScale drives the whole shell.
 	local scale = Util.Create("UIScale", {
 		Scale = initialScale,
 		Parent = root,
 	})

 	local window = Util.Create("Frame", {
 		Name = "Window",
 		Active = true,
 		BackgroundColor3 = Theme.Palette.Window,
 		BorderSizePixel = 0,
 		ClipsDescendants = true,
 		Position = UDim2.fromOffset(origin.X, origin.Y + 12),
 		Size = UDim2.fromOffset(width, height),
 		Parent = root,
 	})
 	Util.Corner(window, Config.Radius.Window)
 	Theme.Bind(window, "BackgroundColor3", "Window")

 	-- Keep an opaque shell behind all chrome. Surface opacity is allowed to vary,
 	-- but the game world must never leak through seams, rounded corners or the
 	-- sidebar/content boundary.
 	local shellSurface = Util.Create("Frame", {
 		Name = "ShellSurface",
 		BackgroundColor3 = Theme.Palette.Window,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		ZIndex = 0,
 		Parent = window,
 	})
 	Util.Corner(shellSurface, Config.Radius.Window)
 	Theme.Bind(shellSurface, "BackgroundColor3", "Window")
 	backdrop.Parent = window
 	Util.Corner(backdrop, Config.Radius.Window)
 	local outline = Util.Stroke(window, Theme.Palette.Outline, 1, 0.3)
 	Theme.Bind(outline, "Color", "Outline")
 	self.Stroke = outline

 	-- Native drop shadow, present on clients that expose UIShadow.
 	local shadow = Util.AddShadow(window, Theme.Palette.Shadow, { Blur = 22, Transparency = 0.5, OffsetY = 8 })
 	if shadow then
 		self.Maid:Add(Theme.Changed:Connect(function(palette)
 			pcall(function()
 				shadow.Color = palette.Shadow
 			end)
 		end))
 	end

 	-- Subtle top light so the surface does not read as a flat rectangle.
 	local sheen = Util.Create("Frame", {
 		Name = "Sheen",
 		BackgroundColor3 = Theme.Palette.WindowGradient,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		ZIndex = 1,
 		Parent = window,
 	})
 	Util.Corner(sheen, Config.Radius.Window)
 	Theme.Bind(sheen, "BackgroundColor3", "WindowGradient")
 	Util.Create("UIGradient", {
 		Rotation = 90,
 		Transparency = NumberSequence.new({
 			NumberSequenceKeypoint.new(0, 0.84),
 			NumberSequenceKeypoint.new(1, 1),
 		}),
 		Parent = sheen,
 	})

 	-------------------------------------------------------------------------
 	-- Topbar
 	-------------------------------------------------------------------------

 	local topbar = Util.Create("Frame", {
 		Name = "Topbar",
 		Active = true,
 		BackgroundColor3 = Theme.Palette.Topbar,
 		BorderSizePixel = 0,
 		Size = UDim2.new(1, 0, 0, metrics.TopbarHeight),
 		ZIndex = 4,
 		Parent = window,
 	})
 	-- Cornered explicitly as well as clipped, so the shell always reads round.
 	Util.Corner(topbar, Config.Radius.Window)
 	Theme.Bind(topbar, "BackgroundColor3", "Topbar")

 	Theme.Bind(
 		Util.Create("Frame", {
 			Name = "Border",
 			BackgroundColor3 = Theme.Palette.Outline,
 			BackgroundTransparency = 0.55,
 			BorderSizePixel = 0,
 			Size = UDim2.new(1, -2, 0, 1),
 			Position = UDim2.new(0, 1, 1, -1),
 			Parent = topbar,
 		}),
 		"BackgroundColor3",
 		"Outline"
 	)

 	local heading = Util.Create("Frame", {
 		Name = "Heading",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, 14, 0, 0),
 		Size = UDim2.new(0, 0, 1, 0),
 		AutomaticSize = Enum.AutomaticSize.X,
 		Parent = topbar,
 	})
 	local headingLayout = Util.List(heading, 8, true)
 	headingLayout.VerticalAlignment = Enum.VerticalAlignment.Center

 	-- Brand mark: keeps the shell from looking like an anonymous grey box.
 	local mark = Util.Create("Frame", {
 		Name = "Mark",
 		BackgroundColor3 = Theme.Palette.AccentSoft,
 		BorderSizePixel = 0,
 		Size = UDim2.fromOffset(22, 22),
 		ZIndex = 0,
 		Parent = heading,
 	})
 	Util.Corner(mark, Config.Radius.Small + 2)
 	Theme.Bind(mark, "BackgroundColor3", "AccentSoft")

 	local markIcon = Icon.new(mark, options.Mark or "sparkles", Config.Icons.BrandSize, "Accent")
 	markIcon.Container.AnchorPoint = Vector2.new(0.5, 0.5)
 	markIcon.Container.Position = UDim2.fromScale(0.5, 0.5)
 	self.Mark = markIcon

 	local titleLabel = Util.Create("TextLabel", {
 		Name = "Title",
 		BackgroundTransparency = 1,
 		Font = Config.Font.Bold,
 		Size = UDim2.new(0, 0, 0, 18),
 		AutomaticSize = Enum.AutomaticSize.X,
 		Text = options.Title or "Lumen",
 		TextSize = Config.TextSize.Title,
 		TextXAlignment = Enum.TextXAlignment.Left,
 		Parent = heading,
 	})
 	Theme.Bind(titleLabel, "TextColor3", "Text")

 	local subtitleLabel = Util.Create("TextLabel", {
 		Name = "Subtitle",
 		BackgroundTransparency = 1,
 		Font = Config.Font.Regular,
 		Size = UDim2.new(0, 0, 0, 16),
 		AutomaticSize = Enum.AutomaticSize.X,
 		Text = options.Subtitle or "",
 		TextSize = Config.TextSize.Subtitle,
 		TextXAlignment = Enum.TextXAlignment.Left,
 		Visible = options.Subtitle ~= nil and options.Subtitle ~= "",
 		Parent = heading,
 	})
 	Theme.Bind(subtitleLabel, "TextColor3", "TextMuted")

 	local controls = Util.Create("Frame", {
 		Name = "Controls",
 		AnchorPoint = Vector2.new(1, 0.5),
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.new(1, -10, 0.5, 0),
 		Size = UDim2.new(0, 74, 0, 28),
 		ZIndex = 2,
 		Parent = topbar,
 	})
 	local controlsLayout = Util.List(controls, 6, true)
 	controlsLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right

 	--- Builds one topbar control with hover feedback and a glyph icon.
 	local function createControlButton(name, glyph, hoverKey)
 		local button = Util.Create("TextButton", {
 			Name = name,
 			AutoButtonColor = false,
 			BackgroundColor3 = Theme.Palette.Control,
 			BackgroundTransparency = 1,
 			BorderSizePixel = 0,
 			ClipsDescendants = true,
 			Size = UDim2.fromOffset(34, 26),
 			Text = "",
 			TextTransparency = 1,
 			ZIndex = 2,
 			Parent = controls,
 		})
 		Util.Corner(button, Config.Radius.Small)

 		local icon = Icon.new(button, glyph, Config.Icons.TopbarSize, "TextMuted")
 		icon.Container.AnchorPoint = Vector2.new(0.5, 0.5)
 		icon.Container.Position = UDim2.fromScale(0.5, 0.5)

 		local sheen = Effects.Sheen(button, { Color = Theme.Palette.Text, ZIndex = 4 })
 		local hovered = false

 		local function paint()
 			icon:SetColor(hovered and hoverKey or "TextMuted")

 			Motion.Spring(button, "BackgroundTransparency", hovered and 0.2 or 1, {
 				Stiffness = Config.Motion.Hover.Stiffness,
 				Damping = Config.Motion.Hover.Damping,
 			})
 		end

 		button.MouseEnter:Connect(function()
 			hovered = true
 			paint()
 			sheen.Play()
 		end)

 		button.MouseLeave:Connect(function()
 			hovered = false
 			paint()
 		end)

 		button.InputBegan:Connect(function(input)
 			local inputType = input.UserInputType
 			if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
 				Motion.Spring(button, "BackgroundTransparency", 0.08, { Stiffness = 900, Damping = 40 })
 			end
 		end)

 		self.Maid:Add(Theme.Changed:Connect(paint))
 		paint()

 		return button
 	end

 	local minimizeButton = createControlButton("Minimize", "minus", "Text")
 	local closeButton = createControlButton("Close", "x", "Error")

 	if options.Minimizable == false then
 		minimizeButton.Visible = false
 	end

 	-------------------------------------------------------------------------
 	-- Sidebar
 	-------------------------------------------------------------------------

 	local sidebar = Util.Create("Frame", {
 		Name = "Sidebar",
 		BackgroundColor3 = Theme.Palette.Sidebar,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, 0, 0, metrics.TopbarHeight),
 		Size = UDim2.new(0, metrics.SidebarWidth, 1, -metrics.TopbarHeight),
 		ZIndex = 3,
 		Parent = window,
 	})
 	Util.Corner(sidebar, Config.Radius.Window)
 	Theme.Bind(sidebar, "BackgroundColor3", "Sidebar")

 	Theme.Bind(
 		Util.Create("Frame", {
 			Name = "Border",
 			BackgroundColor3 = Theme.Palette.Outline,
 			BackgroundTransparency = 0.55,
 			BorderSizePixel = 0,
 			Position = UDim2.new(1, -1, 0, 1),
 			Size = UDim2.new(0, 1, 1, -2),
 			Parent = sidebar,
 		}),
 		"BackgroundColor3",
 		"Outline"
 	)

 	local tabList = Util.Create("ScrollingFrame", {
 		Name = "Tabs",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, metrics.SidebarPadding, 0, metrics.SidebarPadding),
 		Size = UDim2.new(1, -(metrics.SidebarPadding * 2), 1, -(metrics.SidebarPadding * 2 + 22)),
 		CanvasSize = UDim2.new(),
 		AutomaticCanvasSize = Enum.AutomaticSize.Y,
 		ScrollBarThickness = 0,
 		ScrollingDirection = Enum.ScrollingDirection.Y,
 		ElasticBehavior = Enum.ElasticBehavior.WhenScrollable,
 		Parent = sidebar,
 	})
 	Util.List(tabList, metrics.TabSpacing)

 	-- Accent rail that fills the active tab's full height. A short centered
 	-- dash left visible gaps at the tab edges and looked unfinished.
 	local indicator = Util.Create("Frame", {
 		Name = "TabIndicator",
 		AnchorPoint = Vector2.new(0, 0.5),
 		BackgroundColor3 = Theme.Palette.Accent,
 		BorderSizePixel = 0,
 		Position = UDim2.fromOffset(metrics.SidebarPadding - 5, metrics.SidebarPadding + metrics.TabHeight / 2),
 		Size = UDim2.fromOffset(3, metrics.TabHeight),
 		ZIndex = 4,
 		Visible = false,
 		Parent = sidebar,
 	})
 	Util.Corner(indicator, Config.Radius.Pill)
 	Theme.Bind(indicator, "BackgroundColor3", "Accent")

 	local footer = Util.Create("Frame", {
 		Name = "Footer",
 		AnchorPoint = Vector2.new(0, 1),
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, metrics.SidebarPadding + 4, 1, -10),
 		Size = UDim2.new(1, -(metrics.SidebarPadding * 2 + 8), 0, 14),
 		Parent = sidebar,
 	})

 	local footerIcon = Icon.new(footer, "sparkles", Config.Icons.FooterSize, "TextDim")
 	footerIcon.Container.AnchorPoint = Vector2.new(0, 0.5)
 	footerIcon.Container.Position = UDim2.new(0, 0, 0.5, 0)

 	local versionLabel = Util.Create("TextLabel", {
 		Name = "Version",
 		BackgroundTransparency = 1,
 		Font = Config.Font.Regular,
 		Position = UDim2.fromOffset(18, 0),
 		Size = UDim2.new(1, -18, 1, 0),
 		Text = options.Footer or ("Lumen  " .. Config.Version),
 		TextSize = Config.TextSize.Badge,
 		TextXAlignment = Enum.TextXAlignment.Left,
 		TextYAlignment = Enum.TextYAlignment.Center,
 		Parent = footer,
 	})
 	Theme.Bind(versionLabel, "TextColor3", "TextDim")

 	-------------------------------------------------------------------------
 	-- Content and overlay
 	-------------------------------------------------------------------------

 	local content = Util.Create("Frame", {
 		Name = "Content",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		ClipsDescendants = true,
 		Position = UDim2.new(0, metrics.SidebarWidth, 0, metrics.TopbarHeight),
 		Size = UDim2.new(1, -metrics.SidebarWidth, 1, -metrics.TopbarHeight),
 		ZIndex = 2,
 		Parent = window,
 	})

 	-- A persistent base surface prevents the empty space between cards from
 	-- exposing a differently tinted parent layer during scale and fade motion.
 	local contentSurface = Util.Create("Frame", {
 		Name = "ContentSurface",
 		BackgroundColor3 = Theme.Palette.Window,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		ZIndex = 0,
 		Parent = content,
 	})
 	Theme.Bind(contentSurface, "BackgroundColor3", "Window")

 	local overlay = Util.Create("Frame", {
 		Name = "Overlay",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		ZIndex = 20,
 		Parent = window,
 	})

 	local grip = Util.Create("Frame", {
 		Name = "ResizeGrip",
 		Active = true,
 		AnchorPoint = Vector2.new(1, 1),
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.new(1, -2, 1, -2),
 		Size = UDim2.fromOffset(16, 16),
 		ZIndex = 21,
 		Visible = options.Resizable ~= false,
 		Parent = window,
 	})

 	local gripDots = {}
 	for index = 1, 3 do
 		local dot = Util.Create("Frame", {
 			Name = "Dot" .. index,
 			AnchorPoint = Vector2.new(1, 1),
 			BackgroundColor3 = Theme.Palette.TextDim,
 			BorderSizePixel = 0,
 			Position = UDim2.new(1, -2 - (index - 1) * 5, 1, -2),
 			Size = UDim2.fromOffset(2, 2),
 			Parent = grip,
 		})
 		Util.Corner(dot, 1)
 		table.insert(gripDots, dot)

 		local mirrored = Util.Create("Frame", {
 			Name = "Dot" .. index .. "B",
 			AnchorPoint = Vector2.new(1, 1),
 			BackgroundColor3 = Theme.Palette.TextDim,
 			BorderSizePixel = 0,
 			Position = UDim2.new(1, -2, 1, -2 - (index - 1) * 5),
 			Size = UDim2.fromOffset(2, 2),
 			Parent = grip,
 		})
 		Util.Corner(mirrored, 1)
 		table.insert(gripDots, mirrored)
 	end

 	for _, dot in ipairs(gripDots) do
 		Theme.Bind(dot, "BackgroundColor3", "TextDim")
 	end

 	local function paintGrip(active)
 		for _, dot in ipairs(gripDots) do
 			Theme.Bind(dot, "BackgroundColor3", active and "Accent" or "TextDim")
 		end
 	end

 	grip.MouseEnter:Connect(function()
 		paintGrip(true)
 	end)

 	grip.MouseLeave:Connect(function()
 		paintGrip(false)
 	end)

 	self.ScreenGui = screenGui
 	self.OwnsScreenGui = ownsScreenGui
 	self.Root = root
 	self.Backdrop = backdrop
 	self.Scale = scale
 	self.Blur = nil -- Kept for backwards compatibility; this is now a local GUI effect.
 	self.ActivePopup = nil
 	self.Frame = window
 	self.ShellSurface = shellSurface
 	self.Topbar = topbar
 	self.Sidebar = sidebar
 	self.TabList = tabList
 	self.Indicator = indicator
 	self.Content = content
 	self.ContentSurface = contentSurface
 	self.Overlay = overlay
 	self.SidebarWidth = metrics.SidebarWidth

 	self.Tooltip = Tooltip.new(self)
 	self.Notifications = Notification.new(self)

 	-------------------------------------------------------------------------
 	-- Behaviour
 	-------------------------------------------------------------------------

 	if options.Backdrop then
 		backdrop.BackgroundTransparency = 1 - options.Backdrop
 	end

 	if options.Draggable ~= false then
 		self.Maid:Add(Util.AttachDrag(window, topbar, {
 			Scale = function()
 				return scale.Scale
 			end,
 			TitlebarHeight = metrics.TopbarHeight,
 			MinimumVisibleTitlebar = metrics.MinimumVisibleTitlebar,
 			OnDragStart = function()
 				if self.Stroke then
 					Motion.Spring(self.Stroke, "Transparency", 0.08, {
 						Stiffness = Config.Motion.Hover.Stiffness,
 						Damping = Config.Motion.Hover.Damping,
 					})
 				end
 			end,
 			OnDragEnd = function()
 				if self.Stroke then
 					Motion.Spring(self.Stroke, "Transparency", 0.3, {
 						Stiffness = Config.Motion.Hover.Stiffness,
 						Damping = Config.Motion.Hover.Damping,
 					})
 				end
 			end,
 		}))
 	end

 	if options.Resizable ~= false then
 		self.Maid:Add(Util.AttachResize(window, grip, {
 			Minimum = Vector2.new(metrics.MinWidth, metrics.MinHeight),
 			Maximum = Vector2.new(metrics.MaxWidth, metrics.MaxHeight),
 			Scale = function()
 				return scale.Scale
 			end,
 			MaximumForViewport = function()
 				return self:GetMaximumSize()
 			end,
 			OnResize = function()
 				self:ClampToViewport()
 				self:ReflowPopups()
 			end,
 		}))
 	end

 	local function paintWindow()
 		paintGrip(false)
 	end

 	self.Maid:Add(Theme.Changed:Connect(paintWindow))

 	-- A viewport may change due to orientation, a mobile safe area or camera
 	-- replacement. Keep the titlebar and resize grip reachable in every case.
 	local viewportConnection = nil
 	local function watchViewport()
 		if viewportConnection then
 			viewportConnection:Disconnect()
 			viewportConnection = nil
 		end

 		local currentCamera = workspace.CurrentCamera
 		if currentCamera and currentCamera.GetPropertyChangedSignal then
 			viewportConnection = currentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
 				self:ClampToViewport()
 				self:ReflowPopups()
 			end)
 		end
 		self:ClampToViewport()
 	end
 	self.Maid:Add(function()
 		if viewportConnection then
 			viewportConnection:Disconnect()
 		end
 	end)
 	if workspace.GetPropertyChangedSignal then
 		self.Maid:Add(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(watchViewport))
 	end
 	watchViewport()

 	minimizeButton.MouseButton1Click:Connect(function()
 		self:ToggleMinimize()
 	end)

 	closeButton.MouseButton1Click:Connect(function()
 		self:Close()
 	end)

 	self.Maid:Add(function()
 		self.DestroyedSignal:Destroy()
 	end)

 	-- Opening animation: a rising fade rather than a plain appear.
 	task.defer(function()
 		if self.Closed then
 			return
 		end

 		Motion.Curve(window, "Position", UDim2.fromOffset(origin.X, origin.Y), {
 			From = UDim2.fromOffset(origin.X, origin.Y + 22),
 			Curve = Config.Motion.Entrance.Curve,
 			Duration = Config.Motion.Entrance.Duration,
 		})

 		Motion.Curve(root, "GroupTransparency", 0, {
 			Curve = "Glide",
 			Duration = 0.34,
 		})
 	end)

 	return self
 end

 ---------------------------------------------------------------------------
 -- Tabs
 ---------------------------------------------------------------------------

 function Window:Tab(options)
 	local tab = Tab.new(self, options)
 	table.insert(self.Tabs, tab)
 	tab.Button.LayoutOrder = #self.Tabs
 	tab:SetCompact(self:GetEffectiveSidebarWidth() <= 88)

 	if options and options.Selected then
 		self:SelectTab(tab)
 	elseif self.ActiveTab == nil then
 		self:SelectTab(tab)
 	end

 	return tab
 end

 function Window:GetTab(name)
 	for _, tab in ipairs(self.Tabs) do
 		if tab.Name == name then
 			return tab
 		end
 	end
 	return nil
 end

 function Window:SelectTab(tab)
 	if self.ActiveTab == tab or tab == nil then
 		return
 	end

 	local previous = self.ActiveTab
 	self.ActiveTab = tab

 	if previous then
 		previous:SetActive(false)
 	end

 	tab:SetActive(true)
 	self:SlideIndicator(tab)
 end

 --- Springs the sidebar rail to the active tab.
 function Window:SlideIndicator(tab, instant)
 	local indicator = self.Indicator
 	local sidebar = self.Sidebar

 	if indicator == nil or tab == nil or tab.Button == nil then
 		return
 	end

 	local button = tab.Button
 	local hidden = self.Minimized or not sidebar.Visible or not button.Visible
 	indicator.Visible = not hidden

 	if hidden then
 		return
 	end

 	-- Absolute coordinates include UIScale, while the indicator is parented to
 	-- the scaled sidebar. Convert to sidebar-local units before positioning.
 	local scale = self.Scale and math.max(0.05, self.Scale.Scale) or 1
 	local center = (button.AbsolutePosition.Y - sidebar.AbsolutePosition.Y + button.AbsoluteSize.Y / 2) / scale

 	local target = UDim2.fromOffset(indicator.Position.X.Offset, center)
 	if instant then
 		indicator.Position = target
 		return
 	end

 	Motion.Curve(indicator, "Position", target, {
 		Curve = "Swift",
 		Duration = 0.22,
 	})
 end

 --- Reorders the tab model and its UIListLayout children after a tab drag.
 function Window:MoveTab(tab, targetIndex)
 	local fromIndex = table.find(self.Tabs, tab)
 	if fromIndex == nil then
 		return false
 	end

 	targetIndex = math.clamp(targetIndex, 1, #self.Tabs)
 	if fromIndex == targetIndex then
 		return false
 	end

 	table.remove(self.Tabs, fromIndex)
 	table.insert(self.Tabs, targetIndex, tab)

 	for index, entry in ipairs(self.Tabs) do
 		entry.Button.LayoutOrder = index
 	end

 	self:SlideIndicator(self.ActiveTab)
 	return true
 end

 ---------------------------------------------------------------------------
 -- Geometry and popup coordination
 ---------------------------------------------------------------------------

 function Window:GetMaximumSize()
 	local camera = workspace.CurrentCamera
 	local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
 	local scale = math.max(0.05, self.Scale.Scale)
 	local margin = Config.Metrics.ViewportMargin
 	return Vector2.new(
 		math.max(1, math.min(Config.Window.MaxWidth, viewport.X / scale - margin * 2)),
 		math.max(Config.Window.TopbarHeight, math.min(Config.Window.MaxHeight, viewport.Y / scale - margin * 2))
 	)
 end

 --- Keeps the shell usable when scale, size or viewport changes.
 function Window:ClampToViewport()
 	if self.Destroyed or self.Closed then
 		return
 	end

 	local maximum = self:GetMaximumSize()
 	local minimum =
 		Vector2.new(math.min(Config.Window.MinWidth, maximum.X), math.min(Config.Window.MinHeight, maximum.Y))
 	local size = Vector2.new(self.Frame.Size.X.Offset, self.Frame.Size.Y.Offset)
 	if not self.Minimized then
 		size = Vector2.new(math.clamp(size.X, minimum.X, maximum.X), math.clamp(size.Y, minimum.Y, maximum.Y))
 		self.Frame.Size = UDim2.fromOffset(size.X, size.Y)
 	end

 	local camera = workspace.CurrentCamera
 	local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
 	local scale = math.max(0.05, self.Scale.Scale)
 	local baseViewport = Vector2.new(viewport.X / scale, viewport.Y / scale)
 	local visible = math.min(size.X, Config.Window.MinimumVisibleTitlebar)
 	local x =
 		math.clamp(self.Frame.Position.X.Offset, visible - size.X, math.max(visible - size.X, baseViewport.X - visible))
 	local y = math.clamp(self.Frame.Position.Y.Offset, 0, math.max(0, baseViewport.Y - Config.Window.TopbarHeight))
 	self.Frame.Position = UDim2.fromOffset(x, y)
 	self:RefreshSidebarLayout()
 end

 --- Retains the requested sidebar width on regular displays, but uses a
 --- compact icon rail when a portrait viewport would otherwise starve content.
 function Window:GetEffectiveSidebarWidth()
 	if self.Frame.Size.X.Offset <= 420 then
 		return 80
 	end
 	return self.SidebarWidth
 end

 function Window:RefreshSidebarLayout()
 	if not self.Sidebar or not self.Content then
 		return
 	end

 	local width = self:GetEffectiveSidebarWidth()
 	self.Sidebar.Size = UDim2.new(0, width, 1, -Config.Window.TopbarHeight)
 	self.Content.Position = UDim2.new(0, width, 0, Config.Window.TopbarHeight)
 	self.Content.Size = UDim2.new(1, -width, 1, -Config.Window.TopbarHeight)

 	for _, tab in ipairs(self.Tabs) do
 		tab:SetCompact(width <= 88)
 	end

 	if self.ActiveTab then
 		self.ActiveTab.Scroll:Refresh()
 	end
 	self:ReflowPopups()
 end

 --- One popup at a time prevents overlapping menus and duplicate outside listeners.
 function Window:OpenPopup(popup)
 	if self.ActivePopup and self.ActivePopup ~= popup and self.ActivePopup.Hide then
 		self.ActivePopup:Hide()
 	end
 	self.ActivePopup = popup
 end

 function Window:ClosePopup(popup)
 	if self.ActivePopup == popup then
 		self.ActivePopup = nil
 	end
 end

 function Window:ReflowPopups()
 	if self.ActivePopup and self.ActivePopup.Reposition then
 		self.ActivePopup:Reposition()
 	end
 	if self.Tooltip and self.Tooltip.Reposition then
 		self.Tooltip:Reposition()
 	end
 end

 ---------------------------------------------------------------------------
 -- Chrome
 ---------------------------------------------------------------------------

 function Window:SetTitle(text)
 	self.Topbar.Heading.Title.Text = tostring(text)
 end

 function Window:SetSubtitle(text)
 	local label = self.Topbar.Heading.Subtitle
 	label.Text = text == nil and "" or tostring(text)
 	label.Visible = text ~= nil and text ~= ""
 end

 function Window:SetAccentColor(color)
 	Theme.Set(Theme.Name, color)
 end

 function Window:SetTheme(name)
 	Theme.Set(name)
 end

 function Window:SetSize(size)
 	if typeof(size) ~= "Vector2" then
 		return
 	end
 	local maximum = self:GetMaximumSize()
 	local minimum =
 		Vector2.new(math.min(Config.Window.MinWidth, maximum.X), math.min(Config.Window.MinHeight, maximum.Y))
 	self.Frame.Size =
 		UDim2.fromOffset(math.clamp(size.X, minimum.X, maximum.X), math.clamp(size.Y, minimum.Y, maximum.Y))
 	self:ClampToViewport()
 	self:ReflowPopups()
 end

 function Window:ToggleMinimize()
 	if self.Minimized then
 		self:Restore()
 	else
 		self:Minimize()
 	end
 end

 function Window:Minimize(animate)
 	if self.Minimized then
 		return
 	end

 	self.Minimized = true
 	self.RestoredSize = self.Frame.AbsoluteSize

 	self.Sidebar.Visible = false
 	self.Content.Visible = false
 	self.Indicator.Visible = false
 	self.Frame.ResizeGrip.Visible = false

 	local target = UDim2.new(0, self.RestoredSize.X, 0, Config.Window.TopbarHeight)

 	if animate == false then
 		self.Frame.Size = target
 	else
 		Motion.Curve(self.Frame, "Size", target, { Curve = "Glide", Duration = 0.32 })
 	end
 end

 function Window:Restore(animate)
 	if not self.Minimized then
 		return
 	end

 	self.Minimized = false

 	self.Sidebar.Visible = true
 	self.Content.Visible = true
 	self.Frame.ResizeGrip.Visible = self.Options.Resizable ~= false

 	local size = self.RestoredSize or Vector2.new(Config.Window.Width, Config.Window.Height)
 	local target = UDim2.fromOffset(size.X, size.Y)

 	if animate == false then
 		self.Frame.Size = target
 	else
 		Motion.Curve(self.Frame, "Size", target, { Curve = "Glide", Duration = 0.36 })
 	end

 	task.defer(function()
 		if self.ActiveTab then
 			self.ActiveTab.Scroll:Refresh()
 		end

 		self:SlideIndicator(self.ActiveTab)
 	end)
 end

 function Window:SetVisible(visible)
 	self.Root.Visible = visible and true or false
 end

 ---------------------------------------------------------------------------
 -- Appearance
 ---------------------------------------------------------------------------

 --- Scales the whole shell. Useful for a resolution or comfort setting.
 function Window:SetScale(value, animate)
 	value = math.clamp(value, 0.5, 2)

 	if animate == false then
 		self.Scale.Scale = value
 		self:ClampToViewport()
 		self:ReflowPopups()
 		self:SlideIndicator(self.ActiveTab, true)
 		return
 	end

 	Motion.Curve(self.Scale, "Scale", value, {
 		Curve = "Soft",
 		Duration = 0.38,
 		OnUpdate = function()
 			self:ClampToViewport()
 			self:ReflowPopups()
 			self:SlideIndicator(self.ActiveTab, true)
 		end,
 	})
 end

 --- Softens the chrome while the shell itself remains opaque. This avoids
 --- transparency seams and keeps the effect local to Lumen.
 function Window:SetTransparency(alpha, animate)
 	alpha = math.clamp(alpha, 0, 0.85)

 	local function apply(target)
 		if animate == false then
 			target.BackgroundTransparency = alpha
 			return
 		end

 		Motion.Curve(target, "BackgroundTransparency", alpha, {
 			Curve = "Soft",
 			Duration = 0.24,
 		})
 	end

 	apply(self.Topbar)
 	apply(self.Sidebar)
 	apply(self.ContentSurface)
 end

 --- Dims only the window's local surface. 0 clears it without affecting the
 --- game world, CoreGui or other ScreenGuis.
 function Window:SetBackdrop(alpha, animate)
 	alpha = math.clamp(alpha or 0, 0, 1)
 	local target = 1 - alpha

 	if animate == false then
 		self.Backdrop.BackgroundTransparency = target
 		return
 	end

 	Motion.Curve(self.Backdrop, "BackgroundTransparency", target, {
 		Curve = "Glide",
 		Duration = 0.22,
 	})
 end

 --- Applies a local frosted layer inside this window only. Roblox BlurEffect is
 --- global to Lighting and cannot be clipped to a ScreenGui, so it must not be
 --- used for a per-window effect.
 function Window:SetBlur(enabled, size, animate)
 	size = size or Config.Window.BlurSize
 	local transparency = math.clamp(0.3 - (size / Config.Window.BlurSize) * 0.16, 0.06, 0.2)

 	if enabled then
 		if self.Blur == nil then
 			self.Blur = Util.Create("Frame", {
 				Name = "LocalBackdropSoftening",
 				BackgroundColor3 = Theme.Palette.Window,
 				BackgroundTransparency = 1,
 				BorderSizePixel = 0,
 				Size = UDim2.fromScale(1, 1),
 				ZIndex = 0,
 				Parent = self.Frame,
 			})
 			Util.Corner(self.Blur, Config.Radius.Window)
 			Theme.Bind(self.Blur, "BackgroundColor3", "Window")
 			Util.Create("UIGradient", {
 				Rotation = 90,
 				Transparency = NumberSequence.new({
 					NumberSequenceKeypoint.new(0, 0.16),
 					NumberSequenceKeypoint.new(1, 0.58),
 				}),
 				Parent = self.Blur,
 			})
 		end

 		if animate == false then
 			self.Blur.BackgroundTransparency = transparency
 		else
 			Motion.Curve(self.Blur, "BackgroundTransparency", transparency, {
 				Curve = "Swift",
 				Duration = 0.24,
 			})
 		end

 		return
 	end

 	if self.Blur == nil then
 		return
 	end

 	local blur = self.Blur
 	Motion.Curve(blur, "BackgroundTransparency", 1, {
 		Curve = "Glide",
 		Duration = 0.2,
 		OnComplete = function()
 			blur:Destroy()
 			if self.Blur == blur then
 				self.Blur = nil
 			end
 		end,
 	})
 end

 function Window:IsBlurred()
 	return self.Blur ~= nil
 end

 --- Resizes the sidebar and reflows the content area around it.
 function Window:SetSidebarWidth(width, animate)
 	width = math.clamp(width, 120, 320)

 	local previous = self.SidebarWidth
 	self.SidebarWidth = width

 	local function apply(value)
 		if self:GetEffectiveSidebarWidth() ~= value then
 			self:RefreshSidebarLayout()
 			return
 		end

 		self.Sidebar.Size = UDim2.new(0, value, 1, -Config.Window.TopbarHeight)
 		self.Content.Position = UDim2.new(0, value, 0, Config.Window.TopbarHeight)
 		self.Content.Size = UDim2.new(1, -value, 1, -Config.Window.TopbarHeight)

 		if self.ActiveTab then
 			self.ActiveTab.Scroll:Refresh()
 		end
 		self:ReflowPopups()
 	end

 	if animate == false or previous == width then
 		apply(width)
 		return
 	end

 	local proxy = { Width = previous }
 	if self.SidebarWidthProxy then
 		Motion.CancelAll(self.SidebarWidthProxy)
 	end
 	self.SidebarWidthProxy = proxy

 	Motion.Spring(proxy, "Width", width, {
 		Stiffness = Config.Motion.Menu.Stiffness,
 		Damping = Config.Motion.Menu.Damping,
 		OnUpdate = apply,
 		OnComplete = function()
 			if self.SidebarWidthProxy == proxy then
 				self.SidebarWidthProxy = nil
 			end
 		end,
 	})
 end

 --- Recenters the window in the viewport.
 function Window:Center(animate)
 	local camera = workspace.CurrentCamera
 	local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
 	local size = self.Frame.AbsoluteSize

 	local target = UDim2.fromOffset(
 		math.floor(math.max(0, (viewport.X - size.X) / 2)),
 		math.floor(math.max(0, (viewport.Y - size.Y) / 2))
 	)

 	if animate == false then
 		self.Frame.Position = target
 		return
 	end

 	Motion.Spring(self.Frame, "Position", target, { Curve = "Glide", Duration = 0.4 })
 end

 --- Replaces the topbar brand glyph.
 function Window:SetMark(glyph)
 	if self.Mark then
 		self.Mark:SetGlyph(glyph)
 	end
 end

 ---------------------------------------------------------------------------
 -- Notifications
 ---------------------------------------------------------------------------

 function Window:Notify(options)
 	return self.Notifications:Push(options)
 end

 ---------------------------------------------------------------------------
 -- Teardown
 ---------------------------------------------------------------------------

 function Window:Close()
 	if self.Closed then
 		return
 	end
 	self.Closed = true

 	local duration = 0.28

 	Motion.Curve(self.Root, "GroupTransparency", 1, { Curve = "Exit", Duration = duration })
 	Motion.Curve(self.Frame, "Position", self.Frame.Position + UDim2.fromOffset(0, 14), {
 		Curve = "Exit",
 		Duration = duration,
 	})

 	task.delay(duration, function()
 		self:Destroy()
 	end)
 end

 function Window:Destroy()
 	if self.Destroyed then
 		return
 	end
 	self.Destroyed = true
 	self.Closed = true
 	self:ClosePopup(self.ActivePopup)

 	Motion.CancelAll(self)
 	if self.SidebarWidthProxy then
 		Motion.CancelAll(self.SidebarWidthProxy)
 		self.SidebarWidthProxy = nil
 	end
 	for _, instance in ipairs({ self.Root, self.Backdrop }) do
 		if instance then
 			Motion.CancelTree(instance)
 		end
 	end

 	-- Tab:Destroy removes itself from self.Tabs, so a forward ipairs would skip
 	-- every second tab. Always destroy from the tail.
 	for index = #self.Tabs, 1, -1 do
 		local tab = self.Tabs[index]
 		if tab then
 			tab:Destroy()
 		end
 	end
 	table.clear(self.Tabs)

 	self.DestroyedSignal:Fire()

 	self.Tooltip:Destroy()
 	self.Notifications:Destroy()
 	self.Maid:Destroy()
 	Motion.CancelTree(self.Root)
 	Motion.CancelTree(self.Backdrop)

 	if self.Blur then
 		self.Blur:Destroy()
 		self.Blur = nil
 	end

 	if self.OwnsScreenGui then
 		self.ScreenGui:Destroy()
 	else
 		if self.Backdrop then
 			self.Backdrop:Destroy()
 		end

 		if self.Root then
 			self.Root:Destroy()
 		end
 	end
 end

 return Window
end

__modules["Core/Config"] = function(script, require)
 --[[
 	Config
 	Shared constants for layout, typography and animation timing. Nothing in here
 	is required to be touched by consumers, but every value is safe to override
 	before the first window is created.
 ]]

 local Config = {}

 Config.Version = "1.0.0"

 Config.DefaultTheme = "Dark"
 Config.DefaultAccent = Color3.fromHex("4C8DFF")

 -- Layout metrics (in pixels).
 Config.Metrics = {
 	RowHeight = 36,
 	RowHeightDescription = 46,
 	TitleHeight = 18,
 	DescriptionHeight = 16,
 	ControlHeight = 26,
 	ControlGap = 12,
 	CardPaddingY = 10,
 	CardPaddingX = 12,
 	SectionHeaderHeight = 24,
 	SectionSpacing = 12,
 	ScrollSpacing = 8,
 	ScrollbarWidth = 3,
 	PopupMargin = 8,
 	PopupGap = 6,
 	ViewportMargin = 12,
 }

 -- Corner radii (in pixels).
 Config.Radius = {
 	Window = 12,
 	Card = 8,
 	Control = 6,
 	Small = 4,
 	Pill = 1000,
 }

 Config.Window = {
 	Width = 640,
 	Height = 440,
 	MinWidth = 520,
 	MinHeight = 340,
 	MaxWidth = 1440,
 	MaxHeight = 960,
 	SidebarWidth = 176,
 	TopbarHeight = 46,
 	TabHeight = 32,
 	TabSpacing = 2,
 	SidebarPadding = 8,
 	BlurSize = 22,
 	MinimumVisibleTitlebar = 96,
 }

 Config.Font = {
 	Regular = Enum.Font.Gotham,
 	Medium = Enum.Font.GothamMedium,
 	Bold = Enum.Font.GothamBold,
 	Mono = Enum.Font.Code,
 }

 Config.TextSize = {
 	Title = 16,
 	Subtitle = 13,
 	Tab = 14,
 	Section = 12,
 	Element = 14,
 	Description = 13,
 	Control = 13,
 	Body = 13,
 	Badge = 12,
 }

 Config.Animation = {
 	Window = TweenInfo.new(0.32, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
 	Tab = TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
 	Fast = TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
 	Default = TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
 	Slow = TweenInfo.new(0.36, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
 	Snappy = TweenInfo.new(0.26, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
 }

 -- Physics presets for the Motion module. Overshoot is intentional on controls
 -- that latch (switches, rails) and absent on surfaces that should feel stable.
 Config.Motion = {
 	Toggle = { Stiffness = 480, Damping = 26 },
 	Knob = { Stiffness = 560, Damping = 30 },
 	Hover = { Stiffness = 700, Damping = 36 },
 	Menu = { Stiffness = 400, Damping = 30 },
 	Indicator = { Stiffness = 460, Damping = 33 },
 	Collapse = { Stiffness = 360, Damping = 30 },
 	Slider = { Stiffness = 520, Damping = 34 },
 	Reveal = { Curve = "Swift", Duration = 0.42 },
 	RevealStep = 0.05,
 	Entrance = { Curve = "Swift", Duration = 0.5 },
 }

 Config.Icons = {
 	TabSize = 17,
 	TopbarSize = 16,
 	ChevronSize = 15,
 	NoticeSize = 17,
 	KeybindSize = 15,
 	SliderSize = 13,
 	BrandSize = 14,
 	FooterSize = 13,
 	SearchSize = 13,
 }

 return Config
end

__modules["Core/Effects"] = function(script, require)
 --[[
 	Effects
 	Small reusable motion details: click ripples, hover sheens and pulse rings.
 	They are the difference between "a tween happened" and a control that feels
 	like it has surface tension.

 		Effects.AttachRipple(button, self.Maid)
 		Effects.AttachSheen(button, self.Maid)
 ]]

 local Motion = require(script.Parent.Motion)
 local Theme = require(script.Parent.Theme)
 local Util = require(script.Parent.Util)

 local Effects = {}

 local RIPPLE_CORNERS = 1000

 --- Expanding, fading circle anchored at the click point. The host must clip
 --- descendants, otherwise it escapes the control.
 function Effects.Ripple(host, options)
 	options = options or {}

 	local x = options.X or host.AbsoluteSize.X / 2
 	local y = options.Y or host.AbsoluteSize.Y / 2

 	local spread = math.max(host.AbsoluteSize.X, host.AbsoluteSize.Y) * 1.4
 	local size = math.max(24, spread * 2)

 	local ripple = Util.Create("Frame", {
 		Name = "Ripple",
 		AnchorPoint = Vector2.new(0.5, 0.5),
 		BackgroundColor3 = options.Color or Theme.Palette.AccentText,
 		BackgroundTransparency = options.Transparency or 0.72,
 		BorderSizePixel = 0,
 		Position = UDim2.fromOffset(x, y),
 		Size = UDim2.fromOffset(0, 0),
 		ZIndex = options.ZIndex or 3,
 		Parent = host,
 	})
 	Util.Corner(ripple, RIPPLE_CORNERS)

 	Motion.Curve(ripple, "Size", UDim2.fromOffset(size, size), {
 		Curve = "Glide",
 		Duration = 0.5,
 	})

 	Motion.Curve(ripple, "BackgroundTransparency", 1, {
 		Curve = "Exit",
 		Duration = 0.62,
 		OnComplete = function()
 			ripple:Destroy()
 		end,
 	})

 	return ripple
 end

 --- Sweeps a soft highlight across the control once per hover. Uses a gradient
 --- offset so it costs a single instance.
 function Effects.Sheen(host, options)
 	options = options or {}

 	local sweep = Util.Create("Frame", {
 		Name = "Sheen",
 		BackgroundColor3 = options.Color or Color3.new(1, 1, 1),
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		ZIndex = options.ZIndex or 4,
 		Parent = host,
 	})

 	local gradient = Util.Create("UIGradient", {
 		Rotation = options.Rotation or 22,
 		Transparency = NumberSequence.new({
 			NumberSequenceKeypoint.new(0, 1),
 			NumberSequenceKeypoint.new(0.42, 0.86),
 			NumberSequenceKeypoint.new(0.5, 0.8),
 			NumberSequenceKeypoint.new(0.58, 0.86),
 			NumberSequenceKeypoint.new(1, 1),
 		}),
 		Parent = sweep,
 	})

 	local playing = false

 	local function play()
 		if playing then
 			return
 		end

 		playing = true
 		gradient.Offset = Vector2.new(-1.4, 0)

 		Motion.Curve(gradient, "Offset", Vector2.new(1.4, 0), {
 			Curve = "Glide",
 			Duration = options.Duration or 0.66,
 			OnComplete = function()
 				playing = false
 			end,
 		})
 	end

 	return { Instance = sweep, Play = play }
 end

 --- Slow breathing highlight, used while a control waits for input.
 function Effects.PulseRing(host, options)
 	options = options or {}

 	local color = options.Color or Theme.Palette.Accent

 	local ring = Util.Create("Frame", {
 		Name = "PulseRing",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		ZIndex = options.ZIndex or 2,
 		Parent = host,
 	})
 	Util.Corner(ring, options.Radius or 1000)

 	local stroke = Util.Create("UIStroke", {
 		Color = color,
 		Thickness = options.Thickness or 1,
 		Transparency = 1,
 		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
 		Parent = ring,
 	})

 	if options.Active then
 		options.Active(ring, stroke)
 	end

 	return { Instance = ring, Stroke = stroke }
 end

 --- Fades and slides a surface in. `direction` is in pixels on the Y axis.
 function Effects.Reveal(instance, direction, options)
 	options = options or {}

 	local delay = options.Delay or 0
 	local property = options.Property or "Position"
 	local target = options.Target or instance[property]

 	Motion.Curve(instance, property, target, {
 		From = target + UDim2.fromOffset(0, direction or 10),
 		Curve = options.Curve or "Swift",
 		Duration = options.Duration or 0.42,
 		Delay = delay,
 	})

 	if options.Fade ~= false then
 		Motion.Curve(instance, "GroupTransparency", 0, {
 			From = 1,
 			Curve = "Glide",
 			Duration = options.Duration or 0.42,
 			Delay = delay,
 		})
 	end
 end

 return Effects
end

__modules["Core/Element"] = function(script, require)
 --[[
 	Element
 	Base class for every control. It owns the row layout — title, description,
 	optional body area and the right aligned control slot — plus the shared
 	visibility, enabled and destroy behaviour.

 	Row heights are computed arithmetically so sections can size their cards
 	without waiting for a layout pass.
 ]]

 local Config = require(script.Parent.Config)
 local Maid = require(script.Parent.Maid)
 local Motion = require(script.Parent.Motion)
 local Signal = require(script.Parent.Signal)
 local Theme = require(script.Parent.Theme)
 local Util = require(script.Parent.Util)

 local Element = {}
 Element.__index = Element

 --- @param class table Component table the instance belongs to.
 --- @param section table Section that owns the row.
 --- @param options table Component options (Name, Description, Callback, ...).
 --- @param layout table Height, TitleHeight, BodyHeight, BodyGap, PaddingTop,
 --- PaddingBottom, ControlWidth, ControlHeight.
 function Element.new(class, section, options, layout)
 	options = options or {}
 	layout = layout or {}

 	local self = setmetatable({}, class)
 	self.Class = class
 	self.Section = section
 	self.Window = section.Window
 	self.Options = options
 	self.Maid = Maid.new()
 	self.Changed = Signal.new()
 	self.Visible = options.Visible ~= false
 	self.Enabled = options.Enabled ~= false
 	self.Destroyed = false

 	local metrics = Config.Metrics
 	local hasDescription = options.Description ~= nil
 	local titleHeight = layout.TitleHeight or metrics.TitleHeight
 	local lineHeight = titleHeight + (hasDescription and metrics.DescriptionHeight or 0)
 	local controlWidth = layout.ControlWidth
 	local controlHeight = layout.ControlHeight or metrics.ControlHeight
 	local bodyHeight = layout.BodyHeight
 	local paddingTop = layout.PaddingTop or (bodyHeight and 6 or (hasDescription and 8 or 10))
 	local paddingBottom = layout.PaddingBottom or (bodyHeight and 4 or (hasDescription and 8 or 10))

 	local height = layout.Height
 	if height == nil then
 		height = paddingTop + lineHeight + (bodyHeight and ((layout.BodyGap or 6) + bodyHeight) or 0) + paddingBottom
 	end

 	self.RowHeight = height

 	local row = Util.Create("Frame", {
 		Name = "Row",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.new(1, 0, 0, height),
 		Parent = section.Container,
 	})

 	self.Row = row
 	self.HasDescription = hasDescription
 	self.Layout = layout
 	self.TitleHeight = titleHeight
 	self.ControlWidth = controlWidth
 	self.ControlHeight = controlHeight
 	self.BodyHeight = bodyHeight

 	-- Hover wash: inset from the card edges so the row reads as a target. It is
 	-- drawn behind the row content and only animates for interactive rows.
 	local highlight = Util.Create("Frame", {
 		Name = "Highlight",
 		BackgroundColor3 = Theme.Palette.SurfaceHover,
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, -6, 0, -2),
 		Size = UDim2.new(1, 12, 1, 4),
 		ZIndex = 0,
 		Parent = row,
 	})
 	Util.Corner(highlight, Config.Radius.Control)
 	Theme.Bind(highlight, "BackgroundColor3", "SurfaceHover")

 	self.Highlight = highlight
 	self.Hovered = false

 	if options.Name ~= nil then
 		local titleWidth = controlWidth and -(controlWidth + metrics.ControlGap) or 0

 		local title = Util.Create("TextLabel", {
 			Name = "Title",
 			BackgroundTransparency = 1,
 			BorderSizePixel = 0,
 			Font = Config.Font.Medium,
 			Text = tostring(options.Name),
 			TextSize = Config.TextSize.Element,
 			TextXAlignment = Enum.TextXAlignment.Left,
 			TextYAlignment = Enum.TextYAlignment.Top,
 			TextTruncate = Enum.TextTruncate.AtEnd,
 			Size = UDim2.new(1, titleWidth, 0, titleHeight),
 			Position = UDim2.new(0, 0, 0, paddingTop),
 			Parent = row,
 		})
 		Theme.Bind(title, "TextColor3", "Text")
 		self.Title = title
 	end

 	if hasDescription then
 		local descriptionWidth = controlWidth and -(controlWidth + metrics.ControlGap) or 0

 		local description = Util.Create("TextLabel", {
 			Name = "Description",
 			BackgroundTransparency = 1,
 			BorderSizePixel = 0,
 			Font = Config.Font.Regular,
 			Text = tostring(options.Description),
 			TextSize = Config.TextSize.Description,
 			TextXAlignment = Enum.TextXAlignment.Left,
 			TextYAlignment = Enum.TextYAlignment.Top,
 			TextTruncate = Enum.TextTruncate.AtEnd,
 			Size = UDim2.new(1, descriptionWidth, 0, metrics.DescriptionHeight),
 			Position = UDim2.new(0, 0, 0, paddingTop + titleHeight),
 			Parent = row,
 		})
 		Theme.Bind(description, "TextColor3", "TextMuted")
 		self.Description = description
 	end

 	if controlWidth then
 		local controlCenter = (bodyHeight or hasDescription) and (paddingTop + titleHeight / 2) or height / 2

 		self.Control = Util.Create("Frame", {
 			Name = "Control",
 			BackgroundTransparency = 1,
 			BorderSizePixel = 0,
 			AnchorPoint = Vector2.new(1, 0.5),
 			Position = UDim2.new(1, 0, 0, controlCenter),
 			Size = UDim2.new(0, controlWidth, 0, controlHeight),
 			Parent = row,
 		})
 	end

 	if bodyHeight then
 		self.Body = Util.Create("Frame", {
 			Name = "Body",
 			BackgroundTransparency = 1,
 			BorderSizePixel = 0,
 			Size = UDim2.new(1, 0, 0, bodyHeight),
 			Position = UDim2.new(0, 0, 0, height - paddingBottom - bodyHeight),
 			Parent = row,
 		})
 	end

 	self.PaddingTop = paddingTop
 	self.PaddingBottom = paddingBottom

 	self.Separator = Util.Create("Frame", {
 		Name = "Separator",
 		BackgroundTransparency = options.Separator == false and 1 or 0.35,
 		BackgroundColor3 = Theme.Palette.Divider,
 		BorderSizePixel = 0,
 		Size = UDim2.new(1, 0, 0, 1),
 		Parent = section.Container,
 	})
 	Theme.Bind(self.Separator, "BackgroundColor3", "Divider")

 	if not self.Visible then
 		row.Visible = false
 		self.Separator.Visible = false
 	end

 	section:Insert(self)

 	if options.Tooltip then
 		self:AttachTooltip(options.Tooltip)
 	end

 	if not self.Enabled then
 		-- Deferred: components finish building their own controls first.
 		task.defer(function()
 			if not self.Destroyed then
 				self:SetEnabled(false)
 			end
 		end)
 	end

 	return self
 end

 --- Runs the component callback and notifies listeners.
 function Element:Fire(value)
 	Util.SafeCall(self.Options.Callback, value)
 	self.Changed:Fire(value)
 end

 --- Enables the hover wash. Called by interactive components once their control
 --- exists, so the highlight can follow the pointer over the control too.
 function Element:SetHoverable(hoverable)
 	if self.Hoverable == hoverable then
 		return
 	end

 	self.Hoverable = hoverable

 	if not hoverable then
 		return
 	end

 	local function setHovered(state)
 		self.Hovered = state

 		Motion.Spring(self.Highlight, "BackgroundTransparency", state and 0.55 or 1, {
 			Stiffness = Config.Motion.Hover.Stiffness,
 			Damping = Config.Motion.Hover.Damping,
 		})

 		if self.OnHoverChanged then
 			self:OnHoverChanged(state)
 		end
 	end

 	self.Maid:Add(self.Row.MouseEnter:Connect(function()
 		setHovered(true)
 	end))

 	self.Maid:Add(self.Row.MouseLeave:Connect(function()
 		setHovered(false)
 	end))

 	if self.Control then
 		self.Maid:Add(self.Control.MouseEnter:Connect(function()
 			setHovered(true)
 		end))

 		self.Maid:Add(self.Control.MouseLeave:Connect(function()
 			setHovered(false)
 		end))
 	end
 end

 function Element:OnChanged(handler)
 	return self.Changed:Connect(handler)
 end

 --- Resizes the row and asks the owning section to re-flow.
 function Element:SetRowHeight(height)
 	if self.RowHeight == height then
 		return
 	end

 	self.RowHeight = height

 	if self.Row then
 		self.Row.Size = UDim2.new(1, 0, 0, height)
 	end

 	self.Section:RefreshLayout()
 end

 function Element:SetTitle(text)
 	if self.Title then
 		self.Title.Text = text == nil and "" or tostring(text)
 	end
 end

 function Element:SetDescription(text)
 	local hasDescription = text ~= nil
 	if hasDescription and not self.Description then
 		local description = Util.Create("TextLabel", {
 			Name = "Description",
 			BackgroundTransparency = 1,
 			BorderSizePixel = 0,
 			Font = Config.Font.Regular,
 			Text = tostring(text),
 			TextSize = Config.TextSize.Description,
 			TextTruncate = Enum.TextTruncate.AtEnd,
 			TextXAlignment = Enum.TextXAlignment.Left,
 			TextYAlignment = Enum.TextYAlignment.Top,
 			Parent = self.Row,
 		})
 		Theme.Bind(description, "TextColor3", self.Enabled and "TextMuted" or "TextDim")
 		self.Description = description
 	elseif self.Description then
 		self.Description.Text = hasDescription and tostring(text) or ""
 		self.Description.Visible = hasDescription
 	end

 	if self.HasDescription == hasDescription then
 		return
 	end

 	self.HasDescription = hasDescription
 	local layout = self.Layout
 	local bodyHeight = self.BodyHeight
 	local paddingTop = layout.PaddingTop or (bodyHeight and 6 or (hasDescription and 8 or 10))
 	local paddingBottom = layout.PaddingBottom or (bodyHeight and 4 or (hasDescription and 8 or 10))
 	local height = layout.Height
 	if height == nil then
 		height = paddingTop
 			+ self.TitleHeight
 			+ (hasDescription and Config.Metrics.DescriptionHeight or 0)
 			+ (bodyHeight and ((layout.BodyGap or 6) + bodyHeight) or 0)
 			+ paddingBottom
 	end

 	if self.Title then
 		self.Title.Position = UDim2.new(0, 0, 0, paddingTop)
 	end
 	if self.Description then
 		self.Description.Position = UDim2.new(0, 0, 0, paddingTop + self.TitleHeight)
 		self.Description.Size = UDim2.new(
 			1,
 			self.ControlWidth and -(self.ControlWidth + Config.Metrics.ControlGap) or 0,
 			0,
 			Config.Metrics.DescriptionHeight
 		)
 	end
 	if self.Control then
 		local center = (bodyHeight or hasDescription) and (paddingTop + self.TitleHeight / 2) or height / 2
 		self.Control.Position = UDim2.new(1, 0, 0, center)
 	end
 	if self.Body then
 		self.Body.Position = UDim2.new(0, 0, 0, height - paddingBottom - bodyHeight)
 	end

 	self.PaddingTop = paddingTop
 	self.PaddingBottom = paddingBottom
 	self:SetRowHeight(height)
 end

 function Element:SetVisible(visible)
 	self.Visible = visible and true or false

 	if self.Row then
 		self.Row.Visible = self.Visible
 	end

 	if self.Separator then
 		self.Separator.Visible = self.Visible
 	end

 	self.Section:RefreshLayout()
 end

 function Element:IsVisible()
 	return self.Visible
 end

 function Element:SetEnabled(enabled)
 	self.Enabled = enabled and true or false

 	if self.Title then
 		Theme.Bind(self.Title, "TextColor3", self.Enabled and "Text" or "TextDim")
 	end

 	if self.Description then
 		Theme.Bind(self.Description, "TextColor3", self.Enabled and "TextMuted" or "TextDim")
 	end

 	if self.SetControlEnabled then
 		self:SetControlEnabled(self.Enabled)
 	end
 end

 function Element:IsEnabled()
 	return self.Enabled
 end

 --- Shows a hint bubble anchored to the row while the pointer is over it.
 function Element:AttachTooltip(text)
 	if self.Window.Tooltip then
 		self.Window.Tooltip:Bind(self, text)
 	end
 end

 function Element:Destroy()
 	if self.Destroyed then
 		return
 	end
 	self.Destroyed = true

 	Motion.CancelAll(self)
 	Motion.CancelTree(self.Row)
 	Motion.CancelTree(self.Separator)
 	self.Maid:Destroy()
 	self.Changed:Destroy()

 	if self.Separator then
 		self.Separator:Destroy()
 		self.Separator = nil
 	end

 	if self.Row then
 		self.Row:Destroy()
 		self.Row = nil
 	end

 	self.Section:Forget(self)
 end

 return Element
end

