__modules["Core/Maid"] = function(script, require)
 --[[
 	Maid
 	Deterministic cleanup container. Accepts Instances, RBXScriptConnections,
 	functions, threads and tables exposing a Destroy method.
 ]]

 local Maid = {}
 Maid.__index = Maid

 local function destroyTask(task)
 	local kind = typeof(task)

 	if kind == "function" then
 		task()
 	elseif kind == "thread" then
 		task:cancel()
 	elseif kind == "RBXScriptConnection" then
 		task:Disconnect()
 	elseif kind == "Instance" then
 		task:Destroy()
 	elseif kind == "table" and type(task.Destroy) == "function" then
 		task:Destroy()
 	end
 end

 function Maid.new()
 	return setmetatable({ _tasks = {}, _destroyed = false }, Maid)
 end

 function Maid:Add(task)
 	if task == nil then
 		return task
 	end

 	if self._destroyed then
 		destroyTask(task)
 		return task
 	end

 	table.insert(self._tasks, task)
 	return task
 end

 function Maid:Clean()
 	for index = #self._tasks, 1, -1 do
 		local task = self._tasks[index]
 		self._tasks[index] = nil
 		destroyTask(task)
 	end
 end

 function Maid:Destroy()
 	if self._destroyed then
 		return
 	end

 	self._destroyed = true
 	self:Clean()
 end

 return Maid
end

__modules["Core/Motion"] = function(script, require)
 --[[
 	Motion
 	Spring and curve driven property animation.

 	Roblox's tween presets are deliberately not used: springs give controls weight
 	and overshoot, and the bezier presets below are hand picked so motion reads as
 	designed rather than default. A single Heartbeat connection drives every
 	active animation, and starting a new animation on a property cancels the old
 	one for that property.

 		Motion.Spring(instance, "Position", UDim2.fromOffset(0, 0), { Stiffness = 320, Damping = 30 })
 		Motion.Curve(instance, "GroupTransparency", 0, { Curve = "Swift", Duration = 0.4 })
 		Motion.Pulse(instance, "BackgroundTransparency", 0.9, { Stopped = function() return not listening end })
 ]]

 local RunService = game:GetService("RunService")

 local Motion = {}

 -- When true, every animation resolves instantly. Exposed through
 -- Lumen:SetAnimations(false) for players who prefer reduced motion.
 Motion.Reduced = false

 Motion.Curves = {
 	-- Fast start, long settle. Reads as important.
 	Swift = { 0.16, 1, 0.3, 1 },
 	-- Balanced interface motion.
 	Glide = { 0.22, 1, 0.36, 1 },
 	-- Press and release feedback.
 	Press = { 0.34, 1.4, 0.64, 1 },
 	-- Playful overshoot, used sparingly.
 	Pop = { 0.34, 1.56, 0.64, 1 },
 	-- Soft ease for large surfaces.
 	Soft = { 0.25, 0.46, 0.45, 0.94 },
 	-- Symmetrical in and out.
 	Even = { 0.4, 0, 0.2, 1 },
 	-- Decelerating exit.
 	Exit = { 0.4, 0, 1, 1 },
 }

 local DEFAULT_SPRING = { Stiffness = 320, Damping = 30, Mass = 1 }

 local adapters = {
 	number = function(from, to, alpha)
 		return from + (to - from) * alpha
 	end,

 	UDim2 = function(from, to, alpha)
 		return UDim2.new(
 			from.X.Scale + (to.X.Scale - from.X.Scale) * alpha,
 			from.X.Offset + (to.X.Offset - from.X.Offset) * alpha,
 			from.Y.Scale + (to.Y.Scale - from.Y.Scale) * alpha,
 			from.Y.Offset + (to.Y.Offset - from.Y.Offset) * alpha
 		)
 	end,

 	UDim = function(from, to, alpha)
 		return UDim.new(from.Scale + (to.Scale - from.Scale) * alpha, from.Offset + (to.Offset - from.Offset) * alpha)
 	end,

 	Vector2 = function(from, to, alpha)
 		return Vector2.new(from.X + (to.X - from.X) * alpha, from.Y + (to.Y - from.Y) * alpha)
 	end,

 	Color3 = function(from, to, alpha)
 		return Color3.new(
 			from.R + (to.R - from.R) * alpha,
 			from.G + (to.G - from.G) * alpha,
 			from.B + (to.B - from.B) * alpha
 		)
 	end,
 }

 local function lerpValue(from, to, alpha)
 	local adapter = adapters[typeof(from)]
 	if adapter == nil then
 		return to
 	end

 	return adapter(from, to, alpha)
 end

 local registry = setmetatable({}, { __mode = "k" })
 local active = {}
 local running = false
 local connection = nil

 local function isAlive(instance)
 	-- Tables are valid animation proxies; only Roblox instances have a lifetime.
 	return typeof(instance) ~= "Instance" or instance.Parent ~= nil
 end

 local function clearRegistry(instance, property, animation)
 	local perInstance = registry[instance]
 	if perInstance and perInstance[property] == animation then
 		perInstance[property] = nil

 		-- Drop the per-instance table once its last animation is gone.
 		if next(perInstance) == nil then
 			registry[instance] = nil
 		end
 	end
 end

 local function ensureRunning()
 	if running then
 		return
 	end

 	running = true

 	connection = RunService.Heartbeat:Connect(function(delta)
 		for index = #active, 1, -1 do
 			local animation = active[index]
 			if not isAlive(animation.Instance) then
 				animation:Cancel()
 			else
 				animation:Step(delta)
 			end

 			if animation.Finished then
 				clearRegistry(animation.Instance, animation.Property, animation)
 				table.remove(active, index)
 			end
 		end

 		if #active == 0 and connection then
 			connection:Disconnect()
 			connection = nil
 			running = false
 		end
 	end)
 end

 ---------------------------------------------------------------------------
 -- Cubic bezier solver (CSS style curves)
 ---------------------------------------------------------------------------

 local function bezierCoordinate(t, first, second)
 	local inverse = 1 - t
 	return 3 * inverse * inverse * t * first + 3 * inverse * t * t * second + t * t * t
 end

 local function bezierProgress(alpha, first, second)
 	local low = 0
 	local high = 1

 	for _ = 1, 20 do
 		local middle = (low + high) / 2
 		if bezierCoordinate(middle, first, second) < alpha then
 			low = middle
 		else
 			high = middle
 		end
 	end

 	return bezierCoordinate((low + high) / 2, first, second)
 end

 ---------------------------------------------------------------------------
 -- Animation objects
 ---------------------------------------------------------------------------

 local Spring = {}
 Spring.__index = Spring

 local function newSpring(instance, property, target, options)
 	local from = options.From or instance[property]

 	local self = setmetatable({
 		Instance = instance,
 		Property = property,
 		From = from,
 		Target = target,
 		Value = from,
 		Velocity = options.Velocity or 0,
 		Stiffness = options.Stiffness or DEFAULT_SPRING.Stiffness,
 		Damping = options.Damping or DEFAULT_SPRING.Damping,
 		Mass = options.Mass or DEFAULT_SPRING.Mass,
 		Epsilon = options.Epsilon or 0.0006,
 		OnUpdate = options.OnUpdate,
 		OnComplete = options.OnComplete,
 		Finished = false,
 	}, Spring)

 	instance[property] = from

 	return self
 end

 function Spring:Step(delta)
 	-- Sub stepping keeps the integrator stable when a frame is long.
 	local steps = math.clamp(math.ceil(delta / (1 / 120)), 1, 8)
 	local step = delta / steps

 	for _ = 1, steps do
 		local acceleration = (-self.Stiffness * (self.Value - self.Target) - self.Damping * self.Velocity) / self.Mass
 		self.Velocity += acceleration * step
 		self.Value += self.Velocity * step
 	end

 	if math.abs(self.Value - self.Target) < self.Epsilon and math.abs(self.Velocity) < self.Epsilon * 12 then
 		self.Finished = true
 		self.Value = self.Target
 	end

 	self.Instance[self.Property] = self.Value

 	if self.OnUpdate then
 		self.OnUpdate(self.Value)
 	end

 	if self.Finished and self.OnComplete then
 		self.OnComplete()
 	end
 end

 function Spring:Cancel()
 	self.Finished = true
 end

 local Curve = {}
 Curve.__index = Curve

 local function newCurve(instance, property, target, options)
 	local from = options.From or instance[property]

 	return setmetatable({
 		Instance = instance,
 		Property = property,
 		From = from,
 		Target = target,
 		Duration = math.max(options.Duration or 0.3, 0.001),
 		Bezier = Motion.Curves[options.Curve] or Motion.Curves.Glide,
 		Elapsed = -(options.Delay or 0),
 		OnUpdate = options.OnUpdate,
 		OnComplete = options.OnComplete,
 		Finished = false,
 	}, Curve)
 end

 function Curve:Step(delta)
 	self.Elapsed += delta

 	if self.Elapsed < 0 then
 		return
 	end

 	local alpha = math.clamp(self.Elapsed / self.Duration, 0, 1)
 	local value = lerpValue(self.From, self.Target, bezierProgress(alpha, self.Bezier[1], self.Bezier[2]))

 	self.Instance[self.Property] = value

 	if self.OnUpdate then
 		self.OnUpdate(value)
 	end

 	if alpha >= 1 then
 		self.Instance[self.Property] = self.Target
 		self.Finished = true

 		if self.OnComplete then
 			self.OnComplete()
 		end
 	end
 end

 function Curve:Cancel()
 	self.Finished = true
 end

 ---------------------------------------------------------------------------
 -- Public API
 ---------------------------------------------------------------------------

 local function cancelExisting(instance, property)
 	local perInstance = registry[instance]
 	if perInstance == nil then
 		return
 	end

 	local existing = perInstance[property]
 	if existing then
 		existing:Cancel()
 		perInstance[property] = nil

 		if next(perInstance) == nil then
 			registry[instance] = nil
 		end
 	end
 end

 local function track(instance, property, animation)
 	local perInstance = registry[instance]
 	if perInstance == nil then
 		perInstance = {}
 		registry[instance] = perInstance
 	end

 	perInstance[property] = animation
 	table.insert(active, animation)
 	ensureRunning()

 	return animation
 end

 --- Applies a value immediately. Used when motion is switched off, so callers
 --- keep their callbacks without any animation cost.
 local function applyImmediately(instance, property, target, options)
 	instance[property] = target

 	if options.OnUpdate then
 		options.OnUpdate(target)
 	end

 	if options.OnComplete then
 		options.OnComplete()
 	end
 end

 --- Animates a property with spring physics. Only numbers get real springs;
 --- richer values fall back to a short bezier so layout properties still move
 --- with the same character.
 function Motion.Spring(instance, property, target, options)
 	options = options or {}
 	cancelExisting(instance, property)

 	if Motion.Reduced then
 		applyImmediately(instance, property, target, options)
 		return nil
 	end

 	if typeof(target) == "number" and typeof(instance[property]) == "number" then
 		return track(instance, property, newSpring(instance, property, target, options))
 	end

 	return track(
 		instance,
 		property,
 		newCurve(instance, property, target, {
 			From = options.From,
 			Duration = options.Duration or 0.3,
 			Curve = options.Curve or "Glide",
 			Delay = options.Delay,
 			OnUpdate = options.OnUpdate,
 			OnComplete = options.OnComplete,
 		})
 	)
 end

 --- Animates a property along a bezier curve.
 function Motion.Curve(instance, property, target, options)
 	options = options or {}
 	cancelExisting(instance, property)

 	if Motion.Reduced then
 		applyImmediately(instance, property, target, options)
 		return nil
 	end

 	return track(instance, property, newCurve(instance, property, target, options))
 end

 --- Kept for symmetry with Motion.Spring; both are the same entry point.
 function Motion.To(instance, property, target, options)
 	return Motion.Spring(instance, property, target, options)
 end

 --- Repeats a two phase animation until `options.Stopped` returns true.
 function Motion.Pulse(instance, property, peak, options)
 	options = options or {}

 	local base = options.From or instance[property]
 	local duration = (options.Duration or 0.9) / 2

 	local function stopped()
 		return options.Stopped ~= nil and options.Stopped()
 	end

 	local cycle

 	local function settle()
 		Motion.Curve(instance, property, base, { Curve = "Even", Duration = duration })
 	end

 	cycle = function()
 		if stopped() then
 			settle()
 			return
 		end

 		Motion.Curve(instance, property, peak, {
 			Curve = "Even",
 			Duration = duration,
 			OnComplete = function()
 				if stopped() then
 					settle()
 					return
 				end

 				Motion.Curve(instance, property, base, {
 					Curve = "Even",
 					Duration = duration,
 					OnComplete = cycle,
 				})
 			end,
 		})
 	end

 	cycle()
 end

 --- Runs `callback` over `instances` with a small delay between each one.
 function Motion.Stagger(instances, step, callback)
 	for index, instance in ipairs(instances) do
 		callback(instance, (index - 1) * (step or 0.03))
 	end
 end

 function Motion.Cancel(instance, property)
 	cancelExisting(instance, property)
 end

 --- Cancels every property animation owned by an instance or a proxy table.
 --- Destruction paths use this to prevent callbacks from running against stale
 --- component state before the next Heartbeat has a chance to prune it.
 function Motion.CancelAll(instance)
 	local perInstance = registry[instance]
 	if perInstance then
 		for property, animation in pairs(perInstance) do
 			animation:Cancel()
 			perInstance[property] = nil
 		end

 		registry[instance] = nil
 	end

 	for index = #active, 1, -1 do
 		if active[index].Instance == instance then
 			table.remove(active, index)
 		end
 	end
 end

 --- Cancels active properties on an instance and every descendant. This is used
 --- immediately before a GUI subtree is destroyed, rather than waiting for the
 --- next Heartbeat to discover that its instances lost their parent.
 function Motion.CancelTree(instance)
 	if instance == nil then
 		return
 	end

 	Motion.CancelAll(instance)
 	if typeof(instance) == "Instance" and instance.GetChildren then
 		for _, child in ipairs(instance:GetChildren()) do
 			Motion.CancelTree(child)
 		end
 	end
 end

 function Motion.IsActive(instance, property)
 	local perInstance = registry[instance]
 	if perInstance == nil then
 		return false
 	end

 	local animation = perInstance[property]
 	return animation ~= nil and not animation.Finished
 end

 --- Steps every animation manually. The live path is the Heartbeat loop; this
 --- exists for deterministic tests.
 function Motion.Step(delta)
 	for index = #active, 1, -1 do
 		local animation = active[index]
 		if not isAlive(animation.Instance) then
 			animation:Cancel()
 		else
 			animation:Step(delta)
 		end

 		if animation.Finished then
 			clearRegistry(animation.Instance, animation.Property, animation)
 			table.remove(active, index)
 		end
 	end
 end

 function Motion.ActiveCount()
 	return #active
 end

 return Motion
end

__modules["Core/Scroll"] = function(script, require)
 --[[
 	Scroll
 	ScrollingFrame wrapper with a custom auto hiding scrollbar and edge fades.

 	The canvas is sized explicitly from the content layout instead of relying on
 	AutomaticCanvasSize, so geometry stays predictable no matter how rows are
 	added, resized or hidden. Fades at the top and bottom hint that there is more
 	content without a visible scrollbar. Add content to `scroll.Content`.
 ]]

 local Config = require(script.Parent.Config)
 local Maid = require(script.Parent.Maid)
 local Motion = require(script.Parent.Motion)
 local Theme = require(script.Parent.Theme)
 local Util = require(script.Parent.Util)

 local Scroll = {}
 Scroll.__index = Scroll

 local BAR = Config.Metrics.ScrollbarWidth

 function Scroll.new(parent, options)
 	options = options or {}

 	local sides = options.Padding or { Top = 12, Right = 16, Bottom = 12, Left = 14 }
 	local padTop = sides.Top or 0
 	local padRight = sides.Right or 0
 	local padBottom = sides.Bottom or 0
 	local padLeft = sides.Left or 0

 	local self = setmetatable({}, Scroll)
 	self.Maid = Maid.new()
 	self.Padding = { Top = padTop, Right = padRight, Bottom = padBottom, Left = padLeft }

 	local container = Util.Create("Frame", {
 		Name = "ScrollContainer",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		Parent = parent,
 	})

 	local frame = Util.Create("ScrollingFrame", {
 		Name = "Scroll",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Size = UDim2.fromScale(1, 1),
 		CanvasSize = UDim2.new(),
 		AutomaticCanvasSize = Enum.AutomaticSize.None,
 		ScrollingDirection = Enum.ScrollingDirection.Y,
 		ScrollBarThickness = 0,
 		VerticalScrollBarInset = Enum.ScrollBarInset.None,
 		ElasticBehavior = Enum.ElasticBehavior.WhenScrollable,
 		Parent = container,
 	})

 	local content = Util.Create("Frame", {
 		Name = "Content",
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Position = UDim2.new(0, padLeft, 0, padTop),
 		Size = UDim2.new(1, -(padLeft + padRight), 0, 0),
 		Parent = frame,
 	})

 	local layout = Util.List(content, options.Spacing or Config.Metrics.ScrollSpacing)

 	-- Edge fades: opaque against the surface, fading into the content.
 	local fadeKey = options.FadeColor or "Window"
 	local fadeSize = options.FadeSize or 22

 	local function createFade(name, rotation)
 		local fade = Util.Create("Frame", {
 			Name = name,
 			BackgroundColor3 = Theme.Palette[fadeKey] or Theme.Palette.Window,
 			BackgroundTransparency = 1,
 			BorderSizePixel = 0,
 			Size = UDim2.new(1, 0, 0, fadeSize),
 			ZIndex = 6,
 			Parent = container,
 		})
 		Theme.Bind(fade, "BackgroundColor3", fadeKey)
 		Util.Create("UIGradient", {
 			Rotation = rotation,
 			Transparency = NumberSequence.new({
 				NumberSequenceKeypoint.new(0, 0),
 				NumberSequenceKeypoint.new(1, 1),
 			}),
 			Parent = fade,
 		})
 		return fade
 	end

 	local topFade = createFade("TopFade", 90)
 	topFade.Position = UDim2.fromOffset(0, 0)
 	local bottomFade = createFade("BottomFade", -90)
 	bottomFade.AnchorPoint = Vector2.new(0, 1)
 	bottomFade.Position = UDim2.new(0, 0, 1, 0)

 	local track = Util.Create("Frame", {
 		Name = "Scrollbar",
 		AnchorPoint = Vector2.new(1, 0.5),
 		Position = UDim2.new(1, -5, 0.5, 0),
 		Size = UDim2.new(0, 12, 1, -20),
 		BackgroundTransparency = 1,
 		BorderSizePixel = 0,
 		Active = true,
 		Visible = false,
 		Parent = container,
 	})

 	local thumb = Util.Create("Frame", {
 		Name = "Thumb",
 		AnchorPoint = Vector2.new(0.5, 0),
 		Position = UDim2.new(0.5, 0, 0, 0),
 		Size = UDim2.new(0, BAR, 0, 40),
 		BackgroundColor3 = Theme.Palette.TextMuted,
 		BackgroundTransparency = 0.45,
 		BorderSizePixel = 0,
 		Parent = track,
 	})
 	Util.Corner(thumb, BAR)
 	Theme.Bind(thumb, "BackgroundColor3", "TextMuted")

 	self.Container = container
 	self.Frame = frame
 	self.Content = content
 	self.Layout = layout
 	self.Scrollbar = track
 	self.Thumb = thumb
 	self.TopFade = topFade
 	self.BottomFade = bottomFade

 	local function setThumbTransparency(value)
 		Motion.Spring(thumb, "BackgroundTransparency", value, {
 			Stiffness = Config.Motion.Hover.Stiffness,
 			Damping = Config.Motion.Hover.Damping,
 		})
 	end

 	local fadeState = { top = false, bottom = false }

 	local function setFade(fade, key, visible)
 		if fadeState[key] == visible then
 			return
 		end

 		fadeState[key] = visible

 		Motion.Curve(fade, "BackgroundTransparency", visible and 0 or 1, {
 			Curve = "Glide",
 			Duration = 0.24,
 		})
 	end

 	--- Resolves the canvas size, the scrollbar geometry and the edge fades.
 	local function refresh()
 		local contentHeight = layout.AbsoluteContentSize.Y
 		content.Size = UDim2.new(1, -(padLeft + padRight), 0, contentHeight)
 		frame.CanvasSize = UDim2.new(0, 0, 0, contentHeight + padTop + padBottom)

 		local windowHeight = frame.AbsoluteWindowSize.Y
 		local canvasHeight = contentHeight + padTop + padBottom
 		local trackHeight = track.AbsoluteSize.Y
 		local position = frame.CanvasPosition.Y
 		local maximum = canvasHeight - windowHeight
 		local scrollable = trackHeight > 0 and canvasHeight > windowHeight + 1

 		if not scrollable then
 			track.Visible = false
 			setFade(topFade, "top", false)
 			setFade(bottomFade, "bottom", false)
 			return
 		end

 		track.Visible = true

 		local thumbHeight = math.max(28, trackHeight * (windowHeight / canvasHeight))
 		local travel = trackHeight - thumbHeight
 		local progress = maximum > 0 and (position / maximum) or 0

 		thumb.Size = UDim2.new(0, BAR, 0, thumbHeight)
 		thumb.Position = UDim2.new(0.5, 0, 0, Util.Clamp(progress, 0, 1) * travel)

 		setFade(topFade, "top", position > 4)
 		setFade(bottomFade, "bottom", maximum > 4 and position < maximum - 4)
 	end

 	self.Maid:Add(layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(refresh))
 	self.Maid:Add(frame:GetPropertyChangedSignal("AbsoluteCanvasSize"):Connect(refresh))
 	self.Maid:Add(frame:GetPropertyChangedSignal("CanvasPosition"):Connect(refresh))
 	self.Maid:Add(frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(refresh))

 	-- Scrollbar dragging.
 	local dragging = false
 	local pointerOrigin = 0
 	local thumbOrigin = 0
 	local moveConnection = nil

 	local function stopDragging()
 		dragging = false
 		if moveConnection then
 			moveConnection:Disconnect()
 			moveConnection = nil
 		end
 	end

 	track.InputBegan:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
 			return
 		end

 		local pointer = input.Position.Y
 		local thumbHeight = thumb.AbsoluteSize.Y
 		local travel = track.AbsoluteSize.Y - thumbHeight
 		if travel <= 0 then
 			return
 		end

 		if not Util.IsInside(thumb, Vector2.new(input.Position.X, pointer)) then
 			local localY = pointer - track.AbsolutePosition.Y
 			local target = Util.Clamp(localY - thumbHeight / 2, 0, travel)
 			local maximum = frame.AbsoluteCanvasSize.Y - frame.AbsoluteWindowSize.Y
 			if maximum > 0 then
 				frame.CanvasPosition = Vector2.new(0, target / travel * maximum)
 			end
 		end

 		dragging = true
 		pointerOrigin = pointer
 		thumbOrigin = thumb.Position.Y.Offset

 		local userInputService = game:GetService("UserInputService")
 		if moveConnection then
 			moveConnection:Disconnect()
 		end
 		moveConnection = userInputService.InputChanged:Connect(function(moved)
 			if not dragging then
 				return
 			end

 			local movedType = moved.UserInputType
 			if movedType ~= Enum.UserInputType.MouseMovement and movedType ~= Enum.UserInputType.Touch then
 				return
 			end

 			local position = Util.Clamp(thumbOrigin + (moved.Position.Y - pointerOrigin), 0, travel)
 			thumb.Position = UDim2.new(0.5, 0, 0, position)

 			local maximum = frame.AbsoluteCanvasSize.Y - frame.AbsoluteWindowSize.Y
 			if maximum > 0 then
 				frame.CanvasPosition = Vector2.new(0, position / travel * maximum)
 			end
 		end)
 	end)

 	track.InputEnded:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
 			stopDragging()
 		end
 	end)

 	local userInputService = game:GetService("UserInputService")
 	self.Maid:Add(userInputService.InputEnded:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
 			stopDragging()
 		end
 	end))

 	track.MouseEnter:Connect(function()
 		setThumbTransparency(0.15)
 	end)

 	track.MouseLeave:Connect(function()
 		setThumbTransparency(0.45)
 	end)

 	self.Maid:Add(stopDragging)
 	self._refresh = refresh

 	task.defer(refresh)

 	return self
 end

 --- Recomputes canvas size, scrollbar geometry and edge fades.
 function Scroll:Refresh()
 	self._refresh()
 end

 --- Scrolls to an absolute canvas offset.
 function Scroll:SetCanvasPositionY(value)
 	self.Frame.CanvasPosition = Vector2.new(0, value)
 end

 --- Scrolls the given instance into view.
 function Scroll:ScrollTo(instance)
 	local position = instance.AbsolutePosition.Y - self.Content.AbsolutePosition.Y
 	self.Frame.CanvasPosition = Vector2.new(0, math.max(0, position - 12))
 end

 function Scroll:Destroy()
 	self.Maid:Destroy()
 	self.Container:Destroy()
 end

 return Scroll
end

__modules["Core/Signal"] = function(script, require)
 --[[
 	Signal
 	A minimal synchronous event primitive. Handlers run in connection order and
 	receive the payload passed to Fire.
 ]]

 local Signal = {}
 Signal.__index = Signal

 local Connection = {}
 Connection.__index = Connection

 function Connection:Disconnect()
 	local handlers = self._handlers
 	if not handlers then
 		return
 	end

 	local index = table.find(handlers, self._handler)
 	if index then
 		table.remove(handlers, index)
 	end

 	self._handlers = nil
 	self._handler = nil
 end

 function Connection:Destroy()
 	self:Disconnect()
 end

 function Signal.new()
 	return setmetatable({ _handlers = {} }, Signal)
 end

 function Signal:Connect(handler)
 	assert(typeof(handler) == "function", "Signal:Connect expects a function")

 	table.insert(self._handlers, handler)

 	return setmetatable({ _handlers = self._handlers, _handler = handler }, Connection)
 end

 function Signal:Once(handler)
 	local connection
 	connection = self:Connect(function(...)
 		connection:Disconnect()
 		handler(...)
 	end)
 	return connection
 end

 function Signal:Fire(...)
 	-- Iterate a copy so handlers may disconnect themselves mid-fire.
 	local handlers = table.clone(self._handlers)

 	for index = 1, #handlers do
 		handlers[index](...)
 	end
 end

 function Signal:DisconnectAll()
 	table.clear(self._handlers)
 end

 function Signal:Destroy()
 	self:DisconnectAll()
 end

 return Signal
end

__modules["Core/Theme"] = function(script, require)
 --[[
 	Theme
 	Global color palette with live rebinding. Components never hardcode colors:
 	they either bind a property to a palette key or subscribe to Theme.Changed
 	for state dependent colors.
 ]]

 local Signal = require(script.Parent.Signal)
 local Util = require(script.Parent.Util)
 local Config = require(script.Parent.Config)

 local Theme = {}

 Theme.Changed = Signal.new()
 Theme.Palette = {}
 Theme.Name = "Dark"

 local PALETTES = {
 	Dark = {
 		Window = Color3.fromHex("0F1116"),
 		WindowGradient = Color3.fromHex("161A22"),
 		Topbar = Color3.fromHex("12151B"),
 		Sidebar = Color3.fromHex("0B0D12"),
 		Surface = Color3.fromHex("171A21"),
 		SurfaceHover = Color3.fromHex("1C2028"),
 		Control = Color3.fromHex("1F242E"),
 		ControlHover = Color3.fromHex("262C38"),
 		ControlActive = Color3.fromHex("2E3543"),
 		Outline = Color3.fromHex("262B35"),
 		OutlineSoft = Color3.fromHex("1E222B"),
 		Divider = Color3.fromHex("22262F"),
 		Text = Color3.fromHex("E8EBF0"),
 		TextMuted = Color3.fromHex("8B93A5"),
 		TextDim = Color3.fromHex("5C6474"),
 		Accent = Color3.fromHex("4C8DFF"),
 		AccentText = Color3.fromHex("FFFFFF"),
 		Success = Color3.fromHex("3FB950"),
 		Warning = Color3.fromHex("D8A657"),
 		Error = Color3.fromHex("F0616D"),
 		Shadow = Color3.fromHex("000000"),
 	},

 	Light = {
 		Window = Color3.fromHex("F4F5F8"),
 		WindowGradient = Color3.fromHex("FFFFFF"),
 		Topbar = Color3.fromHex("FFFFFF"),
 		Sidebar = Color3.fromHex("ECEEF3"),
 		Surface = Color3.fromHex("FFFFFF"),
 		SurfaceHover = Color3.fromHex("F2F4F8"),
 		Control = Color3.fromHex("EDEFF4"),
 		ControlHover = Color3.fromHex("E2E6ED"),
 		ControlActive = Color3.fromHex("D6DBE4"),
 		Outline = Color3.fromHex("DCE0E8"),
 		OutlineSoft = Color3.fromHex("E8EBF1"),
 		Divider = Color3.fromHex("E6E9EF"),
 		Text = Color3.fromHex("151920"),
 		TextMuted = Color3.fromHex("6B7385"),
 		TextDim = Color3.fromHex("9AA2B1"),
 		Accent = Color3.fromHex("2F6FED"),
 		AccentText = Color3.fromHex("FFFFFF"),
 		Success = Color3.fromHex("1F9D4D"),
 		Warning = Color3.fromHex("B4791A"),
 		Error = Color3.fromHex("D6404E"),
 		Shadow = Color3.fromHex("9AA2B1"),
 	},
 }

 Theme.Presets = table.freeze({ "Dark", "Light" })

 -- `bindings` is a hash set ([binding] = true) so a binding can be removed in
 -- O(1) when its Instance is destroyed. `lookup` maps Instance -> { [property] =
 -- binding }, which is what lets the destroy path find just that instance's
 -- bindings without scanning every binding in the process.
 local bindings = {}
 local lookup = setmetatable({}, { __mode = "k" })

 local function resolve(value)
 	if type(value) == "string" then
 		local color = Theme.Palette[value]
 		if color == nil then
 			warn(("[Lumen] unknown theme key %q"):format(value))
 		end
 		return color
 	end

 	return value
 end

 local function applyBindings()
 	for binding in pairs(bindings) do
 		local value = resolve(binding.Value)
 		if value ~= nil then
 			binding.Instance[binding.Property] = value
 		end
 	end
 end

 --- Keeps `property` of `instance` in sync with a palette key (or a literal).
 --- Binding the same property twice updates the existing entry, so state
 --- dependent colors never leave stale bindings behind.
 function Theme.Bind(instance, property, value)
 	local perInstance = lookup[instance]
 	if perInstance == nil then
 		perInstance = {}
 		lookup[instance] = perInstance

 		instance.Destroying:Connect(function()
 			lookup[instance] = nil

 			for _, binding in pairs(perInstance) do
 				bindings[binding] = nil
 			end
 			table.clear(perInstance)
 		end)
 	end

 	local binding = perInstance[property]
 	if binding then
 		binding.Value = value
 	else
 		binding = { Instance = instance, Property = property, Value = value }
 		perInstance[property] = binding
 		bindings[binding] = true
 	end

 	local resolved = resolve(value)
 	if resolved ~= nil then
 		instance[property] = resolved
 	end

 	return instance
 end

 --- Returns the current color for a palette key.
 function Theme.Get(key)
 	return Theme.Palette[key]
 end

 --- Returns a color blended towards the accent color.
 function Theme.AccentMix(alpha, base)
 	return Util.Mix(base or Theme.Palette.Window, Theme.Palette.Accent, alpha)
 end

 --- Switches the active palette. `accent` optionally overrides the accent color.
 function Theme.Set(name, accent)
 	local preset = PALETTES[name]
 	if preset == nil then
 		warn(("[Lumen] unknown theme %q, falling back to Dark"):format(tostring(name)))
 		preset = PALETTES.Dark
 		name = "Dark"
 	end

 	local palette = table.clone(preset)
 	if accent ~= nil then
 		palette.Accent = accent
 	end

 	palette.AccentSoft = Util.Mix(palette.Window, palette.Accent, 0.14)
 	palette.AccentFaint = Util.Mix(palette.Window, palette.Accent, 0.06)
 	palette.AccentDim = Util.Mix(palette.Window, palette.Accent, 0.45)

 	Theme.Name = name
 	Theme.Palette = palette

 	applyBindings()
 	Theme.Changed:Fire(palette)

 	return palette
 end

 --- Re-applies every binding, useful after mutating the palette in place.
 function Theme.Refresh()
 	applyBindings()
 	Theme.Changed:Fire(Theme.Palette)
 end

 Theme.Set(Config.DefaultTheme, Config.DefaultAccent)

 return Theme
end

__modules["Core/Util"] = function(script, require)
 --[[
 	Util
 	Instance construction, tweening, text measurement and pointer helpers shared
 	by every component in the library.
 ]]

 local TweenService = game:GetService("TweenService")
 local TextService = game:GetService("TextService")

 local Util = {}

 Util.Easing = {
 	Fast = TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
 	Default = TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
 	Slow = TweenInfo.new(0.36, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
 	Snappy = TweenInfo.new(0.26, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
 	Linear = TweenInfo.new(0.2, Enum.EasingStyle.Linear),
 }

 --- Creates an Instance and applies properties in one pass. `Parent` is always
 --- applied last so layouts settle once. An optional array of Instances is
 --- parented before the properties are written.
 function Util.Create(className, properties, children)
 	local instance = Instance.new(className)
 	local parent = nil

 	if properties then
 		for key, value in pairs(properties) do
 			if key == "Parent" then
 				parent = value
 			else
 				instance[key] = value
 			end
 		end
 	end

 	if children then
 		for index = 1, #children do
 			children[index].Parent = instance
 		end
 	end

 	if parent then
 		instance.Parent = parent
 	end

 	return instance
 end

 function Util.Corner(parent, radius)
 	return Util.Create("UICorner", {
 		CornerRadius = UDim.new(0, radius),
 		Parent = parent,
 	})
 end

 function Util.Stroke(parent, color, thickness, transparency)
 	return Util.Create("UIStroke", {
 		Color = color or Color3.new(0, 0, 0),
 		Thickness = thickness or 1,
 		Transparency = transparency or 0,
 		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
 		LineJoinMode = Enum.LineJoinMode.Round,
 		Parent = parent,
 	})
 end

 function Util.Padding(parent, top, right, bottom, left)
 	if type(top) == "table" then
 		local sides = top
 		top, right, bottom, left = sides.Top, sides.Right, sides.Bottom, sides.Left
 	end

 	if right == nil then
 		right, bottom, left = top, top, top
 	end

 	return Util.Create("UIPadding", {
 		PaddingTop = UDim.new(0, top or 0),
 		PaddingRight = UDim.new(0, right or 0),
 		PaddingBottom = UDim.new(0, bottom or 0),
 		PaddingLeft = UDim.new(0, left or 0),
 		Parent = parent,
 	})
 end

 function Util.Gradient(parent, colorSequence, rotation)
 	return Util.Create("UIGradient", {
 		Color = colorSequence,
 		Rotation = rotation or 0,
 		Parent = parent,
 	})
 end

 function Util.List(parent, padding, horizontal)
 	return Util.Create("UIListLayout", {
 		FillDirection = horizontal and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical,
 		SortOrder = Enum.SortOrder.LayoutOrder,
 		Padding = UDim.new(0, padding or 0),
 		Parent = parent,
 	})
 end

 function Util.Tween(instance, properties, info)
 	local tween = TweenService:Create(instance, info or Util.Easing.Default, properties)
 	tween:Play()
 	return tween
 end

 --- Adds an engine drop shadow when the client exposes UIShadow, otherwise
 --- returns nil so callers can fall back to a plain stroke.
 function Util.AddShadow(parent, color, options)
 	options = options or {}

 	local ok, shadow = pcall(Instance.new, "UIShadow")
 	if not ok or shadow == nil then
 		return nil
 	end

 	local function set(property, value)
 		pcall(function()
 			shadow[property] = value
 		end)
 	end

 	set("BlurRadius", UDim.new(0, options.Blur or 18))
 	set("Color", color or Color3.new(0, 0, 0))
 	set("Transparency", options.Transparency or 0.55)
 	set("Offset", UDim2.fromOffset(0, options.OffsetY or 6))
 	set("Spread", UDim2.fromOffset(0, 0))
 	set("ShowBehindParent", true)
 	set("Enabled", true)

 	shadow.Parent = parent

 	return shadow
 end

 function Util.Round(value, decimals)
 	local multiplier = 10 ^ (decimals or 0)
 	return math.floor(value * multiplier + 0.5) / multiplier
 end

 function Util.Clamp(value, minimum, maximum)
 	if value < minimum then
 		return minimum
 	elseif value > maximum then
 		return maximum
 	end
 	return value
 end

 --- Blends two colors. `alpha` of 0 returns `from`, 1 returns `to`.
 function Util.Mix(from, to, alpha)
 	return Color3.new(
 		from.R + (to.R - from.R) * alpha,
 		from.G + (to.G - from.G) * alpha,
 		from.B + (to.B - from.B) * alpha
 	)
 end

 --- Runs a user supplied callback without letting it tear down library internals.
 function Util.SafeCall(callback, ...)
 	if type(callback) ~= "function" then
 		return
 	end

 	local ok, err = pcall(callback, ...)
 	if not ok then
 		warn("[Lumen] callback error: " .. tostring(err))
 	end
 end

 function Util.MeasureText(text, size, font)
 	local bounds = TextService:GetTextSize(text, size, font, Vector2.new(1000, 100))
 	return bounds.X
 end

 --- Height of `text` once wrapped to `width` pixels.
 function Util.MeasureWrappedHeight(text, size, font, width)
 	local bounds = TextService:GetTextSize(text, size, font, Vector2.new(math.max(1, width), 1000))
 	return bounds.Y
 end

 function Util.IsInside(guiObject, point)
 	local position = guiObject.AbsolutePosition
 	local size = guiObject.AbsoluteSize

 	return point.X >= position.X
 		and point.X <= position.X + size.X
 		and point.Y >= position.Y
 		and point.Y <= position.Y + size.Y
 end

 local INPUT_NAMES = {
 	[Enum.UserInputType.MouseButton1] = "Mouse 1",
 	[Enum.UserInputType.MouseButton2] = "Mouse 2",
 	[Enum.UserInputType.MouseButton3] = "Mouse 3",
 	[Enum.UserInputType.MouseWheel] = "Wheel",
 	[Enum.UserInputType.Gamepad1] = "Gamepad 1",
 	[Enum.UserInputType.Touch] = "Touch",
 }

 --- Human readable label for a KeyCode or UserInputType.
 function Util.KeyName(value)
 	if typeof(value) ~= "EnumItem" then
 		return "None"
 	end

 	if value.EnumType == Enum.UserInputType then
 		return INPUT_NAMES[value] or value.Name
 	end

 	return value.Name
 end

 --- Makes `target` draggable by `handle`. Both mouse and touch input are
 --- supported; movement is delta based so GUI insets never skew the result.
 function Util.AttachDrag(target, handle, options)
 	options = options or {}
 	local dragging = false
 	local pointerOrigin = Vector2.zero
 	local positionOrigin = Vector2.zero
 	local moveConnection = nil

 	local userInputService = game:GetService("UserInputService")

 	local function viewportSize()
 		local camera = workspace.CurrentCamera
 		return camera and camera.ViewportSize or Vector2.new(1280, 720)
 	end

 	local function stopDragging()
 		dragging = false
 		if moveConnection then
 			moveConnection:Disconnect()
 			moveConnection = nil
 		end
 	end

 	local function onInputChanged(input)
 		if not dragging then
 			return
 		end

 		local inputType = input.UserInputType
 		if inputType ~= Enum.UserInputType.MouseMovement and inputType ~= Enum.UserInputType.Touch then
 			return
 		end

 		local pointer = Vector2.new(input.Position.X, input.Position.Y)
 		local delta = pointer - pointerOrigin
 		local position = positionOrigin + delta

 		if options.Clamp ~= false then
 			local viewport = viewportSize()
 			local scale = options.Scale and options.Scale() or 1
 			local size = target.AbsoluteSize
 			local titlebar = (options.TitlebarHeight or 0) * scale
 			local visibleTitlebar = math.min(size.X, (options.MinimumVisibleTitlebar or 0) * scale)
 			local minimum = Vector2.new(visibleTitlebar - size.X, 0)
 			local maximum = Vector2.new(viewport.X - visibleTitlebar, math.max(0, viewport.Y - titlebar))
 			position =
 				Vector2.new(Util.Clamp(position.X, minimum.X, maximum.X), Util.Clamp(position.Y, minimum.Y, maximum.Y))
 		end

 		target.Position = UDim2.fromOffset(position.X, position.Y)

 		if options.OnDrag then
 			options.OnDrag(position)
 		end
 	end

 	handle.Active = true
 	local beganConnection = handle.InputBegan:Connect(function(input)
 		if dragging then
 			return
 		end

 		local inputType = input.UserInputType
 		if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
 			return
 		end

 		dragging = true
 		pointerOrigin = Vector2.new(input.Position.X, input.Position.Y)
 		positionOrigin = Vector2.new(target.Position.X.Offset, target.Position.Y.Offset)

 		if options.OnDragStart then
 			options.OnDragStart()
 		end

 		if moveConnection then
 			moveConnection:Disconnect()
 		end
 		moveConnection = userInputService.InputChanged:Connect(onInputChanged)
 	end)

 	local function finishDragging()
 		if not dragging then
 			return
 		end

 		stopDragging()
 		if options.OnDragEnd then
 			options.OnDragEnd()
 		end
 	end

 	local endedConnection = handle.InputEnded:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
 			finishDragging()
 		end
 	end)

 	local releaseConnection = userInputService.InputEnded:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
 			finishDragging()
 		end
 	end)

 	return function()
 		stopDragging()
 		beganConnection:Disconnect()
 		endedConnection:Disconnect()
 		releaseConnection:Disconnect()
 	end
 end

 --- Makes `target` resizable by `handle`, growing towards the bottom right.
 function Util.AttachResize(target, handle, options)
 	options = options or {}
 	local resizing = false
 	local pointerOrigin = Vector2.zero
 	local sizeOrigin = Vector2.zero
 	local moveConnection = nil

 	local userInputService = game:GetService("UserInputService")
 	local minimum = options.Minimum or Vector2.new(360, 240)
 	local maximum = options.Maximum or Vector2.new(1440, 960)

 	local function stopResizing()
 		resizing = false
 		if moveConnection then
 			moveConnection:Disconnect()
 			moveConnection = nil
 		end
 	end

 	local function onInputChanged(input)
 		if not resizing then
 			return
 		end

 		local inputType = input.UserInputType
 		if inputType ~= Enum.UserInputType.MouseMovement and inputType ~= Enum.UserInputType.Touch then
 			return
 		end

 		local pointer = Vector2.new(input.Position.X, input.Position.Y)
 		-- Deltas arrive in screen pixels; the shell may be scaled by a UIScale.
 		local ratio = options.Scale and options.Scale() or 1
 		local delta = (pointer - pointerOrigin) / math.max(0.05, ratio)
 		local size = sizeOrigin + delta

 		local dynamicMaximum = options.MaximumForViewport and options.MaximumForViewport() or maximum
 		size = Vector2.new(
 			Util.Clamp(size.X, math.min(minimum.X, dynamicMaximum.X), dynamicMaximum.X),
 			Util.Clamp(size.Y, math.min(minimum.Y, dynamicMaximum.Y), dynamicMaximum.Y)
 		)

 		target.Size = UDim2.fromOffset(size.X, size.Y)

 		if options.OnResize then
 			options.OnResize(size)
 		end
 	end

 	handle.Active = true
 	local beganConnection = handle.InputBegan:Connect(function(input)
 		local inputType = input.UserInputType
 		if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then
 			return
 		end

 		resizing = true
 		pointerOrigin = Vector2.new(input.Position.X, input.Position.Y)
 		sizeOrigin = target.AbsoluteSize

 		if options.OnResizeStart then
 			options.OnResizeStart()
 		end

 		if moveConnection then
 			moveConnection:Disconnect()
 		end
 		moveConnection = userInputService.InputChanged:Connect(onInputChanged)
 	end)

 	local releaseConnection = userInputService.InputEnded:Connect(function(input)
 		if not resizing then
 			return
 		end

 		local inputType = input.UserInputType
 		if inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch then
 			stopResizing()
 			if options.OnResizeEnd then
 				options.OnResizeEnd()
 			end
 		end
 	end)

 	return function()
 		stopResizing()
 		beganConnection:Disconnect()
 		releaseConnection:Disconnect()
 	end
 end

 return Util
end

__modules["init"] = function(script, require)
 --[[
 	Lumen
 	A native Roblox interface library.

 		local Lumen = require(game:GetService("ReplicatedStorage").Lumen)

 		local window = Lumen:CreateWindow({ Title = "Lumen" })
 		local tab = window:Tab({ Name = "Main" })
 		local section = tab:Section({ Name = "General" })

 		section:Toggle({ Name = "Enabled", Callback = print })

 	Everything is built from stock Roblox instances: no images, no packages and
 	no external state. See README.md for the full component reference.
 ]]

 local Core = script.Core
 local Components = script.Components

 local Config = require(Core.Config)
 local Effects = require(Core.Effects)
 local Element = require(Core.Element)
 local Maid = require(Core.Maid)
 local Motion = require(Core.Motion)
 local Signal = require(Core.Signal)
 local Theme = require(Core.Theme)
 local Util = require(Core.Util)

 local Icon = require(Components.Icon)
 local Section = require(Components.Section)
 local Window = require(Components.Window)

 local Lumen = {}

 Lumen.Version = Config.Version
 Lumen.Config = Config
 Lumen.Theme = Theme
 Lumen.Motion = Motion
 Lumen.Effects = Effects
 Lumen.Signal = Signal
 Lumen.Maid = Maid
 Lumen.Util = Util
 Lumen.Icon = Icon
 Lumen.Element = Element
 Lumen.Section = Section

 local latestWindow = nil

 --- Creates a window. The most recent window receives Lumen:Notify calls.
 function Lumen:CreateWindow(options)
 	local window = Window.new(options)
 	latestWindow = window

 	window.DestroyedSignal:Connect(function()
 		if latestWindow == window then
 			latestWindow = nil
 		end
 	end)

 	return window
 end

 function Lumen.new(options)
 	return Lumen:CreateWindow(options)
 end

 --- Switches the palette ("Dark" or "Light") and optionally the accent color.
 function Lumen:SetTheme(name, accent)
 	return Theme.Set(name, accent)
 end

 function Lumen:GetTheme()
 	return Theme.Name
 end

 function Lumen:GetAccent()
 	return Theme.Palette.Accent
 end

 --- Pushes a notification through the latest window.
 function Lumen:Notify(options)
 	if latestWindow == nil then
 		warn("[Lumen] notify was called before any window was created")
 		return nil
 	end

 	return latestWindow:Notify(options)
 end

 --- Returns the latest window, if one is still alive.
 function Lumen:GetWindow()
 	return latestWindow
 end

 --- Turns animation on or off. Off applies every value instantly, which is the
 --- right call for a reduced motion accessibility setting.
 function Lumen:SetAnimations(enabled)
 	Motion.Reduced = enabled == false
 end

 function Lumen:GetAnimations()
 	return not Motion.Reduced
 end

 --- Current animation count, handy when profiling a heavy screen.
 function Lumen:GetActiveAnimations()
 	return Motion.ActiveCount()
 end

 return Lumen
end

local Lumen = __require(__root)

-- Expose the library so the interactive console can reach it.
local __getgenv = rawget(_G, "getgenv")
if type(__getgenv) == "function" then
	local ok, environment = pcall(__getgenv)
	if ok and type(environment) == "table" then
		environment.Lumen = Lumen
	end
else
	pcall(function()
		_G.Lumen = Lumen
	end)
end

return Lumen
